INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068dc817-95dd-4f0f-8f5e-820afe25e3bb', '建中癸亥歲奉天除夜宿武當山北茅平村', '建中癸亥歲奉天除夜宿武當山北茅平村', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["歲除日又暮，山險路仍新。","驅傳迷深谷，瞻星記北辰。","古亭聊假寐，中夜忽逢人。","相問皆嗚咽，傷心不待春。"]', '["歲除日又暮，山險路仍新。","驱傳迷深谷，瞻星記北辰。","古亭聊假寐，中夜忽逢人。","相问皆嗚咽，傷心不待春。"]', '诗', 'shi', '', NULL, '建中癸亥歲奉天除夜宿武當山北茅平村 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65156e09-c8f8-4bc2-b1f4-d03ffeed2745', '京口送皇甫司馬副端曾舒州辭滿歸去東都', '京口送皇甫司马副端曾舒州辞满归去东都', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["潮水忽復過，雲帆儼欲飛。","故園雙闕下，左宦十年歸。","晚景照華髮，涼風吹繡衣。","淹留更一醉，老去莫相違。"]', '["潮水忽复過，云帆儼欲飞。","故园雙闕下，左宦十年归。","晚景照华髮，涼风吹繡衣。","淹留更一醉，老去莫相違。"]', '诗', 'shi', '', NULL, '京口送皇甫司馬副端曾舒州辭滿歸去東都 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b092a7d9-645f-47fd-bd75-76119951262d', '送李審之桂州謁中丞叔', '送李審之桂州謁中丞叔', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["知音不可遇，才子向天涯。","遠水下山急，孤舟上路賒。","亂雲收暮雨，雜樹落疎花。","到日應文會，風流勝阮家。"]', '["知音不可遇，才子向天涯。","远水下山急，孤舟上路賒。","亂云收暮雨，杂樹落疎花。","到日應文會，风流勝阮家。"]', '诗', 'shi', '', NULL, '送李審之桂州謁中丞叔 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1fbadd-5082-41a9-8db7-1b9d192aca1e', '送王翁信及第歸江東舊隱', '送王翁信及第归江东旧隐', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["南行無俗侶，秋鴈與寒雲。","野趣自多愜，名香日總聞。","吳山中路斷，浙水半江分。","此地登臨慣，含情一送君。"]', '["南行無俗侶，秋鴈與寒云。","野趣自多愜，名香日總闻。","吳山中路斷，浙水半江分。","此地登臨慣，含情一送君。"]', '诗', 'shi', '', NULL, '送王翁信及第歸江東舊隱 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d91e133-3234-446a-a944-7919d532da99', '送李明府之任', '送李明府之任', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["身爲百里長，家寵五諸侯。","含笑聽猨狖，搖鞭望斗牛。","梅花堪比雪，芳草不知秋。","別後南風起，相思夢嶺頭。"]', '["身爲百里长，家寵五諸侯。","含笑听猨狖，搖鞭望斗牛。","梅花堪比雪，芳草不知秋。","別後南风起，相思梦嶺头。"]', '诗', 'shi', '', NULL, '送李明府之任 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eaab85d-aa2b-4496-9d1c-3fd448789934', '送郭太祝中孚歸江東', '送郭太祝中孚归江东', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鄉人去欲盡，北鴈又南飛。","京洛風塵久，江湖音信稀。","舊山知獨往，一醉莫相違。","未得辭羈旅，無勞問是非。"]', '["乡人去欲尽，北鴈又南飞。","京洛风塵久，江湖音信稀。","旧山知独往，一醉莫相違。","未得辞羈旅，無勞问是非。"]', '诗', 'shi', '', NULL, '送郭太祝中孚歸江東 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa29734b-2c9f-4347-8923-e403f0633077', '新秋夜寄江右友人', '新秋夜寄江右友人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["遙夜獨不寐，寂寥蓬戶中。","河明五陵上，月滿九門東。","舊知親友散，故園江海空。","懷歸正南望，此夕起秋風。"]', '["遙夜独不寐，寂寥蓬戶中。","河明五陵上，月满九门东。","旧知親友散，故园江海空。","懷归正南望，此夕起秋风。"]', '诗', 'shi', '', NULL, '新秋夜寄江右友人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de1320f-f293-4f10-846b-1059c07aaab8', '清明日送鄧芮二子還鄉', '清明日送鄧芮二子還乡', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鐘鼓喧離日，車徒促夜裝。","曉廚新變火，輕柳暗翻霜。","傳鏡看華髮，持杯話故鄉。","每嫌兒女淚，今日自霑裳。"]', '["鐘鼓喧離日，车徒促夜裝。","晓廚新变火，轻柳暗翻霜。","傳镜看华髮，持杯話故乡。","每嫌兒女泪，今日自霑裳。"]', '诗', 'shi', '', NULL, '清明日送鄧芮二子還鄉 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49cb64c-709b-4fc0-bf82-ee616cbdc070', '送謝夷甫宰餘姚縣', '送謝夷甫宰餘姚縣', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["君去方爲宰，干戈尚未銷。","邑中殘老小，亂後少官僚。","廨宇經兵火，公田沒海潮。","到時應變俗，新政滿餘姚。"]', '["君去方爲宰，干戈尚未銷。","邑中殘老小，亂後少官僚。","廨宇經兵火，公田沒海潮。","到时應变俗，新政满餘姚。"]', '诗', 'shi', '', NULL, '送謝夷甫宰餘姚縣 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f2a421-f439-45f3-9fe5-b9948368568e', '送柳道時余北還', '送柳道时余北還', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["征役各異路，煙波同旅愁。","輕橈上桂水，大艑下揚州。","何處成後會，今朝分舊遊。","離心比楊柳，蕭颯不勝秋。"]', '["征役各異路，煙波同旅愁。","轻橈上桂水，大艑下揚州。","何处成後會，今朝分旧游。","離心比楊柳，蕭颯不勝秋。"]', '诗', 'shi', '', NULL, '送柳道時余北還 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203982d6-d495-447c-ab81-0c07b54ff82a', '送萬戶曹之任揚州便歸舊隱', '送万戶曹之任揚州便归旧隐', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["擬歸雲壑去，聊寄宦名中。","俸祿資生事，文章實國風。","聽潮回楚浪，看月照隋宮。","儻有登樓望，還應伴庾公。"]', '["擬归云壑去，聊寄宦名中。","俸祿資生事，文章實国风。","听潮回楚浪，看月照隋宮。","儻有登楼望，還應伴庾公。"]', '诗', 'shi', '', NULL, '送萬戶曹之任揚州便歸舊隱 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('764f58af-f3ba-4bc1-af61-f85d4e7d1500', '送李長史縱之任常州', '送李长史縱之任常州', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["不與名利隔，且爲江漢遊。","吳山本佳麗，謝客舊淹留。","狹道通陵口，貧家住蔣州。","思歸復怨別，寥落詎關秋。"]', '["不與名利隔，且爲江漢游。","吳山本佳丽，謝客旧淹留。","狹道通陵口，貧家住蔣州。","思归复怨別，寥落詎关秋。"]', '诗', 'shi', '', NULL, '送李長史縱之任常州 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e474b107-4081-4a41-9cb9-e793f55b03fe', '南賓送蔡侍御遊蜀', '南賓送蔡侍御游蜀', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["巴江秋欲盡，遠別更淒然。","月照高唐峽，人隨賈客船。","積雲藏嶮路，流水促行年。","不料相逢日，空悲尊酒前。"]', '["巴江秋欲尽，远別更淒然。","月照高唐峽，人隨賈客船。","積云藏嶮路，流水促行年。","不料相逢日，空悲尊酒前。"]', '诗', 'shi', '', NULL, '南賓送蔡侍御遊蜀 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('499e451a-6e1f-4d38-8988-2231069d6fbb', '送崔拾遺峒江淮訪圖書', '送崔拾遺峒江淮訪圖书', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["九門思諫議，萬里採風謠。","關外逢秋月，天涯過晚潮。","鴈來雲杳杳，木落浦蕭蕭。","空怨他鄉別，迴舟暮寂寥。"]', '["九门思諫議，万里採风謠。","关外逢秋月，天涯過晚潮。","鴈来云杳杳，木落浦蕭蕭。","空怨他乡別，迴舟暮寂寥。"]', '诗', 'shi', '', NULL, '送崔拾遺峒江淮訪圖書 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e33ccd-cb7d-43a6-aec1-7fe7281d1859', '九日送洛陽李丞之任', '九日送洛陽李丞之任', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["爲文通絕境，從宦及良辰。","洛下知名早，腰邊結綬新。","且傾浮菊酒，聊拂染衣塵。","獨恨滄波侶，秋來別故人。"]', '["爲文通絕境，從宦及良辰。","洛下知名早，腰邊結綬新。","且傾浮菊酒，聊拂染衣塵。","独恨滄波侶，秋来別故人。"]', '诗', 'shi', '', NULL, '九日送洛陽李丞之任 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0419bd57-d2e1-4a94-a893-63b42eb0d986', '奉陪李大夫九日宴龍沙', '奉陪李大夫九日宴龙沙', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["邦君採菊地，近接旅人居。","一命招衰疾，清光照里閭。","去官慚比謝，下榻貴同徐。","莫怪沙邊倒，偏霑杯酌餘。"]', '["邦君採菊地，近接旅人居。","一命招衰疾，清光照里閭。","去官慚比謝，下榻貴同徐。","莫怪沙邊倒，偏霑杯酌餘。"]', '诗', 'shi', '', NULL, '奉陪李大夫九日宴龍沙 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64882e32-e727-47ef-be16-1218fa9dab76', '送車參軍江陵', '送车參軍江陵', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["槐花落盡柳陰清，蕭索涼天楚客情。","海上舊山無的信，東門歸路不堪行。","身隨幻境勞多事，跡學禪心厭有名。","公子道存知不棄，欲依劉表住南荆。"]', '["槐花落尽柳陰清，蕭索涼天楚客情。","海上旧山無的信，东门归路不堪行。","身隨幻境勞多事，跡学禪心厭有名。","公子道存知不棄，欲依劉表住南荆。"]', '诗', 'shi', '', NULL, '送車參軍江陵 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a321972-1f6e-4382-b373-bf3cc516f92c', '遊清溪蘭若', '游清溪蘭若', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["西看疊嶂幾千重，秀色孤標此一峰。","丹竈久閑荒宿草，碧溪深處有潛龍。","靈仙已去空巖室，到客唯聞古寺鐘。","遠對白雲幽隱在，年年不離舊杉松。"]', '["西看叠嶂幾千重，秀色孤標此一峰。","丹竈久闲荒宿草，碧溪深处有潛龙。","靈仙已去空巖室，到客唯闻古寺鐘。","远对白云幽隐在，年年不離旧杉松。"]', '诗', 'shi', '', NULL, '遊清溪蘭若 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d111558f-6992-4035-a2e1-e0df14c121b7', '贈史開府', '贈史开府', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["南天胡馬獨悲嘶，白首相逢話鼓鼙。","野戰頻年沙朔外，旌竿高與雪峰齊。","扁舟遠泛輕全楚，落日愁看舊紫泥。","早晚瑤階歸伏奏，獨能畫地取關西。"]', '["南天胡马独悲嘶，白首相逢話鼓鼙。","野戰頻年沙朔外，旌竿高與雪峰齊。","扁舟远泛轻全楚，落日愁看旧紫泥。","早晚瑤階归伏奏，独能畫地取关西。"]', '诗', 'shi', '', NULL, '贈史開府 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b63e28a-eabe-4695-b668-4d72e6e0713f', '登樓望月寄鳳翔李少尹', '登楼望月寄鳳翔李少尹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["陌上涼風槐葉凋，夕陽清露濕寒條。","登樓望月楚山迥，月到南樓山獨遙。","心送情人趨鳳闕，目隨陽鴈極煙霄。","軒轅不重無名客，此地還能訪寂寥。"]', '["陌上涼风槐葉凋，夕陽清露濕寒條。","登楼望月楚山迥，月到南楼山独遙。","心送情人趨鳳闕，目隨陽鴈極煙霄。","軒轅不重無名客，此地還能訪寂寥。"]', '诗', 'shi', '', NULL, '登樓望月寄鳳翔李少尹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b33b12-2a42-43b0-9327-b3b5cb7bf35b', '和汴州李相公勉人日喜春', '和汴州李相公勉人日喜春', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["年來日日春光好，今日春光好更新。","獨獻菜羹憐應節，遍傳金勝喜逢人。","煙添柳色看猶淺，鳥踏梅花落已頻。","東閤此時聞一曲，翻令和者不勝春。"]', '["年来日日春光好，今日春光好更新。","独獻菜羹怜應節，遍傳金勝喜逢人。","煙添柳色看猶淺，鸟踏梅花落已頻。","东閤此时闻一曲，翻令和者不勝春。"]', '诗', 'shi', '', NULL, '和汴州李相公勉人日喜春 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f04093a5-e41d-476f-9ff8-c23b3b7b540d', '奉酬盧端公飲後贈諸公見示之作', '奉酬盧端公饮後贈諸公见示之作', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["佐幕臨戎旌斾間，五營無事萬家閑。","風吹楊柳漸拂地，日映樓臺欲下山。","綺席晝開留上客，朱門半掩擬重關。","當時不敢辭先醉，誤逐羣公倒載還。"]', '["佐幕臨戎旌斾间，五營無事万家闲。","风吹楊柳漸拂地，日映楼台欲下山。","綺席晝开留上客，朱门半掩擬重关。","當时不敢辞先醉，誤逐羣公倒載還。"]', '诗', 'shi', '', NULL, '奉酬盧端公飲後贈諸公見示之作 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1fd9b73-7258-4449-9cb5-38ac9be815fa', '贈司空拾遺', '贈司空拾遺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["侍臣何事辭雲陛，江上彈冠見雪花。","望闕未承丹鳳詔，開門空對楚人家。","陳琳草奏才還在，王粲登樓興不賒。","高館更容塵外客，仍令歸去待瓊華。"]', '["侍臣何事辞云陛，江上彈冠见雪花。","望闕未承丹鳳詔，开门空对楚人家。","陳琳草奏才還在，王粲登楼兴不賒。","高館更容塵外客，仍令归去待瓊华。"]', '诗', 'shi', '', NULL, '贈司空拾遺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab185b82-5200-4a6d-a327-a21749e60981', '越溪村居', '越溪村居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["年來橈客寄禪扉，多話貧居在翠微。","黃雀數聲催柳變，清溪一路踏花歸。","空林野寺經過少，落日深山伴侶稀。","負米到家春未盡，風蘿閑掃釣魚磯。"]', '["年来橈客寄禪扉，多話貧居在翠微。","黄雀數声催柳变，清溪一路踏花归。","空林野寺經過少，落日深山伴侶稀。","負米到家春未尽，风蘿闲掃釣鱼磯。"]', '诗', 'shi', '', NULL, '越溪村居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3013337-5e2e-4fbb-ac96-c4d166c46d35', '贈韓道士', '贈韓道士', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["日暮秋風吹野花，上清歸客意無涯。","桃源寂寂煙霞閉，天路悠悠星漢斜。","還似世人生白髮，定知仙骨變黃芽。","東城南陌頻相見，應是壺中別有家。"]', '["日暮秋风吹野花，上清归客意無涯。","桃源寂寂煙霞閉，天路悠悠星漢斜。","還似世人生白髮，定知仙骨变黄芽。","东城南陌頻相见，應是壺中別有家。"]', '诗', 'shi', '', NULL, '贈韓道士 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223a80a9-26df-447d-bf07-7acd740fed42', '寄萬德躬故居', '寄万德躬故居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["日暮山風吹女蘿，故人舟楫定如何。","呂仙祠下寒砧急，帝子閣前秋水多。","閩海風塵鳴戍鼓，江湖煙雨暗漁蓑。","何時醉把黃花酒，聽爾南征長短歌。"]', '["日暮山风吹女蘿，故人舟楫定如何。","呂仙祠下寒砧急，帝子閣前秋水多。","閩海风塵鳴戍鼓，江湖煙雨暗漁蓑。","何时醉把黄花酒，听爾南征长短歌。"]', '诗', 'shi', '', NULL, '寄萬德躬故居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18801489-9f1d-4d5d-9618-66e682d3fc54', '寄司空曙', '寄司空曙', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["細雨柴門生遠愁，向來詩句若爲酬。","林花落處頻中酒，海燕飛時獨倚樓。","北郭晚晴山更遠，南塘春盡水爭流。","可能相別還相憶，莫遣楊花笑白頭。"]', '["細雨柴门生远愁，向来诗句若爲酬。","林花落处頻中酒，海燕飞时独倚楼。","北郭晚晴山更远，南塘春尽水爭流。","可能相別還相憶，莫遣楊花笑白头。"]', '诗', 'shi', '', NULL, '寄司空曙 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('205cafa9-5b98-4e70-8a6c-1543fbb08f35', '過故人陳羽山居', '過故人陳羽山居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["向來攜酒共追攀，此日看雲獨未還。","不見山中人半載，依然松下屋三間。","峰攢仙境丹霞上，水遶漁磯綠玉灣。","却望夏洋懷二妙，滿崖霜樹曉斑斑。"]', '["向来携酒共追攀，此日看云独未還。","不见山中人半載，依然松下屋三间。","峰攢仙境丹霞上，水遶漁磯綠玉灣。","却望夏洋懷二妙，满崖霜樹晓斑斑。"]', '诗', 'shi', '', NULL, '過故人陳羽山居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2855bd7a-82bb-4ff7-8b63-002876bef4bc', '弔暢當', '弔暢當', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["萬里江南一布衣，早將佳句動京畿。","徒聞子敬遺琴在，不見相如駟馬歸。","朔雪恐迷新冢草，秋風愁老故山薇。","玉堂知己能銘述，猶得精魂慰所依。"]', '["万里江南一布衣，早將佳句动京畿。","徒闻子敬遺琴在，不见相如駟马归。","朔雪恐迷新冢草，秋风愁老故山薇。","玉堂知己能銘述，猶得精魂慰所依。"]', '诗', 'shi', '', NULL, '弔暢當 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53055f71-d58b-42e6-bd79-a88eb44e79d8', '寄劉禹錫', '寄劉禹錫', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["謝相園西石徑斜，知君習隱暫爲家。","有時出郭行芳草，長日臨池看落花。","春去能忘詩共賦，客來應是酒頻賒。","五年不見西山色，悵望浮雲隱落霞。"]', '["謝相园西石徑斜，知君習隐暫爲家。","有时出郭行芳草，长日臨池看落花。","春去能忘诗共賦，客来應是酒頻賒。","五年不见西山色，悵望浮云隐落霞。"]', '诗', 'shi', '', NULL, '寄劉禹錫 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe8b080-6494-4279-9a7b-e6b4917fc51f', '寄孟郊', '寄孟郊', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["亂餘城郭怕經過，到處閑門長薜蘿。","用世空悲聞道淺，入山偏喜識僧多。","醉歸花徑雲生履，樵罷松巖雪滿蓑。","石上幽期春又暮，何時載酒聽高歌。"]', '["亂餘城郭怕經過，到处闲门长薜蘿。","用世空悲闻道淺，入山偏喜識僧多。","醉归花徑云生履，樵罷松巖雪满蓑。","石上幽期春又暮，何时載酒听高歌。"]', '诗', 'shi', '', NULL, '寄孟郊 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5774ddb1-5506-4a6c-8ab7-81c5d6a3d992', '贈徐山人', '贈徐山人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["亂餘山水半凋殘，江上逢君春正闌。","針自指南天窅窅，星猶拱北夜漫漫。","漢陵帝子黃金盌，晉代神仙白玉棺。","回首風塵千里外，故園煙雨五峰寒。"]', '["亂餘山水半凋殘，江上逢君春正闌。","針自指南天窅窅，星猶拱北夜漫漫。","漢陵帝子黄金盌，晉代神仙白玉棺。","回首风塵千里外，故园煙雨五峰寒。"]', '诗', 'shi', '', NULL, '贈徐山人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f8d32be-b8c6-45ea-8f07-96bf932592e7', '過賈誼舊居', '過賈誼旧居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["楚鄉卑濕歎殊方，鵩賦人非宅已荒。","謾有長書憂漢室，空將哀些弔沅湘。","雨餘古井生秋草，葉盡疎林見夕陽。","過客不須頻太息，咸陽宮殿亦淒涼。"]', '["楚乡卑濕歎殊方，鵩賦人非宅已荒。","謾有长书憂漢室，空將哀些弔沅湘。","雨餘古井生秋草，葉尽疎林见夕陽。","過客不須頻太息，咸陽宮殿亦淒涼。"]', '诗', 'shi', '', NULL, '過賈誼舊居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d37823-3437-4e99-961c-b4b9c99f7354', '宮詞', '宮词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["紫禁迢迢宮漏鳴，夜深無語獨含情。","春風鸞鏡愁中影，明月羊車夢裏聲。","塵暗玉堦綦跡斷，香飄金屋篆煙清。","貞心一任蛾眉妒，買賦何須問馬卿。"]', '["紫禁迢迢宮漏鳴，夜深無語独含情。","春风鸾镜愁中影，明月羊车梦裏声。","塵暗玉堦綦跡斷，香飄金屋篆煙清。","貞心一任蛾眉妒，買賦何須问马卿。"]', '诗', 'shi', '', NULL, '宮詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e46e210-631f-40d7-99be-8f5e1f21e1be', '漢宮人入道', '漢宮人入道', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["蕭蕭白髮出宮門，羽服星冠道意存。","霄漢九重辭鳳闕，雲山何處訪桃源。","瑤池醉月勞仙夢，玉輦乘春却帝恩。","回首吹簫天上伴，上陽花落共誰言。"]', '["蕭蕭白髮出宮门，羽服星冠道意存。","霄漢九重辞鳳闕，云山何处訪桃源。","瑤池醉月勞仙梦，玉輦乘春却帝恩。","回首吹簫天上伴，上陽花落共誰言。"]', '诗', 'shi', '', NULL, '漢宮人入道 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f6ebbf-396a-4980-bbf1-0c14d80d384d', '二靈寺守歲', '二靈寺守歲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["守歲山房迥絕緣，燈光香灺共蕭然。","無人更獻椒花頌，有客同參栢子禪。","已悟化城非樂界，不知今夕是何年。","憂心悄悄渾忘寐，坐待扶桑日麗天。"]', '["守歲山房迥絕緣，灯光香灺共蕭然。","無人更獻椒花頌，有客同參栢子禪。","已悟化城非乐界，不知今夕是何年。","憂心悄悄渾忘寐，坐待扶桑日丽天。"]', '诗', 'shi', '', NULL, '二靈寺守歲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfdfe676-a556-40c1-b250-d9e935a39a63', '暮春感懷 一', '暮春感懷 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["杜宇聲聲喚客愁，故園何處此登樓。","落花飛絮成春夢，賸水殘山異昔遊。","歌扇多情明月在，舞衣無意綵雲收。","東皇去後韶華盡，老圃寒香別有秋。"]', '["杜宇声声喚客愁，故园何处此登楼。","落花飞絮成春梦，賸水殘山異昔游。","歌扇多情明月在，舞衣無意綵云收。","东皇去後韶华尽，老圃寒香別有秋。"]', '诗', 'shi', '', NULL, '暮春感懷 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66255fc9-0ccd-4d15-90a4-e44f0c4ce0f6', '暮春感懷 二', '暮春感懷 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["四十無聞嬾慢身，放情丘壑任天真。","悠悠往事杯中物，赫赫時名扇外塵。","短策看雲松寺晚，疎簾聽雨草堂春。","山花水鳥皆知己，百遍相過不厭貧。"]', '["四十無闻嬾慢身，放情丘壑任天真。","悠悠往事杯中物，赫赫时名扇外塵。","短策看云松寺晚，疎簾听雨草堂春。","山花水鸟皆知己，百遍相過不厭貧。"]', '诗', 'shi', '', NULL, '暮春感懷 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c197e13-7039-48a1-97c1-63a8e56d0f85', '哭朱放', '哭朱放', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["幾年湖海挹餘芳，豈料蘭摧一夜霜。","人世空傳名耿耿，泉臺杳隔路茫茫。","碧窗月落琴聲斷，華表雲深鶴夢長。","最是不堪回首處，九泉煙冷樹蒼蒼。"]', '["幾年湖海挹餘芳，豈料蘭摧一夜霜。","人世空傳名耿耿，泉台杳隔路茫茫。","碧窗月落琴声斷，华表云深鹤梦长。","最是不堪回首处，九泉煙冷樹蒼蒼。"]', '诗', 'shi', '', NULL, '哭朱放 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8502e6fa-f283-440a-a69a-12bb1b54610f', '酬盩厔耿少府湋見寄', '酬盩厔耿少府湋见寄', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["方丈蕭蕭落葉中，暮天深巷起悲風。","流年不盡人自老，外事無端心已空。","家近小山當海畔，身留環衞蔭牆東。","遙聞相訪頻逢雪，一醉寒宵誰與同。"]', '["方丈蕭蕭落葉中，暮天深巷起悲风。","流年不尽人自老，外事無端心已空。","家近小山當海畔，身留环衞蔭牆东。","遙闻相訪頻逢雪，一醉寒宵誰與同。"]', '诗', 'shi', '', NULL, '酬盩厔耿少府湋見寄 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f75b5345-5fc9-44f2-b547-de2b3ffc8e97', '贈慧上人', '贈慧上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["仙槎江口槎溪寺，幾度停舟訪未能。","自恨頻年爲遠客，喜從異郡識高僧。","雲霞色釅禪房衲，星月光涵古殿燈。","何日却飛真錫返，故人丘木翳寒藤。"]', '["仙槎江口槎溪寺，幾度停舟訪未能。","自恨頻年爲远客，喜從異郡識高僧。","云霞色釅禪房衲，星月光涵古殿灯。","何日却飞真錫返，故人丘木翳寒藤。"]', '诗', 'shi', '', NULL, '贈慧上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae41a4c9-251d-44ff-8f20-f1056c90c087', '漸至涪州先寄王員外使君縱', '漸至涪州先寄王員外使君縱', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["文教通夷俗，均輸問火田。","江分巴字水，樹入夜郎煙。","毒瘴含秋氣，陰崖蔽曙天。","路難空計日，身老不由年。","將命寧知遠，歸心詎可傳。","星郎復何意，出守五溪邊。"]', '["文教通夷俗，均輸问火田。","江分巴字水，樹入夜郎煙。","毒瘴含秋氣，陰崖蔽曙天。","路难空計日，身老不由年。","將命寧知远，归心詎可傳。","星郎复何意，出守五溪邊。"]', '诗', 'shi', '', NULL, '漸至涪州先寄王員外使君縱 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4362e4-b3a8-442b-a272-f9b96f2e37ed', '和河南羅主簿送校書兄歸江南', '和河南羅主簿送校书兄归江南', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["兄弟泣殊方，天涯指故鄉。","斷雲無定處，歸鴈不成行。","草莽人煙少，風波水驛長。","上虞親渤澥，東楚隔瀟湘。","古戍陰傳火，寒蕪曉帶霜。","海門潮灩灩，沙岸荻蒼蒼。","京輦辭芸閣，蘅芳憶草堂。","知君始寧隱，還緝舊荷裳。"]', '["兄弟泣殊方，天涯指故乡。","斷云無定处，归鴈不成行。","草莽人煙少，风波水驛长。","上虞親渤澥，东楚隔瀟湘。","古戍陰傳火，寒蕪晓带霜。","海门潮灩灩，沙岸荻蒼蒼。","京輦辞芸閣，蘅芳憶草堂。","知君始寧隐，還緝旧荷裳。"]', '诗', 'shi', '', NULL, '和河南羅主簿送校書兄歸江南 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9ca09f-e8e7-48a5-94a5-ec8ec6c99667', '曉聞長樂鐘聲', '晓闻长乐鐘声', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["漢苑鐘聲早，秦郊曙色分。","霜凌萬戶徹，風散一城聞。","已啓蓬萊殿，初朝鴛鷺羣。","虛心方應物，大扣欲干雲。","近雜雞人唱，新傳鳧氏文。","能令翰苑客，流聽思氛氳。"]', '["漢苑鐘声早，秦郊曙色分。","霜凌万戶徹，风散一城闻。","已啓蓬萊殿，初朝鴛鷺羣。","虛心方應物，大扣欲干云。","近杂雞人唱，新傳鳧氏文。","能令翰苑客，流听思氛氳。"]', '诗', 'shi', '', NULL, '曉聞長樂鐘聲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2666a3f9-aa59-4476-bb0b-0af3357d8d87', '聽霜鐘', '听霜鐘', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["渺渺飛霜夜，寥寥遠岫鐘。","出雲疑斷續，入戶乍舂容。","度枕頻驚夢，隨風幾韻松。","悠揚來不已，杳靄去何從。","髣髴煙嵐隔，依稀巖嶠重。","此時聊一聽，餘響繞千峰。"]', '["渺渺飞霜夜，寥寥远岫鐘。","出云疑斷續，入戶乍舂容。","度枕頻驚梦，隨风幾韻松。","悠揚来不已，杳靄去何從。","髣髴煙嵐隔，依稀巖嶠重。","此时聊一听，餘响繞千峰。"]', '诗', 'shi', '', NULL, '聽霜鐘 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f145a5d-ead7-40dc-88a8-217f5bf05e38', '聽霜鐘', '听霜鐘', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["寥亮來豐嶺，分明辨古鐘。","應霜如自擊，中節每相從。","靜聽非閑扣，潛應蘊聖蹤。","風間時斷續，雲外更舂容。","虛警和清籟，雄鳴隔亂峰。","因知諭知己，感激更難逢。"]', '["寥亮来豐嶺，分明辨古鐘。","應霜如自擊，中節每相從。","静听非闲扣，潛應蘊聖蹤。","风间时斷續，云外更舂容。","虛警和清籟，雄鳴隔亂峰。","因知諭知己，感激更难逢。"]', '诗', 'shi', '', NULL, '聽霜鐘 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ee422a-e77c-494c-b5c7-75b5a7fa9833', '酬崔法曹遺劒', '酬崔法曹遺劒', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["臨風脫佩劒，相勸靜胡塵。","自料無筋力，何由荅故人。"]', '["臨风脫佩劒，相勸静胡塵。","自料無筋力，何由荅故人。"]', '诗', 'shi', '', NULL, '酬崔法曹遺劒 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f3e233-70e4-49fd-bb09-c6a0a54f7d4e', '敬報孫常州二首 一', '敬報孫常州二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["衰病苦奔走，未嘗追舊遊。","何言問憔悴，此日駐方舟。"]', '["衰病苦奔走，未嘗追旧游。","何言问憔悴，此日駐方舟。"]', '诗', 'shi', '', NULL, '敬報孫常州二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9449155-5986-4467-8e84-30e5205e3f1e', '敬報孫常州二首 二', '敬報孫常州二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["遠道曳故屐，餘春會高齋。","因言別離久，得盡平生懷。"]', '["远道曳故屐，餘春會高斋。","因言別離久，得尽平生懷。"]', '诗', 'shi', '', NULL, '敬報孫常州二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ade326-5aeb-4d54-b7f3-cb1351a5e23e', '將赴東陽留上包諫議', '將赴东陽留上包諫議', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["敝邑連山遠，仙舟數刻同。","多慚屢回首，前路在泥中。"]', '["敝邑連山远，仙舟數刻同。","多慚屢回首，前路在泥中。"]', '诗', 'shi', '', NULL, '將赴東陽留上包諫議 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a91b39-3990-4eba-b4ef-86f3eca64ce8', '荅崔法曹', '荅崔法曹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["後會知不遠，今歡亦願留。","江天梅雨散，況在月中樓。"]', '["後會知不远，今歡亦願留。","江天梅雨散，況在月中楼。"]', '诗', 'shi', '', NULL, '荅崔法曹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13ca9e2-3f3d-4065-b001-6b5ff7e36dcc', '問嚴居士易', '问嚴居士易', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["自公來問易，不復待加年。","更有垂簾會，遙知續草玄。"]', '["自公来问易，不复待加年。","更有垂簾會，遙知續草玄。"]', '诗', 'shi', '', NULL, '問嚴居士易 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b750e80a-f2d3-4197-b1cb-45c9e7251ddd', '新年第二夜荅處上人宿玉芝觀見寄', '新年第二夜荅处上人宿玉芝观见寄', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["陽春已三日，會友聞昨夜。","可愛剡溪僧，獨尋陶景舍。"]', '["陽春已三日，會友闻昨夜。","可愛剡溪僧，独尋陶景舍。"]', '诗', 'shi', '', NULL, '新年第二夜荅處上人宿玉芝觀見寄 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3335bee1-90a8-4998-9731-c11a8fce0597', '赴撫州對酬崔法曹夜雨滴空堦五首 一', '赴撫州对酬崔法曹夜雨滴空堦五首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["雨落濕孤客，心驚比棲鳥。","空階夜滴繁，相亂應到曉。"]', '["雨落濕孤客，心驚比棲鸟。","空階夜滴繁，相亂應到晓。"]', '诗', 'shi', '', NULL, '赴撫州對酬崔法曹夜雨滴空堦五首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c189006-aefd-4e4f-bdcc-3393aa34f56a', '赴撫州對酬崔法曹夜雨滴空堦五首 二', '赴撫州对酬崔法曹夜雨滴空堦五首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["高會棗樹宅，清言蓮社僧。","兩鄉同夜雨，旅館又無燈。"]', '["高會棗樹宅，清言蓮社僧。","兩乡同夜雨，旅館又無灯。"]', '诗', 'shi', '', NULL, '赴撫州對酬崔法曹夜雨滴空堦五首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e83d27-9a83-4eb6-b348-333bc281c2b9', '赴撫州對酬崔法曹夜雨滴空堦五首 三', '赴撫州对酬崔法曹夜雨滴空堦五首 三', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["謗議不自辨，親朋那得知。","雨中驅馬去，非是獨傷離。"]', '["謗議不自辨，親朋那得知。","雨中驱马去，非是独傷離。"]', '诗', 'shi', '', NULL, '赴撫州對酬崔法曹夜雨滴空堦五首 三 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e91df9f-dc79-4657-a431-44a6378b0ecd', '赴撫州對酬崔法曹夜雨滴空堦五首 四', '赴撫州对酬崔法曹夜雨滴空堦五首 四', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["離室雨初晦，客程雲陡暗。","方爲對吏人，敢望郵童探。"]', '["離室雨初晦，客程云陡暗。","方爲对吏人，敢望郵童探。"]', '诗', 'shi', '', NULL, '赴撫州對酬崔法曹夜雨滴空堦五首 四 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9fa19f8-6e21-460a-a1ad-ad0272328262', '赴撫州對酬崔法曹夜雨滴空堦五首 五', '赴撫州对酬崔法曹夜雨滴空堦五首 五', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["縱酒常擲盞，狂歌時入室。","離羣怨雨聲，幽抑方成疾。"]', '["縱酒常擲盞，狂歌时入室。","離羣怨雨声，幽抑方成疾。"]', '诗', 'shi', '', NULL, '赴撫州對酬崔法曹夜雨滴空堦五首 五 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d7f53c-9631-4849-9975-4887c7e0fb61', '又酬曉燈[離暗]室五首 一', '又酬晓灯[離暗]室五首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["知疑姦叟謗，閑與情人話。","猶是別時燈，不眠同此夜。"]', '["知疑姦叟謗，闲與情人話。","猶是別时灯，不眠同此夜。"]', '诗', 'shi', '', NULL, '又酬曉燈[離暗]室五首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9715a2f1-2b9f-459e-9d0d-36e9c5b78544', '又酬曉燈[離暗]室五首 二', '又酬晓灯[離暗]室五首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["寒燈揚曉焰，重屋驚春雨。","應想遠行人，路逢泥濘阻。"]', '["寒灯揚晓焰，重屋驚春雨。","應想远行人，路逢泥濘阻。"]', '诗', 'shi', '', NULL, '又酬曉燈[離暗]室五首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf8623a-3c01-4bea-94cd-663e6b2a2f76', '又酬曉燈[離暗]室五首 三', '又酬晓灯[離暗]室五首 三', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["燈光照虛屋，雨影懸空壁。","一向簷下聲，遠來愁處滴。"]', '["灯光照虛屋，雨影懸空壁。","一向簷下声，远来愁处滴。"]', '诗', 'shi', '', NULL, '又酬曉燈[離暗]室五首 三 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f71946-f5ac-4789-a750-6af2337a11b8', '又酬曉燈[離暗]室五首 四', '又酬晓灯[離暗]室五首 四', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["楚僧話寂滅，俗慮比虛空。","賴有殘燈喻，相傳昏暗中。"]', '["楚僧話寂滅，俗慮比虛空。","賴有殘灯喻，相傳昏暗中。"]', '诗', 'shi', '', NULL, '又酬曉燈[離暗]室五首 四 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb3ddaff-b685-4259-b956-5cf875608319', '又酬曉燈[離暗]室五首 五', '又酬晓灯[離暗]室五首 五', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["雨聲亂燈影，明滅在空堦。","併枉五言贈，知同萬里懷。"]', '["雨声亂灯影，明滅在空堦。","併枉五言贈，知同万里懷。"]', '诗', 'shi', '', NULL, '又酬曉燈[離暗]室五首 五 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7614ca20-733c-4ff3-a655-3c8ea0d498ef', '同賦龍沙墅', '同賦龙沙墅', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["回轉沙岸近，欹斜林嶺重。","因君訪遺跡，此日見真龍。"]', '["回轉沙岸近，欹斜林嶺重。","因君訪遺跡，此日见真龙。"]', '诗', 'shi', '', NULL, '同賦龍沙墅 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd8b7c0-3d74-4cb0-8980-3dcd5a265a30', '昭君詞', '昭君词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["漢宮若遠近，路在寒沙上。","到死不得歸，何人共南望。"]', '["漢宮若远近，路在寒沙上。","到死不得归，何人共南望。"]', '诗', 'shi', '', NULL, '昭君詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9017db43-e553-41c6-8e41-faec2e570bc5', '勸陸三飲酒', '勸陸三饮酒', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["寒郊好天氣，勸酒莫辭頻。","擾擾鍾陵市，無窮不醉人。"]', '["寒郊好天氣，勸酒莫辞頻。","擾擾鍾陵市，無窮不醉人。"]', '诗', 'shi', '', NULL, '勸陸三飲酒 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16616009-65cd-4aca-9fa7-d811bc47da08', '關山月二首 一', '关山月二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["月出照關山，秋風人未還。","清光無遠近，鄉淚半書間。"]', '["月出照关山，秋风人未還。","清光無远近，乡泪半书间。"]', '诗', 'shi', '', NULL, '關山月二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01898455-f8ad-437f-b6b7-e85557bcdc22', '關山月二首 二', '关山月二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["一鴈過連營，繁霜覆古城。","胡笳在何處，半夜起邊聲。"]', '["一鴈過連營，繁霜覆古城。","胡笳在何处，半夜起邊声。"]', '诗', 'shi', '', NULL, '關山月二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c5d728-c508-4eb6-ab70-b3bda8705e74', '送王司直', '送王司直', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["西塞雲山遠，東風道路長。","人心勝潮水，相送過潯陽。"]', '["西塞云山远，东风道路长。","人心勝潮水，相送過潯陽。"]', '诗', 'shi', '', NULL, '送王司直 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f43418-33bc-4f98-899b-0685366eea5e', '宿無可上人房', '宿無可上人房', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["偶來人境外，何處染囂塵。","倘許棲林下，僧中老此身。"]', '["偶来人境外，何处染囂塵。","倘許棲林下，僧中老此身。"]', '诗', 'shi', '', NULL, '宿無可上人房 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a46701-7f8e-4fda-af01-a547f34e1961', '山居', '山居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["麋鹿自成羣，何人到白雲。","山中無外事，終日醉醺醺。"]', '["麋鹿自成羣，何人到白云。","山中無外事，終日醉醺醺。"]', '诗', 'shi', '', NULL, '山居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151e3f4f-cb2b-4bf1-bd53-800f2185e4d1', '口號', '口號', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["白髮千莖雪，寒窗嬾著書。","最憐吟苜蓿，不及向桑榆。"]', '["白髮千莖雪，寒窗嬾著书。","最怜吟苜蓿，不及向桑榆。"]', '诗', 'shi', '', NULL, '口號 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4a4c891-c602-4085-86e2-78b7678059e1', '夜坐', '夜坐', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["夜靜河漢高，獨坐庭前月。","忽起故園思，動作經年別。"]', '["夜静河漢高，独坐庭前月。","忽起故园思，动作經年別。"]', '诗', 'shi', '', NULL, '夜坐 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0dfd8f-821c-40ce-b802-251e56eb1ed3', '隄上柳', '隄上柳', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["垂柳萬條絲，春來織別離。","行人攀折處，閨妾斷腸時。"]', '["垂柳万條絲，春来织別離。","行人攀折处，閨妾斷腸时。"]', '诗', 'shi', '', NULL, '隄上柳 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec2a7d3-28e5-4dc8-b9e9-7c4e160ac871', '遣興', '遣兴', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["明月臨滄海，閑雲戀故山。","詩名滿天下，終日掩柴關。"]', '["明月臨滄海，闲云戀故山。","诗名满天下，終日掩柴关。"]', '诗', 'shi', '', NULL, '遣興 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e341327a-fb05-44d4-b771-6d22bd4cc7e5', '贈張揮使', '贈張揮使', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["謫戍孤城小，思家萬里遙。","漢廷求衞霍，劒佩上青霄。"]', '["謫戍孤城小，思家万里遙。","漢廷求衞霍，劒佩上青霄。"]', '诗', 'shi', '', NULL, '贈張揮使 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec7585c2-b556-44ce-9536-4ab29f138ed1', '偶成', '偶成', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["野水連天碧，峯巒入海青。","滄浪者誰子，一曲醉中聽。"]', '["野水連天碧，峯巒入海青。","滄浪者誰子，一曲醉中听。"]', '诗', 'shi', '', NULL, '偶成 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4166f66-36ab-4fe1-ab8b-87bae3cf862c', '畫蟬', '畫蟬', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["飲露身何潔，吟風韻更長。","斜陽千萬樹，無處避螳螂。"]', '["饮露身何潔，吟风韻更长。","斜陽千万樹，無处避螳螂。"]', '诗', 'shi', '', NULL, '畫蟬 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('095b716b-89b6-4ecc-a3f9-7ffa0bd688d4', '題天柱山圖', '題天柱山圖', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["拔翠五雲中，擎天不計功。","誰能凌絕頂，看取日升東。"]', '["拔翠五云中，擎天不計功。","誰能凌絕頂，看取日升东。"]', '诗', 'shi', '', NULL, '題天柱山圖 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a012f579-47b8-4b62-a91b-6792bb94ae53', '松鶴', '松鹤', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["雨濕松陰涼，風落松花細。","獨鶴愛清幽，飛來不飛去。"]', '["雨濕松陰涼，风落松花細。","独鹤愛清幽，飞来不飞去。"]', '诗', 'shi', '', NULL, '松鶴 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('181e032c-d33f-449e-a589-92402eb757c9', '草堂一上人', '草堂一上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["一公持一鉢，相復度遙岑。","地瘦無黃獨，春來草更深。"]', '["一公持一鉢，相复度遙岑。","地瘦無黄独，春来草更深。"]', '诗', 'shi', '', NULL, '草堂一上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dbe219f-270f-4ad6-aec7-6f15ae73ad70', '題黃司直園', '題黄司直园', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["爲憶去年梅，凌寒特地來。","門前空臘盡，渾未有花開。"]', '["爲憶去年梅，凌寒特地来。","门前空臘尽，渾未有花开。"]', '诗', 'shi', '', NULL, '題黃司直園 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1464676a-cfac-4c42-8e13-c578e0a54d43', '北山游亭', '北山游亭', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["西崦水泠泠，沿岡有游亭。","自從春草長，遙見祗青青。"]', '["西崦水泠泠，沿岡有游亭。","自從春草长，遙见祗青青。"]', '诗', 'shi', '', NULL, '北山游亭 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1feb3681-6f79-4a9d-ae12-5b826046cac1', '贈李唐山人', '贈李唐山人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["此意無所欲，閉門風景遲。","柳條將白髮，相對共垂絲。"]', '["此意無所欲，閉门风景遲。","柳條將白髮，相对共垂絲。"]', '诗', 'shi', '', NULL, '贈李唐山人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc44f781-f0bb-4947-bf2b-92e0e1275f32', '題秦隱君麗句亭', '題秦隐君丽句亭', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["北人歸欲盡，猶自住蕭山。","閉戶不曾出，詩名滿世間。"]', '["北人归欲尽，猶自住蕭山。","閉戶不曾出，诗名满世间。"]', '诗', 'shi', '', NULL, '題秦隱君麗句亭 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48cb12c-8c93-46f0-ae68-fed69e1fefbe', '荅孫常州見憶', '荅孫常州见憶', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["畫鷁春風裏，迢遙去若飛。","那能寄相憶，不並子猷歸。"]', '["畫鷁春风裏，迢遙去若飞。","那能寄相憶，不並子猷归。"]', '诗', 'shi', '', NULL, '荅孫常州見憶 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba16449e-a278-49cf-9605-e772c7b68422', '送裴明州效南朝體', '送裴明州效南朝體', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["沅水連湘水，千波萬浪中。","知郎未得去，慚愧石尤風。"]', '["沅水連湘水，千波万浪中。","知郎未得去，慚愧石尤风。"]', '诗', 'shi', '', NULL, '送裴明州效南朝體 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3265b08-784b-400b-8fe7-d1654c0d22b8', '戲留顧十一明府', '戲留顧十一明府', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["江明雨初歇，山暗雲猶濕。","未可動歸橈，前程風浪急。"]', '["江明雨初歇，山暗云猶濕。","未可动归橈，前程风浪急。"]', '诗', 'shi', '', NULL, '戲留顧十一明府 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffbd4e81-ebc5-4248-97f3-e94a33ac9515', '荅崔載華', '荅崔載华', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["文案日成堆，愁眉拽不開。","偷歸甕間臥，逢箇楚狂來。"]', '["文案日成堆，愁眉拽不开。","偷归甕间臥，逢箇楚狂来。"]', '诗', 'shi', '', NULL, '荅崔載華 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10cef41f-2e8b-43fc-a431-038760d73e2c', '將赴行營勸客同醉', '將赴行營勸客同醉', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["絲管霜天夜，煙塵淮水西。","明朝上征去，相伴醉如泥。"]', '["絲管霜天夜，煙塵淮水西。","明朝上征去，相伴醉如泥。"]', '诗', 'shi', '', NULL, '將赴行營勸客同醉 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0503020d-c7e8-4119-9a83-4ef5d033c95c', '夏夜江樓會別', '夏夜江楼會別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["不作十日別，煩君此相留。","雨餘江上月，好醉竹間樓。"]', '["不作十日別，煩君此相留。","雨餘江上月，好醉竹间楼。"]', '诗', 'shi', '', NULL, '夏夜江樓會別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e8b1a9f-037f-4f95-94e3-4287c2a9787a', '歲除日奉推事使牒追赴撫州辨對留別崔法曹陸大祝處士上人同賦人字口號', '歲除日奉推事使牒追赴撫州辨对留別崔法曹陸大祝处士上人同賦人字口號', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["上國杳未到，流年忽復新。","回車不自識，君定送何人。"]', '["上国杳未到，流年忽复新。","回车不自識，君定送何人。"]', '诗', 'shi', '', NULL, '歲除日奉推事使牒追赴撫州辨對留別崔法曹陸大祝處士上人同賦人字口號 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342ebc9b-77af-46b5-83c7-efb01c730cd5', '江館會別', '江館會別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["離亭一會宿，能有幾人同。","莫以回車泣，前途不盡窮。"]', '["離亭一會宿，能有幾人同。","莫以回车泣，前途不尽窮。"]', '诗', 'shi', '', NULL, '江館會別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6619ba-ece3-45e4-b611-6b0286c4c757', '容州回逢陸三別', '容州回逢陸三別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["西南積水遠，老病喜生歸。","此地故人別，空餘淚滿衣。"]', '["西南積水远，老病喜生归。","此地故人別，空餘泪满衣。"]', '诗', 'shi', '', NULL, '容州回逢陸三別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb56b65-a89a-4545-81d5-9e17c4ec5eb1', '古意寄呈王侍郎', '古意寄呈王侍郎', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["夜光貯懷袖，待報一顧恩。","日向江湖老，此心誰爲論。"]', '["夜光貯懷袖，待報一顧恩。","日向江湖老，此心誰爲論。"]', '诗', 'shi', '', NULL, '古意寄呈王侍郎 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d87de2c-bb6e-4f15-8c07-939d2702df0a', '送李大夫渡口阻風', '送李大夫渡口阻风', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["浪息定何時，龍門到恐遲。","輕舟不敢渡，空立望旌旗。"]', '["浪息定何时，龙门到恐遲。","轻舟不敢渡，空立望旌旗。"]', '诗', 'shi', '', NULL, '送李大夫渡口阻風 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29e2e73-54f2-418a-9500-f80a9c2469f4', '過三閭廟', '過三閭廟', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["沅湘流不盡，屈宋怨何深。","日暮秋煙起，蕭蕭楓樹林。"]', '["沅湘流不尽，屈宋怨何深。","日暮秋煙起，蕭蕭楓樹林。"]', '诗', 'shi', '', NULL, '過三閭廟 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc5e46e-0187-4441-9d65-d5cad1963221', '泊湘口', '泊湘口', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["湘山千嶺樹，桂水九秋波。","露重猨聲絕，風清月色多。"]', '["湘山千嶺樹，桂水九秋波。","露重猨声絕，风清月色多。"]', '诗', 'shi', '', NULL, '泊湘口 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9456a92c-9b5c-4f9b-a337-06e8430002e2', '遊道林寺', '游道林寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["佳山路不遠，俗侶到常稀。","及此煙霞暮，相看復欲歸。"]', '["佳山路不远，俗侶到常稀。","及此煙霞暮，相看复欲归。"]', '诗', 'shi', '', NULL, '遊道林寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d81a50e-1fbc-4d98-a353-342eea5beb08', '後宮曲', '後宮曲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["初入長門宮，謂言君戲妾。","寧知秋風至，吹盡庭前葉。"]', '["初入长门宮，謂言君戲妾。","寧知秋风至，吹尽庭前葉。"]', '诗', 'shi', '', NULL, '後宮曲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d02f1f30-2f7d-4cf4-984d-949d076945b9', '新別離', '新別離', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["手把杏花枝，未曾經別離。","黃昏掩閨後，寂寞心自知。"]', '["手把杏花枝，未曾經別離。","黄昏掩閨後，寂寞心自知。"]', '诗', 'shi', '', NULL, '新別離 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51193855-3efa-4dbd-a880-c2fd13710fb2', '夏日登鶴巖偶成', '夏日登鹤巖偶成', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["天風吹我上層岡，露灑長松六月涼。","願借老僧雙白鶴，碧雲深處共翺翔。"]', '["天风吹我上層岡，露灑长松六月涼。","願借老僧雙白鹤，碧云深处共翺翔。"]', '诗', 'shi', '', NULL, '夏日登鶴巖偶成 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879f798d-fdd9-40f4-beec-e538bb5c323c', '題淨居寺', '題淨居寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["玉壺山下雲居寺，六百年來選佛場。","滿地白雲關不住，石泉流出落花香。"]', '["玉壺山下云居寺，六百年来選佛場。","满地白云关不住，石泉流出落花香。"]', '诗', 'shi', '', NULL, '題淨居寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('410b1ce2-d6b3-4791-8b76-dba1a74bd8a2', '昭君詞', '昭君词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["漢家宮闕夢中歸，幾度氈房淚濕衣。","惆悵不如邊鴈影，秋風猶得向南飛。"]', '["漢家宮闕梦中归，幾度氈房泪濕衣。","惆悵不如邊鴈影，秋风猶得向南飞。"]', '诗', 'shi', '', NULL, '昭君詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b301d20a-9934-4e51-bada-c92bd451baaf', '織女詞', '织女词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鳳梭停織鵲無音，夢憶仙郎夜夜心。","難得相逢容易別，銀河爭似妾愁深。"]', '["鳳梭停织鵲無音，梦憶仙郎夜夜心。","难得相逢容易別，銀河爭似妾愁深。"]', '诗', 'shi', '', NULL, '織女詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcc0053-11c4-438e-bbc6-28f2e4b9d747', '塞上曲二首 一', '塞上曲二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["軍門頻納受降書，一劒橫行萬里餘。","漢祖謾夸婁敬策，卻將公主嫁單于。"]', '["軍门頻納受降书，一劒橫行万里餘。","漢祖謾夸婁敬策，卻將公主嫁單于。"]', '诗', 'shi', '', NULL, '塞上曲二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ebcb4d-63b0-485b-8ba3-bb6f6963454c', '塞上曲二首 二', '塞上曲二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["漢家旌幟滿陰山，不遣胡兒匹馬還。","願得此身長報國，何須生入玉門關。"]', '["漢家旌幟满陰山，不遣胡兒匹马還。","願得此身长報国，何須生入玉门关。"]', '诗', 'shi', '', NULL, '塞上曲二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('336e74f9-e5ed-4fa4-a931-999115318f0f', '閨怨', '閨怨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["看花無語淚如傾，多少春風怨別情。","不識玉門關外路，夢中昨夜到邊城。"]', '["看花無語泪如傾，多少春风怨別情。","不識玉门关外路，梦中昨夜到邊城。"]', '诗', 'shi', '', NULL, '閨怨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e8c917b-58b6-457a-93ed-321716012ea3', '春怨', '春怨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["金鴨香消欲斷魂，棃花春雨掩重門。","欲知別後相思意，回看羅衣積淚痕。"]', '["金鴨香消欲斷魂，棃花春雨掩重门。","欲知別後相思意，回看羅衣積泪痕。"]', '诗', 'shi', '', NULL, '春怨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1810673f-87d3-40de-85d7-a69cc48c984c', '旅次寄湖南張郎中', '旅次寄湖南張郎中', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["閉門茅底偶爲鄰，北阮那憐南阮貧。","却是梅花無世態，隔牆分送一枝春。"]', '["閉门茅底偶爲鄰，北阮那怜南阮貧。","却是梅花無世態，隔牆分送一枝春。"]', '诗', 'shi', '', NULL, '旅次寄湖南張郎中 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c4f5a9-2d33-416e-aa32-9a614bb534f1', '題友人山居', '題友人山居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["四郭青山處處同，客懷無計荅秋風。","數家茅屋清溪上，千樹蟬聲落日中。"]', '["四郭青山处处同，客懷無計荅秋风。","數家茅屋清溪上，千樹蟬声落日中。"]', '诗', 'shi', '', NULL, '題友人山居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72caa839-845e-4846-bf12-d9b9c21330c0', '別鄭谷', '別鄭谷', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["朝陽齋前桃李樹，手栽清蔭接比鄰。","明年此地看花發，愁向東風憶故人。"]', '["朝陽斋前桃李樹，手栽清蔭接比鄰。","明年此地看花發，愁向东风憶故人。"]', '诗', 'shi', '', NULL, '別鄭谷 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74ff7e4-fc01-4353-a1b6-59ce8cd98458', '贈鶴林上人', '贈鹤林上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["日日澗邊尋茯苓，巖扉常掩鳳山青。","歸來挂衲高林下，自翦芭蕉寫佛經。"]', '["日日澗邊尋茯苓，巖扉常掩鳳山青。","归来挂衲高林下，自翦芭蕉寫佛經。"]', '诗', 'shi', '', NULL, '贈鶴林上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d569368-a596-40d9-bb8d-994f5c3cfe5c', '題稚川山水', '題稚川山水', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["松下茅亭五月涼，汀沙雲樹晚蒼蒼。","行人無限秋風思，隔水青山似故鄉。"]', '["松下茅亭五月涼，汀沙云樹晚蒼蒼。","行人無限秋风思，隔水青山似故乡。"]', '诗', 'shi', '', NULL, '題稚川山水 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3979821a-6f07-41ad-9625-f9a4b76d9108', '過柳溪道院', '過柳溪道院', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["溪上誰家掩竹扉，鳥啼渾似惜春暉。","日斜深巷無人跡，時見棃花片片飛。"]', '["溪上誰家掩竹扉，鸟啼渾似惜春暉。","日斜深巷無人跡，时见棃花片片飞。"]', '诗', 'shi', '', NULL, '過柳溪道院 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e80e40-6e8c-4f7c-8d6f-7e7d58cccb98', '荔枝', '荔枝', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["紅顆真珠誠可愛，白鬚太守亦何癡。","十年結子知誰在，自向中庭種荔枝。"]', '["紅顆真珠誠可愛，白鬚太守亦何癡。","十年結子知誰在，自向中庭種荔枝。"]', '诗', 'shi', '', NULL, '荔枝 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e139b304-059d-4eb4-9312-56e13d45aa39', '憶原上人', '憶原上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["一兩棕鞋八尺藤，廣陵行遍又金陵。","不知竹雨竹風夜，吟對秋山那寺燈。"]', '["一兩棕鞋八尺藤，廣陵行遍又金陵。","不知竹雨竹风夜，吟对秋山那寺灯。"]', '诗', 'shi', '', NULL, '憶原上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40967ba9-1b4c-4999-8b47-fe33249523fd', '閑思', '闲思', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["伯勞東去鶴西還，雲總無心亦度山。","何似嚴陵灘上客，一竿長伴白鷗閑。"]', '["伯勞东去鹤西還，云總無心亦度山。","何似嚴陵灘上客，一竿长伴白鷗闲。"]', '诗', 'shi', '', NULL, '閑思 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d505c716-3ba6-4a6d-aa72-805acad7b350', '蘭溪棹歌', '蘭溪棹歌', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["涼月如眉挂柳灣，越中山色鏡中看。","蘭溪三日桃花雨，半夜鯉魚來上灘。"]', '["涼月如眉挂柳灣，越中山色镜中看。","蘭溪三日桃花雨，半夜鯉鱼来上灘。"]', '诗', 'shi', '', NULL, '蘭溪棹歌 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d34018-cfa7-4547-b70f-dba7b6b0a51b', '蘇溪亭', '蘇溪亭', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["蘇溪亭上草漫漫，誰倚東風十二闌。","燕子不歸春事晚，一汀煙雨杏花寒。"]', '["蘇溪亭上草漫漫，誰倚东风十二闌。","燕子不归春事晚，一汀煙雨杏花寒。"]', '诗', 'shi', '', NULL, '蘇溪亭 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('722c97e2-8499-433f-a18b-67402dcce9c6', '敬酬陸山人二首 一', '敬酬陸山人二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["黨議連誅不可聞，直臣高士去紛紛。","當時漏奪無人問，出宰東陽笑殺君。"]', '["黨議連誅不可闻，直臣高士去紛紛。","當时漏奪無人问，出宰东陽笑殺君。"]', '诗', 'shi', '', NULL, '敬酬陸山人二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b51d4f3-15c4-4722-b936-9467d467cdaa', '敬酬陸山人二首 二', '敬酬陸山人二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["由來海畔逐樵漁，奉詔因乘使者車。","却掌山中子男印，自看猶是舊潛夫。"]', '["由来海畔逐樵漁，奉詔因乘使者车。","却掌山中子男印，自看猶是旧潛夫。"]', '诗', 'shi', '', NULL, '敬酬陸山人二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd187bd-b264-4cc4-877a-9791f9d8e302', '荅崔法曹賦四雪', '荅崔法曹賦四雪', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["楚僧躡雪來招隱，先訪高人積雪中。","已別剡溪逢雪去，雪山修道與師同。"]', '["楚僧躡雪来招隐，先訪高人積雪中。","已別剡溪逢雪去，雪山修道與師同。"]', '诗', 'shi', '', NULL, '荅崔法曹賦四雪 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed0c3d5-5117-4167-865f-2ed676f178ed', '撫州被推昭雪荅陸太祝三首 一', '撫州被推昭雪荅陸太祝三首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["求理由來許便宜，漢朝龔遂不爲疵。","如今謗起翻成累，唯有新人子細知。"]', '["求理由来許便宜，漢朝龔遂不爲疵。","如今謗起翻成累，唯有新人子細知。"]', '诗', 'shi', '', NULL, '撫州被推昭雪荅陸太祝三首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d76ba9-dcd8-4fe8-9f56-c9546472b3a6', '撫州被推昭雪荅陸太祝三首 二', '撫州被推昭雪荅陸太祝三首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["貧交相愛果無疑，共向人間聽直詞。","從古以來何限枉，慚知暗室不曾欺。"]', '["貧交相愛果無疑，共向人间听直词。","從古以来何限枉，慚知暗室不曾欺。"]', '诗', 'shi', '', NULL, '撫州被推昭雪荅陸太祝三首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd56b00-f9a0-490c-b3ae-262f704ba596', '撫州被推昭雪荅陸太祝三首 三', '撫州被推昭雪荅陸太祝三首 三', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["春風旅館長庭蕪，俯首低眉一老夫。","已對鐵冠窮事本，不知廷尉念冤無。"]', '["春风旅館长庭蕪，俯首低眉一老夫。","已对鐵冠窮事本，不知廷尉念冤無。"]', '诗', 'shi', '', NULL, '撫州被推昭雪荅陸太祝三首 三 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1da34c-2be0-485b-bead-81a1911e840e', '送獨孤𢘽還京', '送独孤𢘽還京', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["舉家相逐還鄉去，不向秋風怨別時。","湖水兩重山萬里，定知行盡到京師。"]', '["舉家相逐還乡去，不向秋风怨別时。","湖水兩重山万里，定知行尽到京師。"]', '诗', 'shi', '', NULL, '送獨孤𢘽還京 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('770a0170-ad29-4655-ab97-d06e71cb76ea', '臨流送顧東陽', '臨流送顧东陽', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["海上獨歸慚不及，邑中遺愛定無雙。","蘭橈起唱逐流去，却恨山溪通外江。"]', '["海上独归慚不及，邑中遺愛定無雙。","蘭橈起唱逐流去，却恨山溪通外江。"]', '诗', 'shi', '', NULL, '臨流送顧東陽 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa637bf1-eb04-411f-8171-c5bfadb32805', '行營送馬侍御', '行營送马侍御', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["萬里羽書來未絕，五關烽火晝仍傳。","故人多病盡歸去，唯有劉楨不得眠。"]', '["万里羽书来未絕，五关烽火晝仍傳。","故人多病尽归去，唯有劉楨不得眠。"]', '诗', 'shi', '', NULL, '行營送馬侍御 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c5a2ba4-4609-4c96-8022-23ca17b0e46f', '送秦系', '送秦系', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["五都來往無舊業，一代公卿盡故人。","不肯低頭受羈束，遠師溪上拂纓塵。"]', '["五都来往無旧業，一代公卿尽故人。","不肯低头受羈束，远師溪上拂纓塵。"]', '诗', 'shi', '', NULL, '送秦系 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e2e5ca-c2d3-4a74-889c-5187d67fb5e4', '送裴判官回湖南', '送裴判官回湖南', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["莫怕南風且盡歡，湘山多雨夏中寒。","送君萬里不覺遠，此地曾爲心鐵官。"]', '["莫怕南风且尽歡，湘山多雨夏中寒。","送君万里不覺远，此地曾爲心鐵官。"]', '诗', 'shi', '', NULL, '送裴判官回湖南 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b17513-9627-4dae-9779-c2df11a7007e', '再巡道永留別', '再巡道永留別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鬢下初驚白髮時，更逢離別助秋悲。","從今不學四方事，已共家人海上期。"]', '["鬢下初驚白髮时，更逢離別助秋悲。","從今不学四方事，已共家人海上期。"]', '诗', 'shi', '', NULL, '再巡道永留別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd2ad8c-e1cd-4b4e-afb2-8464e20188d2', '別崔法曹', '別崔法曹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["欲作別離西入秦，芝田棗逕往來頻。","東湖此夕更留醉，逢著廬山學道人。"]', '["欲作別離西入秦，芝田棗逕往来頻。","东湖此夕更留醉，逢著廬山学道人。"]', '诗', 'shi', '', NULL, '別崔法曹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff11599-0092-414d-a759-a18078140df7', '送蕭二', '送蕭二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["擬向田間老此身，寒郊怨別甚於春。","又聞故里朋遊盡，到日知逢何處人。"]', '["擬向田间老此身，寒郊怨別甚於春。","又闻故里朋游尽，到日知逢何处人。"]', '诗', 'shi', '', NULL, '送蕭二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cd7fe9c-61e1-4421-a500-4f22ebd7e494', '湘川野望', '湘川野望', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["懷王獨與佞人謀，聞道忠臣入亂流。","今日登高望不見，楚雲湘水各悠悠。"]', '["懷王独與佞人謀，闻道忠臣入亂流。","今日登高望不见，楚云湘水各悠悠。"]', '诗', 'shi', '', NULL, '湘川野望 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8693c8-135b-43a0-ac7d-5dadfd9980d8', '將至道州寄李使君', '將至道州寄李使君', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["九疑深路遶山回，木落天清猨晝哀。","猶隔簫韶一峯在，遙傳五馬向東來。"]', '["九疑深路遶山回，木落天清猨晝哀。","猶隔簫韶一峯在，遙傳五马向东来。"]', '诗', 'shi', '', NULL, '將至道州寄李使君 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a4b12f1-b33b-4b6a-91b4-41d96a59dbf3', '與虞沔州謁藏真上人', '與虞沔州謁藏真上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["故侯將我到山中，更上西峯見遠公。","共問置心何處好，主人揮手指虛空。"]', '["故侯將我到山中，更上西峯见远公。","共问置心何处好，主人揮手指虛空。"]', '诗', 'shi', '', NULL, '與虞沔州謁藏真上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5f7a070-808f-45b7-ab66-4bdcd7a562e0', '題招隱寺', '題招隐寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["昨日臨川謝病還，求田問舍獨相關。","宋時有井如今在，却種胡麻不買山。"]', '["昨日臨川謝病還，求田问舍独相关。","宋时有井如今在，却種胡麻不買山。"]', '诗', 'shi', '', NULL, '題招隱寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0271a9ee-1faa-4b35-b9d4-c6c3b47127b6', '過珥瀆單老', '過珥瀆單老', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["毫末成圍海變田，單家依舊住溪邊。","比來已向人間老，今日相過却少年。"]', '["毫末成圍海变田，單家依旧住溪邊。","比来已向人间老，今日相過却少年。"]', '诗', 'shi', '', NULL, '過珥瀆單老 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9038c3e7-8bce-44ce-a133-a63b7335e5bb', '族兄各年八十餘見招游洞', '族兄各年八十餘见招游洞', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鶴髮婆娑鄉里親，相邀共看往年春。","擬將兒女歸來住，且是茅山見老人。"]', '["鹤髮婆娑乡里親，相邀共看往年春。","擬將兒女归来住，且是茅山见老人。"]', '诗', 'shi', '', NULL, '族兄各年八十餘見招游洞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5707de8e-3b74-44f2-a67d-4743b9c1597f', '登高回乘月尋僧', '登高回乘月尋僧', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["插鬢茱萸來未盡，共隨明月下沙堆。","高緇寂寂不相問，醉客無端入定來。"]', '["插鬢茱萸来未尽，共隨明月下沙堆。","高緇寂寂不相问，醉客無端入定来。"]', '诗', 'shi', '', NULL, '登高回乘月尋僧 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82d0171-3f18-4888-b953-0bbb51a1023f', '贈殷亮', '贈殷亮', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["日日河邊見水流，傷春未已復悲秋。","山中舊宅無人住，來往風塵共白頭。"]', '["日日河邊见水流，傷春未已复悲秋。","山中旧宅無人住，来往风塵共白头。"]', '诗', 'shi', '', NULL, '贈殷亮 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f1531af-037e-4ca4-8d56-834b2167eed9', '夜發袁江寄李潁川劉侍御', '夜發袁江寄李潁川劉侍御', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["半夜回舟入楚鄉，月明山水共蒼蒼。","孤猨更叫秋風裏，不是愁人亦斷腸。"]', '["半夜回舟入楚乡，月明山水共蒼蒼。","孤猨更叫秋风裏，不是愁人亦斷腸。"]', '诗', 'shi', '', NULL, '夜發袁江寄李潁川劉侍御 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f0c60b4-819f-4141-b19f-b3e34a02ee97', '對酒示申屠學士', '对酒示申屠学士', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["三重江水萬重山，山裏春風度日閑。","且向白雲求一醉，莫教愁夢到鄉關。"]', '["三重江水万重山，山裏春风度日闲。","且向白云求一醉，莫教愁梦到乡关。"]', '诗', 'shi', '', NULL, '對酒示申屠學士 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c81f68-1a2a-403b-a030-109b8041ecc1', '對月荅袁明府', '对月荅袁明府', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["山下孤城月上遲，相留一醉本無期。","明年此夕遊何處，縱有清光知對誰。"]', '["山下孤城月上遲，相留一醉本無期。","明年此夕游何处，縱有清光知对誰。"]', '诗', 'shi', '', NULL, '對月荅袁明府 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e764d6e6-d554-4374-9726-0e7264ee616b', '送前上饒嚴明府攝玉山', '送前上饒嚴明府攝玉山', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["家在故林吳楚間，冰爲溪水玉爲山。","更將舊政化鄰邑，遙見逋人相逐還。"]', '["家在故林吳楚间，冰爲溪水玉爲山。","更將旧政化鄰邑，遙见逋人相逐還。"]', '诗', 'shi', '', NULL, '送前上饒嚴明府攝玉山 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481f61cc-a1a2-44a2-96ca-583a9347bdfe', '聽歌回馬上贈崔法曹', '听歌回马上贈崔法曹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["秋風裏許杏花開，杏樹傍邊醉客來。","共待夜深聽一曲，醒人騎馬斷腸迴。"]', '["秋风裏許杏花开，杏樹傍邊醉客来。","共待夜深听一曲，醒人騎马斷腸迴。"]', '诗', 'shi', '', NULL, '聽歌回馬上贈崔法曹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4f925a-9a24-437e-b334-3415f5585988', '酬駱侍御荅詩', '酬駱侍御荅诗', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["風傳畫閣空知曉，雨濕江城不見春。","堆案遶牀君莫怪，已經愁思古時人。"]', '["风傳畫閣空知晓，雨濕江城不见春。","堆案遶牀君莫怪，已經愁思古时人。"]', '诗', 'shi', '', NULL, '酬駱侍御荅詩 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79036bb6-752d-474c-a130-0ff60d73853a', '送孫直遊郴州', '送孫直游郴州', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["孤舟上水過湘沅，桂嶺南枝花正繁。","行客自知心有托，不聞驚浪與啼猨。"]', '["孤舟上水過湘沅，桂嶺南枝花正繁。","行客自知心有托，不闻驚浪與啼猨。"]', '诗', 'shi', '', NULL, '送孫直遊郴州 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e733ce3-0c15-4cf7-a71c-dccfddc7092a', '麓山寺會送尹秀才', '麓山寺會送尹秀才', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["湖上逢君亦不閑，暫將離別到深山。","飄蓬驚鳥那自定，強欲相留雲樹間。"]', '["湖上逢君亦不闲，暫將離別到深山。","飄蓬驚鸟那自定，強欲相留云樹间。"]', '诗', 'shi', '', NULL, '麓山寺會送尹秀才 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01796277-e2e7-4050-8305-d1b82afd532e', '送董頲', '送董頲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["霜鴈羣飛下楚田，羈人掩淚望秦天。","君行江海無定所，別後相思何處邊。"]', '["霜鴈羣飞下楚田，羈人掩泪望秦天。","君行江海無定所，別後相思何处邊。"]', '诗', 'shi', '', NULL, '送董頲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc2c19f-a20a-4405-b4e7-5a1b2f75cf03', '別張員外', '別張員外', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["木葉紛紛湘水濱，此中何事往頻頻。","臨風自笑歸時晚，更送浮雲逐故人。"]', '["木葉紛紛湘水濱，此中何事往頻頻。","臨风自笑归时晚，更送浮云逐故人。"]', '诗', 'shi', '', NULL, '別張員外 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2c8227-421c-470d-8d69-5bfe9ccefea7', '送張評事', '送張評事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["城郭喧喧爭送遠，危梁褭褭渡東津。","楊花展轉引征騎，莫怪山中多看人。"]', '["城郭喧喧爭送远，危梁褭褭渡东津。","楊花展轉引征騎，莫怪山中多看人。"]', '诗', 'shi', '', NULL, '送張評事 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab9c97e-e1ee-42f8-9ddd-06b5c5f4fff0', '送呂少府', '送呂少府', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["共醉流芳獨歸去，故園高士日相親。","深山古路無楊柳，折取桐花寄遠人。"]', '["共醉流芳独归去，故园高士日相親。","深山古路無楊柳，折取桐花寄远人。"]', '诗', 'shi', '', NULL, '送呂少府 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd101d7-645d-46b0-a793-e1844ad764c7', '送人游嶺南', '送人游嶺南', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["少別華陽萬里遊，近南風景不曾秋。","紅芳綠筍是行路，縱有啼猨聽却幽。"]', '["少別华陽万里游，近南风景不曾秋。","紅芳綠筍是行路，縱有啼猨听却幽。"]', '诗', 'shi', '', NULL, '送人游嶺南 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9170ad6d-98f7-48eb-a960-b9c4f8cae0b4', '妻亡後別妻弟', '妻亡後別妻弟', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["楊柳青青滿路垂，贈行惟折古松枝。","停舟一對湘江哭，哭罷無言君自知。"]', '["楊柳青青满路垂，贈行惟折古松枝。","停舟一对湘江哭，哭罷無言君自知。"]', '诗', 'shi', '', NULL, '妻亡後別妻弟 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb12c44-575d-4e7c-b3f2-25ffba4f5fcd', '和崔法曹建溪聞猨', '和崔法曹建溪闻猨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["曾向巫山峽裏行，羈猨一叫一回驚。","聞道建溪腸欲斷，的知斷著第三聲。"]', '["曾向巫山峽裏行，羈猨一叫一回驚。","闻道建溪腸欲斷，的知斷著第三声。"]', '诗', 'shi', '', NULL, '和崔法曹建溪聞猨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6215cc8f-11df-4617-bd87-4f33001a07ba', '湘南即事', '湘南即事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["盧橘花開楓葉衰，出門何處望京師。","沅湘日夜東流去，不爲愁人住少時。"]', '["盧橘花开楓葉衰，出门何处望京師。","沅湘日夜东流去，不爲愁人住少时。"]', '诗', 'shi', '', NULL, '湘南即事 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c68b88-d4bb-4236-b648-f13c8d810344', '代書寄京洛舊遊', '代书寄京洛旧游', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["今年十月溫風起，湘水悠悠生白蘋。","欲寄遠書還不敢，却愁驚動故鄉人。"]', '["今年十月溫风起，湘水悠悠生白蘋。","欲寄远书還不敢，却愁驚动故乡人。"]', '诗', 'shi', '', NULL, '代書寄京洛舊遊 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245e85be-c3f9-425d-a685-e3a54f755583', '蘄州行營作', '蘄州行營作', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["蘄水城西向北看，桃花落盡柳花殘。","朱旗半捲山川小，白馬連嘶草樹寒。"]', '["蘄水城西向北看，桃花落尽柳花殘。","朱旗半捲山川小，白马連嘶草樹寒。"]', '诗', 'shi', '', NULL, '蘄州行營作 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb68fac8-4200-4362-88b3-76ba0792b853', '題武當逸禪師蘭若', '題武當逸禪師蘭若', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["我身本似遠行客，況是亂時多病身。","經山涉水向何處，羞見竹林禪定人。"]', '["我身本似远行客，況是亂时多病身。","經山涉水向何处，羞见竹林禪定人。"]', '诗', 'shi', '', NULL, '題武當逸禪師蘭若 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42465c23-b469-4754-9429-1fad7a53d3ec', '穀城逢楊評事', '穀城逢楊評事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["遠自五陵獨竄身，筑陽山中歸路新。","橫流夜長不得渡，駐馬荒亭逢故人。"]', '["远自五陵独竄身，筑陽山中归路新。","橫流夜长不得渡，駐马荒亭逢故人。"]', '诗', 'shi', '', NULL, '穀城逢楊評事 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3870907-4c8a-4d1b-be03-5d2e9c30391a', '聽韓使君美人歌', '听韓使君美人歌', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["仙人此夜忽凌波，更唱瑤臺一遍歌。","嫁與將軍天上住，人間可得再相過。"]', '["仙人此夜忽凌波，更唱瑤台一遍歌。","嫁與將軍天上住，人间可得再相過。"]', '诗', 'shi', '', NULL, '聽韓使君美人歌 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d35c106a-a213-46d1-b8e0-5a8466f2ccf7', '轉應詞', '轉應词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["邊草，邊草，邊草盡來共老。","山南山北雪晴，千里萬里月明。","明月，明月，胡笳一聲愁絕。"]', '["邊草，邊草，邊草尽来共老。","山南山北雪晴，千里万里月明。","明月，明月，胡笳一声愁絕。"]', '诗', 'shi', '', NULL, '轉應詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae43520-9762-47f0-b034-3013298ad02b', '精舍對雨', '精舍对雨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["空門寂寂澹吾身，溪雨微微洗客塵。","臥向白雲晴未盡，任他黃鳥醉芳春。"]', '["空门寂寂澹吾身，溪雨微微洗客塵。","臥向白云晴未尽，任他黄鸟醉芳春。"]', '诗', 'shi', '', NULL, '精舍對雨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8cf387-6398-4264-856b-dd30578ffc31', '宿灌陽灘', '宿灌陽灘', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["十月江邊蘆葉飛，灌陽灘冷上舟遲。","今朝未遇高風便，還與沙鷗宿水湄。"]', '["十月江邊蘆葉飞，灌陽灘冷上舟遲。","今朝未遇高风便，還與沙鷗宿水湄。"]', '诗', 'shi', '', NULL, '宿灌陽灘 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1be4a54-cf26-4951-b3db-8c5c43ccf174', '酬贈張衆甫', '酬贈張衆甫', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["野人無本意，散木任天材。","分向空山老，何言上苑來。","迢遙千里道，依倚九層臺。","出處寧知命，輪轅豈自媒。","更慙張處士，相與別蒿萊。"]', '["野人無本意，散木任天材。","分向空山老，何言上苑来。","迢遙千里道，依倚九層台。","出处寧知命，輪轅豈自媒。","更慙張处士，相與別蒿萊。"]', '诗', 'shi', '', NULL, '酬贈張衆甫 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bb1a7c8-b1d8-4683-ac28-b6676e12f667', '客舍秋懷呈駱正字士則', '客舍秋懷呈駱正字士則', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["無言堪自喩，偶坐更相悲。","木落驚年長，門閑惜草衰。","買山猶未得，諫獵又非時。","設被浮名繫，歸休漸欲遲。"]', '["無言堪自喩，偶坐更相悲。","木落驚年长，门闲惜草衰。","買山猶未得，諫獵又非时。","設被浮名繫，归休漸欲遲。"]', '诗', 'shi', '', NULL, '客舍秋懷呈駱正字士則 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c10308-05f9-4c02-ab28-fad2b23f438d', '寄中書李舍人紓', '寄中书李舍人紓', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["萍翻蓬自卷，不共本心期。","復入重城裏，頻看百草滋。","水流歸思遠，花發長年悲。","盡日春風起，無人見此時。"]', '["萍翻蓬自卷，不共本心期。","复入重城裏，頻看百草滋。","水流归思远，花發长年悲。","尽日春风起，無人见此时。"]', '诗', 'shi', '', NULL, '寄中書李舍人紓 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0588faba-2b1b-4451-9c6e-8ddd3a696de9', '贈康老人洽', '贈康老人洽', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["酒泉布衣舊才子，少小知名帝城裏。","一篇飛入九重門，樂府喧喧聞至尊。","宮中美人皆唱得，七貴因之盡相識。","南鄰北里日經過，處處淹留樂事多。","不脫弊裘輕錦綺，長吟佳句掩笙歌。","賢王貴主於我厚，駿馬蒼頭如己有。","暗將心事隔風塵，盡擲年光逐杯酒。","青門幾度見春歸，折柳尋花送落暉。","杜陵往往逢秋暮，望月臨風攀古樹。","繁霜入鬢何足論，舊國連天不知處。","爾來倏忽五十年，却憶當時思眇然。","多識故侯悲宿草，曾看流水沒桑田。","百人會中一身在，被褐飲瓢終不改。","陌頭車馬共營營，不解如君任此生。"]', '["酒泉布衣旧才子，少小知名帝城裏。","一篇飞入九重门，乐府喧喧闻至尊。","宮中美人皆唱得，七貴因之尽相識。","南鄰北里日經過，处处淹留乐事多。","不脫弊裘轻錦綺，长吟佳句掩笙歌。","賢王貴主於我厚，駿马蒼头如己有。","暗將心事隔风塵，尽擲年光逐杯酒。","青门幾度见春归，折柳尋花送落暉。","杜陵往往逢秋暮，望月臨风攀古樹。","繁霜入鬢何足論，旧国連天不知处。","爾来倏忽五十年，却憶當时思眇然。","多識故侯悲宿草，曾看流水沒桑田。","百人會中一身在，被褐饮瓢終不改。","陌头车马共營營，不解如君任此生。"]', '诗', 'shi', '', NULL, '贈康老人洽 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2446f3e6-9a1f-465f-9cba-e481a62e956d', '暮春遊長沙東湖贈辛兖州巢父二首 一', '暮春游长沙东湖贈辛兖州巢父二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["湘流分曲浦，繚繞古城東。","岸轉千家合，林開一鏡空。","人生無事少，心賞幾回同。","且復忘羈束，悠悠落照中。"]', '["湘流分曲浦，繚繞古城东。","岸轉千家合，林开一镜空。","人生無事少，心賞幾回同。","且复忘羈束，悠悠落照中。"]', '诗', 'shi', '', NULL, '暮春遊長沙東湖贈辛兖州巢父二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('869a90a2-6d0b-4c59-90c4-f6c2ec8ab6b6', '暮春遊長沙東湖贈辛兖州巢父二首 二', '暮春游长沙东湖贈辛兖州巢父二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["回環路不盡，歷覽意彌新。","古木畬田火，澄江盪槳人。","緩歌尋極浦，一醉送殘春。","莫恨長沙遠，他年憶此辰。"]', '["回环路不尽，歷覽意彌新。","古木畬田火，澄江盪槳人。","緩歌尋極浦，一醉送殘春。","莫恨长沙远，他年憶此辰。"]', '诗', 'shi', '', NULL, '暮春遊長沙東湖贈辛兖州巢父二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5173303e-8dd5-4ef5-a730-53dd933c131f', '同兖州張秀才過王侍御參謀宅賦十韻', '同兖州張秀才過王侍御參謀宅賦十韻', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["十年官不進，歛跡無怨咎。","漂蕩海內遊，淹留楚鄉久。","因參戎幕下，寄宅湘川口。","翦竹開廣庭，瞻山敞虛牖。","閑門早春至，陋巷新晴後。","覆地落殘梅，和風褭輕柳。","逢迎車馬客，邀結風塵友。","意愜時會文，夜長聊飲酒。","秉心轉孤直，沈照隨可否。","豈學屈大夫，憂慙對漁叟。"]', '["十年官不進，歛跡無怨咎。","漂蕩海內游，淹留楚乡久。","因參戎幕下，寄宅湘川口。","翦竹开廣庭，瞻山敞虛牖。","闲门早春至，陋巷新晴後。","覆地落殘梅，和风褭轻柳。","逢迎车马客，邀結风塵友。","意愜时會文，夜长聊饮酒。","秉心轉孤直，沈照隨可否。","豈学屈大夫，憂慙对漁叟。"]', '诗', 'shi', '', NULL, '同兖州張秀才過王侍御參謀宅賦十韻 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b458312e-4d72-43bf-a5e7-bd427620b1cb', '同辛兖州巢父盧副端岳相思獻酬之作因抒歸懷兼呈辛魏二院長楊長寧', '同辛兖州巢父盧副端岳相思獻酬之作因抒归懷兼呈辛魏二院长楊长寧', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["暮角發高城，情人坐中起。","臨觴不及醉，分散秋風裏。","雖有明日期，離心若千里。","前歡反惆悵，後會還如此。","焉得夜淹留，一回終宴喜。","羈遊復牽役，皆去重湖水。","早晚泛歸舟，吾從數君子。"]', '["暮角發高城，情人坐中起。","臨觴不及醉，分散秋风裏。","雖有明日期，離心若千里。","前歡反惆悵，後會還如此。","焉得夜淹留，一回終宴喜。","羈游复牽役，皆去重湖水。","早晚泛归舟，吾從數君子。"]', '诗', 'shi', '', NULL, '同辛兖州巢父盧副端岳相思獻酬之作因抒歸懷兼呈辛魏二院長楊長寧 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a30cdb0-aab8-4c0d-9ef3-78f7216ceb66', '酬袁太祝長卿小湖村山居書懷見寄', '酬袁太祝长卿小湖村山居书懷见寄', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["背江居隙地，辭職作遺人。","耕鑿資餘力，樵漁逐四鄰。","麥秋桑葉大，梅雨稻田新。","籬落栽山果，池塘養海鱗。","放歌聊自足，幽思忽相親。","余亦歸休者，依君老此身。"]', '["背江居隙地，辞職作遺人。","耕鑿資餘力，樵漁逐四鄰。","麦秋桑葉大，梅雨稻田新。","籬落栽山果，池塘養海鱗。","放歌聊自足，幽思忽相親。","余亦归休者，依君老此身。"]', '诗', 'shi', '', NULL, '酬袁太祝長卿小湖村山居書懷見寄 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5e472b-669d-441b-bd55-7ef708eacf0e', '送汶水王明府', '送汶水王明府', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["何時別故鄉，歸去佩銅章。","親族移家盡，閭閻百戰場。","背關餘古木，近塞足風霜。","遺老應相賀，知君不下堂。"]', '["何时別故乡，归去佩銅章。","親族移家尽，閭閻百戰場。","背关餘古木，近塞足风霜。","遺老應相賀，知君不下堂。"]', '诗', 'shi', '', NULL, '送汶水王明府 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c50fc55-ea8f-47ee-a9a0-9712f66d5cb6', '奉同汴州李相公勉送郭布殿中出巡', '奉同汴州李相公勉送郭布殿中出巡', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["軒車出東閣，都邑遶南河。","馬首先春至，人心比歲和。","省風傳隱恤，持法去煩苛。","却想埋輪者，論功此日多。"]', '["軒车出东閣，都邑遶南河。","马首先春至，人心比歲和。","省风傳隐恤，持法去煩苛。","却想埋輪者，論功此日多。"]', '诗', 'shi', '', NULL, '奉同汴州李相公勉送郭布殿中出巡 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8823f9ad-2be8-46c2-b906-67c13d1e5862', '送東陽顧明府罷歸', '送东陽顧明府罷归', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["祖帳臨鮫室，黎人擁鷁舟。","坐藍高士去，繼組鄙夫留。","白日落寒水，青楓遶曲洲。","相看作離別，一倍不禁愁。"]', '["祖帳臨鮫室，黎人擁鷁舟。","坐藍高士去，繼組鄙夫留。","白日落寒水，青楓遶曲洲。","相看作離別，一倍不禁愁。"]', '诗', 'shi', '', NULL, '送東陽顧明府罷歸 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ed3638-6e4f-4408-a070-71776dcfc0fc', '撫州對事後送外生宋垓歸饒州覲侍呈上姊夫', '撫州对事後送外生宋垓归饒州覲侍呈上姊夫', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["淮汴初喪亂，蔣山烽火起。","與君隨親族，奔迸辭故里。","京口附商客，海門正狂風。","憂心不敢住，夜發驚浪中。","雲開方見日，潮盡爐峯出。","石壁轉棠陰，鄱陽寄茅室。","淹留三十年，分種越人田。","骨肉無半在，鄉園猶未旋。","爾家習文藝，旁究天人際。","父子自相傳，優游聊卒歲。","學成不求達，道勝那厭貧。","時入閭巷醉，好是羲皇人。","頃因物役牽，偶逐簪組輩。","謗書喧朝市，撫己慙淺昧。","世業大小禮，近通顏謝詩。","念渠還領會，非敢獨爲師。"]', '["淮汴初喪亂，蔣山烽火起。","與君隨親族，奔迸辞故里。","京口附商客，海门正狂风。","憂心不敢住，夜發驚浪中。","云开方见日，潮尽爐峯出。","石壁轉棠陰，鄱陽寄茅室。","淹留三十年，分種越人田。","骨肉無半在，乡园猶未旋。","爾家習文藝，旁究天人際。","父子自相傳，優游聊卒歲。","学成不求達，道勝那厭貧。","时入閭巷醉，好是羲皇人。","頃因物役牽，偶逐簪組輩。","謗书喧朝市，撫己慙淺昧。","世業大小禮，近通顏謝诗。","念渠還領會，非敢独爲師。"]', '诗', 'shi', '', NULL, '撫州對事後送外生宋垓歸饒州覲侍呈上姊夫 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31e68e4-cfbe-41d3-bbee-6fe3f21b4c4d', '永康孫明府頲秩滿將歸枉路訪別', '永康孫明府頲秩满將归枉路訪別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["門前水流咽，城下亂山多。","非是還家路，寧知枉騎過。","風煙復欲隔，悲笑屢相和。","不學陶公醉，無因奈別何。"]', '["门前水流咽，城下亂山多。","非是還家路，寧知枉騎過。","风煙复欲隔，悲笑屢相和。","不学陶公醉，無因奈別何。"]', '诗', 'shi', '', NULL, '永康孫明府頲秩滿將歸枉路訪別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4f32bf-4c3f-445c-a840-8365b398c01f', '將赴湖南留別東陽舊僚兼示吏人', '將赴湖南留別东陽旧僚兼示吏人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["智力苦不足，黎甿殊未安。","忽從新命去，復隔舊寮歡。","曉路整車馬，離亭會衣冠。","冰堅細流咽，燒盡亂峯寒。","耆老相餞送，兒童亦悲酸。","桐鄉寄生怨，欲話此情難。"]', '["智力苦不足，黎甿殊未安。","忽從新命去，复隔旧寮歡。","晓路整车马，離亭會衣冠。","冰堅細流咽，燒尽亂峯寒。","耆老相餞送，兒童亦悲酸。","桐乡寄生怨，欲話此情难。"]', '诗', 'shi', '', NULL, '將赴湖南留別東陽舊僚兼示吏人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e98dfa2-956b-4824-9a58-929872bd511b', '撫州處士胡泛見送北迴兩館至南昌縣界查溪蘭若別', '撫州处士胡泛见送北迴兩館至南昌縣界查溪蘭若別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["移罇鋪山曲，祖帳查溪陰。","鋪山即遠道，查溪非故林。","淒然誦新詩，落淚霑素襟。","郡政我何有，別情君獨深。","禪庭古樹秋，宿雨清沈沈。","揮袂千里遠，悲傷去住心。"]', '["移罇鋪山曲，祖帳查溪陰。","鋪山即远道，查溪非故林。","淒然誦新诗，落泪霑素襟。","郡政我何有，別情君独深。","禪庭古樹秋，宿雨清沈沈。","揮袂千里远，悲傷去住心。"]', '诗', 'shi', '', NULL, '撫州處士胡泛見送北迴兩館至南昌縣界查溪蘭若別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b21d308-5be0-42e0-a78b-bcbbb62e42f1', '將巡郴永途中作', '將巡郴永途中作', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["行役留三楚，思歸又一春。","自疑冠下髮，聊此鏡中人。","機息知名誤，形衰恨道貧。","空將舊泉石，長與夢相親。"]', '["行役留三楚，思归又一春。","自疑冠下髮，聊此镜中人。","機息知名誤，形衰恨道貧。","空將旧泉石，长與梦相親。"]', '诗', 'shi', '', NULL, '將巡郴永途中作 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e98249-7f22-41ae-82bc-270870b2e641', '桂陽北嶺偶過野人所居聊書即事呈王永州邕李道州圻', '桂陽北嶺偶過野人所居聊书即事呈王永州邕李道州圻', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["犬吠空山響，林深一逕存。","隔雲尋板屋，渡水到柴門。","日晝風煙靜，花明草樹繁。","乍疑秦世客，漸識楚人言。","不記逃鄉里，居然長子孫。","種田燒險谷，汲井鑿高原。","畦葉藏春雉，庭柯宿旅猨。","嶺陰無瘴癘，地隙有蘭蓀。","內戶均皮席，枯瓢沃野餐。","遠心知自負，幽賞詎能論。","轉步重崖合，瞻途落照昏。","他時願攜手，莫比武陵源。"]', '["犬吠空山响，林深一逕存。","隔云尋板屋，渡水到柴门。","日晝风煙静，花明草樹繁。","乍疑秦世客，漸識楚人言。","不記逃乡里，居然长子孫。","種田燒險谷，汲井鑿高原。","畦葉藏春雉，庭柯宿旅猨。","嶺陰無瘴癘，地隙有蘭蓀。","內戶均皮席，枯瓢沃野餐。","远心知自負，幽賞詎能論。","轉步重崖合，瞻途落照昏。","他时願携手，莫比武陵源。"]', '诗', 'shi', '', NULL, '桂陽北嶺偶過野人所居聊書即事呈王永州邕李道州圻 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994b35f3-5d8e-45b0-8ab9-c59bbe2627e4', '下鼻亭瀧行八十里聊狀艱險寄青苗鄭副端朔陽', '下鼻亭瀧行八十里聊狀艱險寄青苗鄭副端朔陽', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["瀧水天際來，鼻山地中坼。","盤渦幾十處，疊溜皆千尺。","直寫卷沈沙，驚翻衝絕壁。","淙淙振崖谷，洶洶竟朝夕。","人語不自聞，日光亂相射。","艤舟始搖漾，舉棹旋奔激。","既下同建瓴，半空方避石。","前危苦未盡，後險何其迫。","倏閃疾風雷，蒼皇蕩魂魄。","因隨伏流出，忽與跳波隔。","遠想欲回軒，豈茲還泛鷁。","雲涯多候館，努力勤登歷。"]', '["瀧水天際来，鼻山地中坼。","盤渦幾十处，叠溜皆千尺。","直寫卷沈沙，驚翻衝絕壁。","淙淙振崖谷，洶洶竟朝夕。","人語不自闻，日光亂相射。","艤舟始搖漾，舉棹旋奔激。","既下同建瓴，半空方避石。","前危苦未尽，後險何其迫。","倏閃疾风雷，蒼皇蕩魂魄。","因隨伏流出，忽與跳波隔。","远想欲回軒，豈茲還泛鷁。","云涯多候館，努力勤登歷。"]', '诗', 'shi', '', NULL, '下鼻亭瀧行八十里聊狀艱險寄青苗鄭副端朔陽 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdc07246-3835-46d3-8bcb-584c7a2ef676', '少女生日感懷', '少女生日感懷', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["五逢晬日今方見，置爾懷中自惘然。","乍喜老身辭遠役，翻悲一笑隔重泉。","欲教針線嬌難解，暫弄琴書性已便。","還有蔡家殘史籍，可能分與外人傳。"]', '["五逢晬日今方见，置爾懷中自惘然。","乍喜老身辞远役，翻悲一笑隔重泉。","欲教針線嬌难解，暫弄琴书性已便。","還有蔡家殘史籍，可能分與外人傳。"]', '诗', 'shi', '', NULL, '少女生日感懷 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('766e9f06-a076-44aa-8ea9-bc9650dcacf7', '張評事涉秦居士系見訪郡齋即同賦中字', '張評事涉秦居士系见訪郡斋即同賦中字', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["軺車忽枉轍，郡府自生風。","遣吏山禽在，開罇野客同。","古牆抽臘筍，喬木颺春鴻。","能賦傳幽思，清言盡至公。","城欹殘照入，池曲大江通。","此地人來少，相歡一醉中。"]', '["軺车忽枉轍，郡府自生风。","遣吏山禽在，开罇野客同。","古牆抽臘筍，喬木颺春鴻。","能賦傳幽思，清言尽至公。","城欹殘照入，池曲大江通。","此地人来少，相歡一醉中。"]', '诗', 'shi', '', NULL, '張評事涉秦居士系見訪郡齋即同賦中字 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0228a1b-aee8-4571-b1e0-4ee232b5d636', '小雪', '小雪', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["花雪隨風不厭看，更多還肯失林巒。","愁人正在書窗下，一片飛來一片寒。"]', '["花雪隨风不厭看，更多還肯失林巒。","愁人正在书窗下，一片飞来一片寒。"]', '诗', 'shi', '', NULL, '小雪 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2937426d-da4f-4bc6-9280-a84b1f2cc1c9', '句', '句', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鄰里龍沙北。","麥秋桑葉大，梅雨稻田新。","籬落栽山果，池塘養錦鱗。"]', '["鄰里龙沙北。","麦秋桑葉大，梅雨稻田新。","籬落栽山果，池塘養錦鱗。"]', '诗', 'shi', '', NULL, '句 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97cd4e39-463e-4717-8eca-7e01e4827e5f', '競渡歌', '競渡歌', 'dcbb78e1-5cd2-4d89-984b-d785149d55d2', '唐', '["五月五日天晴明，楊花繞江啼曉鶯。","使君未出郡齋外，江上早聞齊和聲。","使君出時皆有準，馬前已被紅旗引。","兩岸羅衣破暈香，銀釵照日如霜刃。","鼓聲三下紅旗開，兩龍躍出浮水來。","櫂影斡波飛萬劒，鼓聲劈浪鳴千雷。","鼓聲漸急標將近，兩龍望標目如瞬。","坡上人呼霹靂驚，竿頭綵挂虹蜺暈。","前船搶水已得標，後船失勢空揮橈。","瘡眉血首爭不定，輸岸一朋心似燒。","只將輸贏分罰賞，兩岸十舟五來往。","須臾戲罷各東西，競脫文身請書上。","吾今細觀競度兒，何殊當路權相持。","不思得岸各休去，會到摧車折檝時。"]', '["五月五日天晴明，楊花繞江啼晓鶯。","使君未出郡斋外，江上早闻齊和声。","使君出时皆有準，马前已被紅旗引。","兩岸羅衣破暈香，銀釵照日如霜刃。","鼓声三下紅旗开，兩龙躍出浮水来。","櫂影斡波飞万劒，鼓声劈浪鳴千雷。","鼓声漸急標將近，兩龙望標目如瞬。","坡上人呼霹靂驚，竿头綵挂虹蜺暈。","前船搶水已得標，後船失勢空揮橈。","瘡眉血首爭不定，輸岸一朋心似燒。","只將輸贏分罰賞，兩岸十舟五来往。","須臾戲罷各东西，競脫文身請书上。","吾今細观競度兒，何殊當路權相持。","不思得岸各休去，會到摧车折檝时。"]', '诗', 'shi', '', NULL, '競渡歌 張建封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8389c9-3ecf-4efb-9abd-d620c977e9a2', '酬韓校書愈打毬歌', '酬韓校书愈打毬歌', 'dcbb78e1-5cd2-4d89-984b-d785149d55d2', '唐', '["僕本修文持筆者，今來帥領紅旌下。","不能無事習虵矛，閑就平場學使馬。","軍中伎癢驍智材，競馳駿逸隨我來。","護軍對引相向去，風呼月旋朋先開。","俯身仰擊復傍擊，難於古人左右射。","齊觀百步透短門，誰羨養由遙破的。","儒生疑我新發狂，武夫愛我生雄光。","杖移鬃底拂尾後，星從月下流中場。","人不約，心自一，馬不鞭，蹄自疾。","凡情莫辨捷中能，拙目翻驚巧時失。","韓生訝我爲斯藝，勸我徐驅作安計。","不知戎事竟何成，且愧吾人一言惠。"]', '["僕本修文持笔者，今来帥領紅旌下。","不能無事習虵矛，闲就平場学使马。","軍中伎癢驍智材，競驰駿逸隨我来。","護軍对引相向去，风呼月旋朋先开。","俯身仰擊复傍擊，难於古人左右射。","齊观百步透短门，誰羨養由遙破的。","儒生疑我新發狂，武夫愛我生雄光。","杖移鬃底拂尾後，星從月下流中場。","人不約，心自一，马不鞭，蹄自疾。","凡情莫辨捷中能，拙目翻驚巧时失。","韓生訝我爲斯藝，勸我徐驱作安計。","不知戎事竟何成，且愧吾人一言惠。"]', '诗', 'shi', '', NULL, '酬韓校書愈打毬歌 張建封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08d9140-736a-43b7-80db-7d0815e5f0c2', '春山夜月', '春山夜月', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["春山多勝事，賞翫夜忘歸。","掬水月在手，弄花香滿衣。","興來無遠近，欲去惜芳菲。","南望鳴鐘處，樓臺深翠微。"]', '["春山多勝事，賞翫夜忘归。","掬水月在手，弄花香满衣。","兴来無远近，欲去惜芳菲。","南望鳴鐘处，楼台深翠微。"]', '诗', 'shi', '', NULL, '春山夜月 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15965ee-8558-400d-889d-15bd933181b8', '宿藍田山口奉寄沈員外', '宿藍田山口奉寄沈員外', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["山暝飛羣鳥，川長泛四鄰。","煙歸河畔草，月照渡頭人。","朋友懷東道，鄉關戀北辰。","去留無所適，岐路獨迷津。"]', '["山暝飞羣鸟，川长泛四鄰。","煙归河畔草，月照渡头人。","朋友懷东道，乡关戀北辰。","去留無所適，岐路独迷津。"]', '诗', 'shi', '', NULL, '宿藍田山口奉寄沈員外 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea53702-480c-4b1c-bb8a-bb95c8e701dc', '冬日野望寄李贊府', '冬日野望寄李贊府', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["地際朝陽滿，天邊宿霧收。","風兼殘雪起，河帶斷冰流。","北闕馳心極，南圖尚旅遊。","登臨思不已，何處得銷愁。"]', '["地際朝陽满，天邊宿霧收。","风兼殘雪起，河带斷冰流。","北闕驰心極，南圖尚旅游。","登臨思不已，何处得銷愁。"]', '诗', 'shi', '', NULL, '冬日野望寄李贊府 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153638ca-1f1b-4214-8d83-41919a6675f8', '閑居寄薛華', '闲居寄薛华', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["隱几讀黃老，閑居耳目清。","僻居人事少，多病道心生。","雨洗山林濕，鴉鳴池館晴。","晚來因廢卷，行藥至西城。"]', '["隐几读黄老，闲居耳目清。","僻居人事少，多病道心生。","雨洗山林濕，鴉鳴池館晴。","晚来因廢卷，行藥至西城。"]', '诗', 'shi', '', NULL, '閑居寄薛華 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c426e92d-e18f-4dcc-810e-5d967353dfa4', '江上送友人', '江上送友人', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["看爾動行櫂，未收離別筵。","千帆忽見及，亂却故人船。","紛泊雁羣起，逶迤沙漵連。","長亭十里外，應是少人煙。"]', '["看爾动行櫂，未收離別筵。","千帆忽见及，亂却故人船。","紛泊雁羣起，逶迤沙漵連。","长亭十里外，應是少人煙。"]', '诗', 'shi', '', NULL, '江上送友人 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2df70bb-0958-4bc6-bef3-593eae26d678', '田家秋日送友', '田家秋日送友', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["蒼茫日初宴，遙野雲初收。","殘雨北山裏，夕陽東渡頭。","舟依漁溓合，水入田家流。","何意君迷駕，山林應有秋。"]', '["蒼茫日初宴，遙野云初收。","殘雨北山裏，夕陽东渡头。","舟依漁溓合，水入田家流。","何意君迷駕，山林應有秋。"]', '诗', 'shi', '', NULL, '田家秋日送友 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50f6900-25c0-49d5-8d6c-39b33a9fb878', '自吟', '自吟', '8bbf7a6b-fea6-495d-8a85-a97fee1679b0', '唐', '["出身三十年，髮白衣猶碧。","日暮倚朱門，從朱污袍赤。"]', '["出身三十年，髮白衣猶碧。","日暮倚朱门，從朱污袍赤。"]', '诗', 'shi', '', NULL, '自吟 于良史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50de24cb-7548-4a09-bb9f-7681a1fe7d27', '感興', '感兴', 'a8c47753-b338-4d4d-8898-f7f8b717ae70', '唐', '["富貴難義合，困窮易感恩。","古來忠烈士，多出貧賤門。","世上桃李樹，但結繁華子。","白屋抱關人，青雲壯心死。","本以勢利交，勢盡交情已。","如何失情後，始歎門易軌。"]', '["富貴难義合，困窮易感恩。","古来忠烈士，多出貧賤门。","世上桃李樹，但結繁华子。","白屋抱关人，青云壯心死。","本以勢利交，勢尽交情已。","如何失情後，始歎门易軌。"]', '诗', 'shi', '', NULL, '感興 崔膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac3dfa77-1d98-474b-a7b5-76d080cbd0fa', '別佳人', '別佳人', 'a8c47753-b338-4d4d-8898-f7f8b717ae70', '唐', '["壠上流泉壠下分，斷腸嗚咽不堪聞。","嫦娥一入月中去，巫峽千秋空白雲。"]', '["壠上流泉壠下分，斷腸嗚咽不堪闻。","嫦娥一入月中去，巫峽千秋空白云。"]', '诗', 'shi', '', NULL, '別佳人 崔膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27423bb8-fa3f-41e6-83a6-9c105c176d3d', '御溝新柳', '御溝新柳', '02246080-d605-4f54-9d01-0465e371ec26', '唐', '["夾道天渠遠，垂絲御柳新。","千條宜向日，萬戶共迎春。","輕翠含煙發，微音逐吹頻。","靜看思渡口，迴望憶江濱。","嫋嫋分遊騎，依依駐旅人。","陽和如可及，攀折在茲辰。"]', '["夾道天渠远，垂絲御柳新。","千條宜向日，万戶共迎春。","轻翠含煙發，微音逐吹頻。","静看思渡口，迴望憶江濱。","嫋嫋分游騎，依依駐旅人。","陽和如可及，攀折在茲辰。"]', '诗', 'shi', '', NULL, '御溝新柳 馮宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a7b56ab-bb3a-462e-b704-7cba25843e6b', '酬白樂天劉夢得', '酬白乐天劉梦得', '02246080-d605-4f54-9d01-0465e371ec26', '唐', '["共稱洛邑難其選，何幸天書用不才。","遙約和風新草木，且令新雪靜塵埃。","臨岐有愧傾三省，別酌無辭醉百杯。","明歲杏園花下集，須知春色自東來。"]', '["共稱洛邑难其選，何幸天书用不才。","遙約和风新草木，且令新雪静塵埃。","臨岐有愧傾三省，別酌無辞醉百杯。","明歲杏园花下集，須知春色自东来。"]', '诗', 'shi', '', NULL, '酬白樂天劉夢得 馮宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3128cf50-ec04-4964-855a-2bc5b0531987', '樂府荅孟東野戲贈', '乐府荅孟东野戲贈', '53f77d71-48b8-4376-adc3-2a5e7143822d', '唐', '["芙蓉初出水，菡萏露中花。","風吹著枯木，無奈值空槎。"]', '["芙蓉初出水，菡萏露中花。","风吹著枯木，無奈值空槎。"]', '诗', 'shi', '', NULL, '樂府荅孟東野戲贈 陸長源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbefe905-26fd-4334-895d-c87e0ff08671', '詶孟十二新居見寄', '詶孟十二新居见寄', '53f77d71-48b8-4376-adc3-2a5e7143822d', '唐', '["大道本夷曠，高情亦沖虛。","因隨白雲意，偶逐青蘿居。","青蘿紛蒙密，四序無慘舒。","餘清濯子襟，散彩還吾廬。","去歲登美第，策名在公車。","將必繼管蕭，豈惟躡應徐。","首夏尚清和，殘芳遍丘墟。","褰幃蔭窗柳，汲井滋園蔬。","達者貴知心，古人不願餘。","愛君蔣生逕，且著茂陵書。"]', '["大道本夷曠，高情亦沖虛。","因隨白云意，偶逐青蘿居。","青蘿紛蒙密，四序無慘舒。","餘清濯子襟，散彩還吾廬。","去歲登美第，策名在公车。","將必繼管蕭，豈惟躡應徐。","首夏尚清和，殘芳遍丘墟。","褰幃蔭窗柳，汲井滋园蔬。","達者貴知心，古人不願餘。","愛君蔣生逕，且著茂陵书。"]', '诗', 'shi', '', NULL, '詶孟十二新居見寄 陸長源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('589b7577-0753-4ffb-b6c4-66854d6fedb8', '荅東野夷門雪', '荅东野夷门雪', '53f77d71-48b8-4376-adc3-2a5e7143822d', '唐', '["好丹與素道不同，失意得途事皆別。","東隣少年樂未央，南客思歸腸欲絕。","千里長河冰復冰，雲鴻冥冥楚山雪。"]', '["好丹與素道不同，失意得途事皆別。","东隣少年乐未央，南客思归腸欲絕。","千里长河冰复冰，云鴻冥冥楚山雪。"]', '诗', 'shi', '', NULL, '荅東野夷門雪 陸長源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eaa1d14-09d3-446b-a722-01c4d674dace', '句', '句', '53f77d71-48b8-4376-adc3-2a5e7143822d', '唐', '["忽然一曲稱君心，破却中人百家產。","城外平人驅欲盡，帳中猶打衮花球。"]', '["忽然一曲稱君心，破却中人百家產。","城外平人驱欲尽，帳中猶打衮花球。"]', '诗', 'shi', '', NULL, '句 陸長源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc8caaf5-a738-4e46-973c-f7050efaf214', '寄興國池鶴上劉相公', '寄兴国池鹤上劉相公', 'f45ce7a1-8276-4ab5-8204-f2b10334be20', '唐', '["馴狎經時久，䙰褷短翮存。","不隨淮海變，空媿稻粱恩。","獨立秋天靜，單棲夕露繁。","欲飛還斂翼，詎敢望乘軒。"]', '["馴狎經时久，䙰褷短翮存。","不隨淮海变，空媿稻粱恩。","独立秋天静，單棲夕露繁。","欲飞還斂翼，詎敢望乘軒。"]', '诗', 'shi', '', NULL, '寄興國池鶴上劉相公 張衆甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c336a822-fed8-4896-af78-7dc493780df0', '送李司直使吳', '送李司直使吳', 'f45ce7a1-8276-4ab5-8204-f2b10334be20', '唐', '["使臣方擁傳，王事遠辭家。","震澤逢殘雨，新豐過落花。","水萍千葉散，風柳萬條斜。","何處看離恨，春江無限沙。"]', '["使臣方擁傳，王事远辞家。","震澤逢殘雨，新豐過落花。","水萍千葉散，风柳万條斜。","何处看離恨，春江無限沙。"]', '诗', 'shi', '', NULL, '送李司直使吳 張衆甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da94437-62ec-4f16-b3da-a7b18662e736', '送李觀之宣州謁袁中丞賦得三州渡', '送李观之宣州謁袁中丞賦得三州渡', 'f45ce7a1-8276-4ab5-8204-f2b10334be20', '唐', '["古渡大江濱，西南距要津。","自當舟檝路，應濟往來人。","翻浪驚飛鳥，回風起綠蘋。","君看波上客，歲晚獨垂綸。"]', '["古渡大江濱，西南距要津。","自當舟檝路，應濟往来人。","翻浪驚飞鸟，回风起綠蘋。","君看波上客，歲晚独垂綸。"]', '诗', 'shi', '', NULL, '送李觀之宣州謁袁中丞賦得三州渡 張衆甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc4c2ff-a861-4170-881b-babe127564a4', '宿慧山寺', '宿慧山寺', '58365c14-057e-4c1a-b344-c5c5197d7a46', '唐', '["秋日遊古寺，秋山正蒼蒼。","泛舟次巖壑，稽首金仙堂。","下有寒泉流，上有珍禽翔。","石門吐明月，竹木涵清光。","中夜河沈沈，但聞松桂香。","曠然出塵境，憂慮澹已忘。"]', '["秋日游古寺，秋山正蒼蒼。","泛舟次巖壑，稽首金仙堂。","下有寒泉流，上有珍禽翔。","石门吐明月，竹木涵清光。","中夜河沈沈，但闻松桂香。","曠然出塵境，憂慮澹已忘。"]', '诗', 'shi', '', NULL, '宿慧山寺 王武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc26733-1070-4a17-b803-b5b9de83e5fc', '秋暮登北樓', '秋暮登北楼', '58365c14-057e-4c1a-b344-c5c5197d7a46', '唐', '["秋滿空山悲客心，山樓晴望散幽襟。","一川紅樹迎霜老，數曲清溪繞寺深。","寒氣急催遙塞雁，夕風高送遠城砧。","三年海上音書絕，鄉國蕭條惟夢尋。"]', '["秋满空山悲客心，山楼晴望散幽襟。","一川紅樹迎霜老，數曲清溪繞寺深。","寒氣急催遙塞雁，夕风高送远城砧。","三年海上音书絕，乡国蕭條惟梦尋。"]', '诗', 'shi', '', NULL, '秋暮登北樓 王武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2224bbe8-9998-4a41-b624-8c59969ed098', '宿慧山寺 一', '宿慧山寺 一', 'bcbb8a50-4b16-4867-a1d6-ad9d86152320', '唐', '["古寺隱秋山，登攀度林樾。","悠然清蓮界，此地塵境絕。","機閑任晝昏，慮澹知生滅。","微吹遞遙泉，疎松對殘月。","庭虛露華綴，池淨荷香發。","心悟形未留，遲遲履歸轍。"]', '["古寺隐秋山，登攀度林樾。","悠然清蓮界，此地塵境絕。","機闲任晝昏，慮澹知生滅。","微吹遞遙泉，疎松对殘月。","庭虛露华綴，池淨荷香發。","心悟形未留，遲遲履归轍。"]', '诗', 'shi', '', NULL, '宿慧山寺 一 朱宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d2dd1c1-8133-420d-ba0b-1bd8f67e8e6b', '宿慧山寺 二', '宿慧山寺 二', 'bcbb8a50-4b16-4867-a1d6-ad9d86152320', '唐', '["歲月人間促，煙霞此地多。","殷勤竹林寺，更得幾迴過。"]', '["歲月人间促，煙霞此地多。","殷勤竹林寺，更得幾迴過。"]', '诗', 'shi', '', NULL, '宿慧山寺 二 朱宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d6a90c-8065-48b0-a99f-138d984fb40c', '送惟良上人歸江南', '送惟良上人归江南', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["落日映危檣，歸僧向岳陽。","注瓶寒浪靜，讀律夜船香。","苦霧沈山影，陰霾發海光。","羣生一何負，多病禮醫王。"]', '["落日映危檣，归僧向岳陽。","注瓶寒浪静，读律夜船香。","苦霧沈山影，陰霾發海光。","羣生一何負，多病禮醫王。"]', '诗', 'shi', '', NULL, '送惟良上人歸江南 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baa8ac70-3b99-49e7-ab47-0c35c7b125c9', '送韓都護還邊', '送韓都護還邊', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["好勇知名早，爭雄上將間。","戰多春入塞，獵慣夜登山。","陣合龍蛇動，軍移草木閑。","今來部曲盡，白首過蕭關。"]', '["好勇知名早，爭雄上將间。","戰多春入塞，獵慣夜登山。","陣合龙蛇动，軍移草木闲。","今来部曲尽，白首過蕭关。"]', '诗', 'shi', '', NULL, '送韓都護還邊 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c6b3a96-fbbf-4407-83cf-5c6ad0c4b496', '送吉中孚校書歸楚州舊山', '送吉中孚校书归楚州旧山', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["青袍芸閣郎，談笑挹侯王。","舊籙藏雲穴，新詩滿帝鄉。","名高閑不得，到處人爭識。","誰知冰雪顏，已雜風塵色。","此去復如何，東臯岐路多。","藉芳臨紫陌，回首憶滄波。","年來倦蕭索，但說淮南樂。","並檝湖上遊，連檣月中泊。","沿溜入閶門，千燈夜市喧。","喜逢鄰舍伴，遙語問鄉園。","下淮風自急，樹杪分郊邑。","送客隨岸行，離人出帆立。","漁村繞水田，澹澹隔晴煙。","欲就林中醉，先期石上眠。","林昏天未曙，但向雲邊去。","暗入無路山，心知有花處。","登高日轉明，下望見春城。","洞裏草空長，塚邊人自耕。","寥寥行異境，過盡千峰影。","露色凝古壇，泉聲落寒井。","仙成不可期，多別自堪悲。","爲問桃源客，何人見亂時。"]', '["青袍芸閣郎，談笑挹侯王。","旧籙藏云穴，新诗满帝乡。","名高闲不得，到处人爭識。","誰知冰雪顏，已杂风塵色。","此去复如何，东臯岐路多。","藉芳臨紫陌，回首憶滄波。","年来倦蕭索，但说淮南乐。","並檝湖上游，連檣月中泊。","沿溜入閶门，千灯夜市喧。","喜逢鄰舍伴，遙語问乡园。","下淮风自急，樹杪分郊邑。","送客隨岸行，離人出帆立。","漁村繞水田，澹澹隔晴煙。","欲就林中醉，先期石上眠。","林昏天未曙，但向云邊去。","暗入無路山，心知有花处。","登高日轉明，下望见春城。","洞裏草空长，塚邊人自耕。","寥寥行異境，過尽千峰影。","露色凝古壇，泉声落寒井。","仙成不可期，多別自堪悲。","爲问桃源客，何人见亂时。"]', '诗', 'shi', '', NULL, '送吉中孚校書歸楚州舊山 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb76b92-4f30-43b9-8c96-ce8e3b718dec', '送姨弟裴均尉諸曁', '送姨弟裴均尉諸曁', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["相悲得成長，同是外家恩。","舊業廢三畝，弱年成一門。","城開山日早，吏散渚禽喧。","東閣謬容止，予心君冀言。"]', '["相悲得成长，同是外家恩。","旧業廢三畝，弱年成一门。","城开山日早，吏散渚禽喧。","东閣謬容止，予心君冀言。"]', '诗', 'shi', '', NULL, '送姨弟裴均尉諸曁 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac042cb6-34ae-4d77-9942-56fb5aad802e', '送鄧州崔長史', '送鄧州崔长史', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["出山車騎次諸侯，坐領圖書見督郵。","遶郭桑麻通淅口，滿川風景接襄州。","高城鳥過方催夜，廢壘蟬鳴不待秋。","聞說元規偏愛月，知君常得伴登樓。"]', '["出山车騎次諸侯，坐領圖书见督郵。","遶郭桑麻通淅口，满川风景接襄州。","高城鸟過方催夜，廢壘蟬鳴不待秋。","闻说元規偏愛月，知君常得伴登楼。"]', '诗', 'shi', '', NULL, '送鄧州崔長史 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d30d7e0b-1af1-488e-a533-4a9c45366c1a', '送鹽鐵裴判官入蜀', '送鹽鐵裴判官入蜀', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["傳詔收方貢，登車著賜衣。","榷商蠻客富，稅地芋田肥。","雲白風雷歇，林清洞穴稀。","炎涼君莫問，見即在忘歸。"]', '["傳詔收方貢，登车著賜衣。","榷商蠻客富，稅地芋田肥。","云白风雷歇，林清洞穴稀。","炎涼君莫问，见即在忘归。"]', '诗', 'shi', '', NULL, '送鹽鐵裴判官入蜀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81fd429-5b1f-481a-a7a3-ffa1a1eaddc9', '送魏廣下第歸揚州', '送魏廣下第归揚州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["楚鄉雲水內，春日衆山開。","淮浪參差起，江帆次第來。","獨歸初失桂，共醉忽停杯。","漢詔年年有，何愁掩上才。"]', '["楚乡云水內，春日衆山开。","淮浪參差起，江帆次第来。","独归初失桂，共醉忽停杯。","漢詔年年有，何愁掩上才。"]', '诗', 'shi', '', NULL, '送魏廣下第歸揚州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b01399-c9cc-4660-a2fd-c92550bc6513', '送潘述應宏詞下第歸江南', '送潘述應宏词下第归江南', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["愁與醉相和，昏昏竟若何。","感年懷闕久，失意夢鄉多。","雨裏行青草，山前望白波。","江樓覆棋好，誰引仲宣過。"]', '["愁與醉相和，昏昏竟若何。","感年懷闕久，失意梦乡多。","雨裏行青草，山前望白波。","江楼覆棋好，誰引仲宣過。"]', '诗', 'shi', '', NULL, '送潘述應宏詞下第歸江南 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ef9a8b-4c38-48e4-a143-a54a9d411abc', '送從舅成都縣丞廣歸蜀', '送從舅成都縣丞廣归蜀', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["襃谷通岷嶺，青冥此路深。","晚程椒瘴熱，野飯荔枝陰。","古郡三刀夜，春橋萬里心。","唯應對楊柳，暫醉卓家琴。"]', '["襃谷通岷嶺，青冥此路深。","晚程椒瘴熱，野飯荔枝陰。","古郡三刀夜，春橋万里心。","唯應对楊柳，暫醉卓家琴。"]', '诗', 'shi', '', NULL, '送從舅成都縣丞廣歸蜀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27673f94-0473-48be-874c-928016c01b78', '送宋校書赴宣州幕', '送宋校书赴宣州幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["南想宣城郡，清江野戍閑。","艨艟高映浦，睥睨曲隨山。","名寄圖書內，威生將吏間。","春行板橋暮，應伴庾公還。"]', '["南想宣城郡，清江野戍闲。","艨艟高映浦，睥睨曲隨山。","名寄圖书內，威生將吏间。","春行板橋暮，應伴庾公還。"]', '诗', 'shi', '', NULL, '送宋校書赴宣州幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298603f3-945f-4112-a9d7-f6d9e73dccc7', '送李縱別駕加員外郎却赴常州幕', '送李縱別駕加員外郎却赴常州幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["霄漢正聯飛，江湖又獨歸。","暫歡同賜被，不待易朝衣。","山雨迎軍晚，蘆風候火微。","還當宴鈴閣，謝守亦光輝。"]', '["霄漢正聯飞，江湖又独归。","暫歡同賜被，不待易朝衣。","山雨迎軍晚，蘆风候火微。","還當宴鈴閣，謝守亦光輝。"]', '诗', 'shi', '', NULL, '送李縱別駕加員外郎却赴常州幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90873ddd-2b28-4582-be1e-9967bac5dd8b', '送元贊府重任龍門縣', '送元贊府重任龙门縣', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["二職亞陶公，歸程與夢同。","柳垂平澤雨，魚躍大河風。","混跡威長在，孤清志自雄。","應嗤向隅者，空寄路塵中。"]', '["二職亞陶公，归程與梦同。","柳垂平澤雨，鱼躍大河风。","混跡威长在，孤清志自雄。","應嗤向隅者，空寄路塵中。"]', '诗', 'shi', '', NULL, '送元贊府重任龍門縣 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d704fc60-067b-4385-b541-b3f0fb4c6e0d', '送黎燧尉陽翟', '送黎燧尉陽翟', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉貌承嚴訓，金聲稱上才。","列筵青草偃，驟馬綠楊開。","潘縣花添發，梅家鶴暫來。","誰知望恩者，空逐路人回。"]', '["玉貌承嚴訓，金声稱上才。","列筵青草偃，驟马綠楊开。","潘縣花添發，梅家鹤暫来。","誰知望恩者，空逐路人回。"]', '诗', 'shi', '', NULL, '送黎燧尉陽翟 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37408b78-1836-4f05-90ae-d13fcb2e86b3', '送丹陽趙少府', '送丹陽趙少府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["恭聞林下別，未至亦霑裳。","荻岸雨聲盡，江天虹影長。","佩韋宗嬾慢，偷橘愛芳香。","遙想從公後，稱榮在上堂。"]', '["恭闻林下別，未至亦霑裳。","荻岸雨声尽，江天虹影长。","佩韋宗嬾慢，偷橘愛芳香。","遙想從公後，稱榮在上堂。"]', '诗', 'shi', '', NULL, '送丹陽趙少府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f0030c-0030-4b54-9f67-aa37cf114dfe', '送菊潭王明府', '送菊潭王明府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["組綬掩衰顏，輝光里第間。","晚涼經灞水，清晝入商山。","行境逢花發，彈琴見鶴還。","唯應理農後，鄉老賀君閑。"]', '["組綬掩衰顏，輝光里第间。","晚涼經灞水，清晝入商山。","行境逢花發，彈琴见鹤還。","唯應理農後，乡老賀君闲。"]', '诗', 'shi', '', NULL, '送菊潭王明府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b42b7db-84ff-4e02-89ea-1d78079a8550', '送陳明府赴萍縣', '送陳明府赴萍縣', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["素舸載陶公，南隨萬里風。","梅花成雪嶺，橘樹當家僮。","祠掩荒山下，田開野荻中。","歲終書善績，應與古碑同。"]', '["素舸載陶公，南隨万里风。","梅花成雪嶺，橘樹當家僮。","祠掩荒山下，田开野荻中。","歲終书善績，應與古碑同。"]', '诗', 'shi', '', NULL, '送陳明府赴萍縣 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8451a8d-f39f-44a7-a9e3-f9f8c0636582', '送申屠正字往湖南迎親兼謁趙和州因呈上侍郎使君幷戲簡前歷陽李明府', '送申屠正字往湖南迎親兼謁趙和州因呈上侍郎使君幷戲簡前歷陽李明府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["曉月朣朦映水關，水邊因到歷陽山。","千艘財貨朱橋下，一曲閭閻青荻間。","坦腹定逢潘令醉，上樓應伴庾公閑。","歡餘若問南行計，知念天涯負米還。"]', '["晓月朣朦映水关，水邊因到歷陽山。","千艘財貨朱橋下，一曲閭閻青荻间。","坦腹定逢潘令醉，上楼應伴庾公闲。","歡餘若问南行計，知念天涯負米還。"]', '诗', 'shi', '', NULL, '送申屠正字往湖南迎親兼謁趙和州因呈上侍郎使君幷戲簡前歷陽李明府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac0413e-d57f-451a-9111-d5c79ed5a730', '送李尚書郎君昆季侍從歸覲滑州', '送李尚书郎君昆季侍從归覲滑州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鳳雛聯翼美王孫，綵服戎裝擬塞垣。","金鼎對筵調野膳，玉鞭齊騎引行軒。","冰河一曲旌旗滿，墨詔千封雨露繁。","更說務農能罷戰，敢持謌頌慶晨昏。"]', '["鳳雛聯翼美王孫，綵服戎裝擬塞垣。","金鼎对筵調野膳，玉鞭齊騎引行軒。","冰河一曲旌旗满，墨詔千封雨露繁。","更说務農能罷戰，敢持謌頌慶晨昏。"]', '诗', 'shi', '', NULL, '送李尚書郎君昆季侍從歸覲滑州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698d746e-7903-48fa-920c-f68eee20c36a', '送張調參軍侍從歸觐荆南因寄長林司空十四曙', '送張調參軍侍從归觐荆南因寄长林司空十四曙', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉勒侍行襜，郄超未有髯。","守儒輕獵騎，承誨訪沈潛。","雲勢將峰雜，江聲與嶼兼。","還當見王粲，應念二毛添。"]', '["玉勒侍行襜，郄超未有髯。","守儒轻獵騎，承誨訪沈潛。","云勢將峰杂，江声與嶼兼。","還當见王粲，應念二毛添。"]', '诗', 'shi', '', NULL, '送張調參軍侍從歸觐荆南因寄長林司空十四曙 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7ead4e-e822-4c8a-99ba-b884e0e29a6c', '送馬尚書郎君侍從歸覲太原', '送马尚书郎君侍從归覲太原', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉人垂玉鞭，百騎帶櫜鞬。","從賞野郵靜，獻新秋果鮮。","塞屯豐雨雪，虜帳失山川。","遙想稱觴後，唯當共被眠。"]', '["玉人垂玉鞭，百騎带櫜鞬。","從賞野郵静，獻新秋果鲜。","塞屯豐雨雪，虜帳失山川。","遙想稱觴後，唯當共被眠。"]', '诗', 'shi', '', NULL, '送馬尚書郎君侍從歸覲太原 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10be540-a81f-43dc-8cf2-5d347f47468d', '送張成季往江上賦得垂楊', '送張成季往江上賦得垂楊', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["垂楊真可憐，地勝覺春偏。","一穗雨聲裏，千條池色前。","露繁光的皪，日麗影團圓。","若到隋隄望，應逢花滿船。"]', '["垂楊真可怜，地勝覺春偏。","一穗雨声裏，千條池色前。","露繁光的皪，日丽影團圓。","若到隋隄望，應逢花满船。"]', '诗', 'shi', '', NULL, '送張成季往江上賦得垂楊 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f3931e-fb9a-45db-bd7d-e20034434010', '送陝府王司法', '送陝府王司法', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["東門雪覆塵，出送陝城人。","粉郭朝喧市，朱橋夜掩津。","上寮應重學，小吏已甘貧。","謝朓曾爲掾，希君一比鄰。"]', '["东门雪覆塵，出送陝城人。","粉郭朝喧市，朱橋夜掩津。","上寮應重学，小吏已甘貧。","謝朓曾爲掾，希君一比鄰。"]', '诗', 'shi', '', NULL, '送陝府王司法 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b51846c-dad8-4e78-86fb-b1722719cb46', '送太常李主簿歸覲省', '送太常李主簿归覲省', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["粲粲美仍都，清閑一貴儒。","定交分玉劒，發詠寫冰壺。","風景隨台位，河山入障圖。","上堂多慶樂，肯念谷中愚。"]', '["粲粲美仍都，清闲一貴儒。","定交分玉劒，發詠寫冰壺。","风景隨台位，河山入障圖。","上堂多慶乐，肯念谷中愚。"]', '诗', 'shi', '', NULL, '送太常李主簿歸覲省 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59cde0c6-34f7-41f9-b059-c3930b1835d2', '送從叔程歸西川幕', '送從叔程归西川幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["千山冰雪晴，山靜錦花明。","羣鶴棲蓮府，諸戎拜柳營。","浪依巴字息，風入蜀關清。","豈念在貧巷，竹林鳴鳥聲。"]', '["千山冰雪晴，山静錦花明。","羣鹤棲蓮府，諸戎拜柳營。","浪依巴字息，风入蜀关清。","豈念在貧巷，竹林鳴鸟声。"]', '诗', 'shi', '', NULL, '送從叔程歸西川幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da69f75-03c4-4501-9930-01c8c3033c44', '送萬巨', '送万巨', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["把酒留君聽琴，難堪歲暮離心。","霜葉無風自落，秋雲不雨空陰。","人愁荒村路細，馬怯寒溪水深。","望斷青山獨立，更知何處相尋。"]', '["把酒留君听琴，难堪歲暮離心。","霜葉無风自落，秋云不雨空陰。","人愁荒村路細，马怯寒溪水深。","望斷青山独立，更知何处相尋。"]', '诗', 'shi', '', NULL, '送萬巨 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672a31e0-ed1c-4061-9da6-8f1e39a7a251', '途中遇雨馬上口號留別張劉二端公', '途中遇雨马上口號留別張劉二端公', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["陰雷慢轉野雲長，駿馬雙嘶愛雨涼。","應念龍鐘在泥滓，欲摧肝膽事王章。"]', '["陰雷慢轉野云长，駿马雙嘶愛雨涼。","應念龙鐘在泥滓，欲摧肝膽事王章。"]', '诗', 'shi', '', NULL, '途中遇雨馬上口號留別張劉二端公 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eced59f-88bb-4404-99dd-67e57deec2bc', '送夔州班使君', '送夔州班使君', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["曉日照樓船，三軍拜峽前。","白雲隨浪散，青壁與城連。","萬嶺岷峨雪，千家橘柚川。","還知楚河內，天子許經年。"]', '["晓日照楼船，三軍拜峽前。","白云隨浪散，青壁與城連。","万嶺岷峨雪，千家橘柚川。","還知楚河內，天子許經年。"]', '诗', 'shi', '', NULL, '送夔州班使君 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb84cce-b6cd-4346-97ef-bbe40d7a22ee', '送從舅成都丞廣歸蜀', '送從舅成都丞廣归蜀', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["巴字天邊水，秦人去是歸。","棧長山雨響，溪亂火田稀。","俗富行應樂，官雄祿豈微。","魏舒終有淚，還識甯家衣。"]', '["巴字天邊水，秦人去是归。","棧长山雨响，溪亂火田稀。","俗富行應乐，官雄祿豈微。","魏舒終有泪，還識甯家衣。"]', '诗', 'shi', '', NULL, '送從舅成都丞廣歸蜀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c14c68c7-d454-4a5c-8657-fb413db1591a', '無題', '無題', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["耻將名利託交親，只向尊前樂此身。","才大不應成滯客，時危且喜是閑人。","高歌猶愛思歸引，醉語惟誇漉酒巾。","囗囗囗囗囗囗囗，豈能偏遣老風塵。"]', '["耻將名利託交親，只向尊前乐此身。","才大不應成滯客，时危且喜是闲人。","高歌猶愛思归引，醉語惟誇漉酒巾。","囗囗囗囗囗囗囗，豈能偏遣老风塵。"]', '诗', 'shi', '', NULL, '無題 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a977b0f8-5edd-40ad-b571-3a08343cec6b', '題念濟寺', '題念濟寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["靈空聞偈夜清靜，雨裏花枝朝暮開。","故友九泉留語別，逐臣千里寄書來。"]', '["靈空闻偈夜清静，雨裏花枝朝暮开。","故友九泉留語別，逐臣千里寄书来。"]', '诗', 'shi', '', NULL, '題念濟寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c222b6d5-2eb5-4603-84ed-b5afef260fae', '河口逢江州朱道士因聽琴', '河口逢江州朱道士因听琴', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["廬山道士夜攜琴，映月相逢辨語音。","引坐霜中彈一弄，滿船商客有歸心。"]', '["廬山道士夜携琴，映月相逢辨語音。","引坐霜中彈一弄，满船商客有归心。"]', '诗', 'shi', '', NULL, '河口逢江州朱道士因聽琴 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c08d89e-9c4a-4cb2-a7f7-8affe0e8fe70', '送夏侯校書歸華陰別墅', '送夏侯校书归华陰別墅', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["山前白鶴村，竹雪覆柴門。","候客定爲黍，務農因燎原。","乳冰懸暗井，蓮石照晴軒。","貰酒鄰里睦，曝衣場圃喧。","依然望君去，余性亦何昏。"]', '["山前白鹤村，竹雪覆柴门。","候客定爲黍，務農因燎原。","乳冰懸暗井，蓮石照晴軒。","貰酒鄰里睦，曝衣場圃喧。","依然望君去，余性亦何昏。"]', '诗', 'shi', '', NULL, '送夏侯校書歸華陰別墅 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49adda39-bfe8-402d-9f77-05ad95fb4231', '送絳州郭參軍', '送絳州郭參軍', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["炎天故絳路，千里麥花香。","董澤雷聲發，汾橋水氣涼。","府趨隨宓賤，野宴接王祥。","送客今何幸，經宵醉玉堂。"]', '["炎天故絳路，千里麦花香。","董澤雷声發，汾橋水氣涼。","府趨隨宓賤，野宴接王祥。","送客今何幸，經宵醉玉堂。"]', '诗', 'shi', '', NULL, '送絳州郭參軍 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a5d11f-1e42-4441-9c9c-eb87a27c73e9', '中書舍人李座上送潁陽徐少府', '中书舍人李座上送潁陽徐少府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["潁陽春色似河陽，一望繁花一縣香。","今日送官君最恨，可憐才子白鬚長。"]', '["潁陽春色似河陽，一望繁花一縣香。","今日送官君最恨，可怜才子白鬚长。"]', '诗', 'shi', '', NULL, '中書舍人李座上送潁陽徐少府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a1f1d4-dde1-49ec-9b25-a44e24e7eceb', '與從弟瑾同下第後出關言別 一', '與從弟瑾同下第後出关言別 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["同作金門獻賦人，二年悲見故園春。","到闕不沾新雨露，還家空帶舊風塵。"]', '["同作金门獻賦人，二年悲见故园春。","到闕不沾新雨露，還家空带旧风塵。"]', '诗', 'shi', '', NULL, '與從弟瑾同下第後出關言別 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9cf7be7-b5f3-443a-b19f-987b19d7874f', '與從弟瑾同下第後出關言別 二', '與從弟瑾同下第後出关言別 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雜花飛盡柳陰陰，官路逶迤綠草深。","對酒已成千里客，望山空寄兩鄉心。"]', '["杂花飞尽柳陰陰，官路逶迤綠草深。","对酒已成千里客，望山空寄兩乡心。"]', '诗', 'shi', '', NULL, '與從弟瑾同下第後出關言別 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f8215a-0581-45e8-ac71-8d9cfec8e9a3', '與從弟瑾同下第後出關言別 三', '與從弟瑾同下第後出关言別 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["出關愁暮一沾裳，滿野蓬生古戰場。","孤村樹色昏殘雨，遠寺鐘聲帶夕陽。"]', '["出关愁暮一沾裳，满野蓬生古戰場。","孤村樹色昏殘雨，远寺鐘声带夕陽。"]', '诗', 'shi', '', NULL, '與從弟瑾同下第後出關言別 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc228c0d-4d2a-45a3-a137-a3ca03b5d7f0', '與從弟瑾同下第後出關言別 四', '與從弟瑾同下第後出关言別 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["誰憐苦志已三冬，却欲躬耕學老農。","流水白雲尋不盡，期君何處得相逢。"]', '["誰怜苦志已三冬，却欲躬耕学老農。","流水白云尋不尽，期君何处得相逢。"]', '诗', 'shi', '', NULL, '與從弟瑾同下第後出關言別 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dde890d-22b5-413a-8313-9654389d378b', '赴虢州留別故人', '赴虢州留別故人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["世故相逢各未閑，百年多在別離間。","昨夜秋風今夜雨，不知何處入空山。"]', '["世故相逢各未闲，百年多在別離间。","昨夜秋风今夜雨，不知何处入空山。"]', '诗', 'shi', '', NULL, '赴虢州留別故人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6eff0e-d937-4d1f-9e3b-91241dd3db27', '冬夜贈別友人', '冬夜贈別友人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["愁聽千家流水聲，相思獨向月中行。","侵堦暗草秋霜重，遍郭寒山夜月明。","連年客舍唯多病，數畝田園又廢耕。","更送乘軺歸上國，應憐貢禹未成名。"]', '["愁听千家流水声，相思独向月中行。","侵堦暗草秋霜重，遍郭寒山夜月明。","連年客舍唯多病，數畝田园又廢耕。","更送乘軺归上国，應怜貢禹未成名。"]', '诗', 'shi', '', NULL, '冬夜贈別友人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b5a36a-565c-4de0-96e7-ff360fcde230', '送顧秘書獻書後歸岳州', '送顧秘书獻书後归岳州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["黃葉落不盡，蒼苔隨雨生。","當軒置尊酒，送客歸江城。","竹裏聞機杼，舟中見弟兄。","岳陽賢太守，應爲改鄉名。"]', '["黄葉落不尽，蒼苔隨雨生。","當軒置尊酒，送客归江城。","竹裏闻機杼，舟中见弟兄。","岳陽賢太守，應爲改乡名。"]', '诗', 'shi', '', NULL, '送顧秘書獻書後歸岳州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3dfde1b-93ff-4904-9fcd-83d96b59d571', '送衞司法河中覲省', '送衞司法河中覲省', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["出身因強學，不以外家榮。","年少無遺事，官閑有政聲。","曉山臨野渡，落日照軍營。","共賞高堂下，連行弟與兄。"]', '["出身因強学，不以外家榮。","年少無遺事，官闲有政声。","晓山臨野渡，落日照軍營。","共賞高堂下，連行弟與兄。"]', '诗', 'shi', '', NULL, '送衞司法河中覲省 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e99bb380-5ddb-463b-b67c-b5fa720022e8', '送從叔牧永州', '送從叔牧永州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["五侯軒蓋行何疾，零陵太守登車日。","零陵太守淚盈巾，此日長安方欲春。","虎符龍節照岐路，何苦愁爲江海人。","彼方韶景無時節，山水諸花恣開發。","客投津戍少聞猨，鴈過瀟湘更逢雪。","郡齋無事好閑眠，秔稻油油綠滿川。","浪裏爭迎三蜀貨，月中喧泊九江船。","今朝小阮同夷老，欲聞明年借幾年。"]', '["五侯軒蓋行何疾，零陵太守登车日。","零陵太守泪盈巾，此日长安方欲春。","虎符龙節照岐路，何苦愁爲江海人。","彼方韶景無时節，山水諸花恣开發。","客投津戍少闻猨，鴈過瀟湘更逢雪。","郡斋無事好闲眠，秔稻油油綠满川。","浪裏爭迎三蜀貨，月中喧泊九江船。","今朝小阮同夷老，欲闻明年借幾年。"]', '诗', 'shi', '', NULL, '送從叔牧永州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d27cb764-d288-47e1-b54b-f25af928338d', '送趙真長歸夏縣舊山依陽徵君讀書', '送趙真长归夏縣旧山依陽徵君读书', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["臨杯忽泫然，非是惡離弦。","塵陌望松雪，我衰君少年。","幽僧曝山果，寒鹿守冰泉。","感物如有待，況依回也賢。"]', '["臨杯忽泫然，非是惡離弦。","塵陌望松雪，我衰君少年。","幽僧曝山果，寒鹿守冰泉。","感物如有待，況依回也賢。"]', '诗', 'shi', '', NULL, '送趙真長歸夏縣舊山依陽徵君讀書 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c8832d-ba40-4c6b-a471-bd201462693b', '留別耿湋侯釗馮著', '留別耿湋侯釗馮著', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["相識少相知，與君俱已衰。","笙鏞新宅第，岐路古山陂。","學道功難就，爲儒事本遲。","惟當與漁者，終老遂其私。"]', '["相識少相知，與君俱已衰。","笙鏞新宅第，岐路古山陂。","学道功难就，爲儒事本遲。","惟當與漁者，終老遂其私。"]', '诗', 'shi', '', NULL, '留別耿湋侯釗馮著 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6ffe22-1ced-48bf-b342-2d447fc4e0b3', '送渾鍊歸覲却赴闕庭', '送渾鍊归覲却赴闕庭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["露幕擁簪裾，台庭餞伯魚。","綵衣人競看，銀詔帝親書。","知子當元老，爲臣餞二疎。","執珪期已迫，捧膳步寧徐。","而我誠愚者，夫君豈病諸。","探題多決勝，饌玉每分餘。","榮比成功後，恩同造化初。","甑塵方欲合，籠翮或將舒。","榆莢錢難比，楊花雪不如。","明朝古隄路，心斷玉人車。"]', '["露幕擁簪裾，台庭餞伯鱼。","綵衣人競看，銀詔帝親书。","知子當元老，爲臣餞二疎。","執珪期已迫，捧膳步寧徐。","而我誠愚者，夫君豈病諸。","探題多決勝，饌玉每分餘。","榮比成功後，恩同造化初。","甑塵方欲合，籠翮或將舒。","榆莢錢难比，楊花雪不如。","明朝古隄路，心斷玉人车。"]', '诗', 'shi', '', NULL, '送渾鍊歸覲却赴闕庭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('850aa54a-b97e-4f5f-a3b7-c984856f50ed', '送崔邠拾遺', '送崔邠拾遺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["皎潔無瑕清玉壺，曉乘華幰向天衢。","石建每聞宗謹孝，劉歆不敢衒師儒。","諫修郊廟開宸慮，議按休徵淺瑞圖。","今日攀車復何者，轅門垂白一愚夫。"]', '["皎潔無瑕清玉壺，晓乘华幰向天衢。","石建每闻宗謹孝，劉歆不敢衒師儒。","諫修郊廟开宸慮，議按休徵淺瑞圖。","今日攀车复何者，轅门垂白一愚夫。"]', '诗', 'shi', '', NULL, '送崔邠拾遺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b9217ba-c0d2-4a35-88f6-2acfb5f47c6b', '送渾別駕赴舒州', '送渾別駕赴舒州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["江平蘆荻齊，五兩貼檣低。","遶郭覆晴雪，滿船聞曙雞。","鱣魴宜入貢，橘柚亦成蹊。","還似海沂日，風清無鼓鼙。"]', '["江平蘆荻齊，五兩貼檣低。","遶郭覆晴雪，满船闻曙雞。","鱣魴宜入貢，橘柚亦成蹊。","還似海沂日，风清無鼓鼙。"]', '诗', 'shi', '', NULL, '送渾別駕赴舒州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f73be3-747b-4f57-81d5-b45bbb2672fc', '送從叔士準赴任潤州司士', '送從叔士準赴任潤州司士', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲起山城暮，沈沈江上天。","風吹建業雨，浪入廣陵船。","久是吳門客，嘗聞謝守賢。","終悲去國遠，淚盡竹林前。"]', '["云起山城暮，沈沈江上天。","风吹建業雨，浪入廣陵船。","久是吳门客，嘗闻謝守賢。","終悲去国远，泪尽竹林前。"]', '诗', 'shi', '', NULL, '送從叔士準赴任潤州司士 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823c919b-3ad6-47c7-bd05-3e89d7b74183', '送尹樞令狐楚及第後歸覲', '送尹樞令狐楚及第後归覲', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["佳人比香草，君子即芳蘭。","寶器金罍重，清音玉珮寒。","貢文齊受寵，獻禮兩承歡。","鞍馬幷汾地，爭迎陸與潘。"]', '["佳人比香草，君子即芳蘭。","寶器金罍重，清音玉珮寒。","貢文齊受寵，獻禮兩承歡。","鞍马幷汾地，爭迎陸與潘。"]', '诗', 'shi', '', NULL, '送尹樞令狐楚及第後歸覲 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de6e3ed-1985-41b6-8f63-bb2d9ec70c4c', '東潭宴餞河南趙少府', '东潭宴餞河南趙少府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["十載奉戎軒，日聞君子言。","方將賀榮爵，遽乃愴離尊。","岸轉臺閣麗，潭清弦管繁。","松篁難晦節，雨露不私恩。","坐使吏相勉，居爲儒所尊。","可憐桃李樹，先發信陵門。"]', '["十載奉戎軒，日闻君子言。","方將賀榮爵，遽乃愴離尊。","岸轉台閣丽，潭清弦管繁。","松篁难晦節，雨露不私恩。","坐使吏相勉，居爲儒所尊。","可怜桃李樹，先發信陵门。"]', '诗', 'shi', '', NULL, '東潭宴餞河南趙少府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc5c830a-ae41-48d9-9316-d825950f2ad1', '賦得館娃宮送王山人遊江東', '賦得館娃宮送王山人游江东', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["蒼蒼楓樹林，草合廢宮深。","越水風浪起，吳王歌管沈。","燕歸巢已盡，鶴語塚難尋。","旅泊彼何夜，希君抽玉琴。"]', '["蒼蒼楓樹林，草合廢宮深。","越水风浪起，吳王歌管沈。","燕归巢已尽，鹤語塚难尋。","旅泊彼何夜，希君抽玉琴。"]', '诗', 'shi', '', NULL, '賦得館娃宮送王山人遊江東 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01dd8f01-0719-4251-b373-1ef5431694ed', '送暢當還舊山', '送暢當還旧山', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["常逢明月馬塵間，是夜照君歸處山。","山中松桂花盡發，頭白屬君如等閑。"]', '["常逢明月马塵间，是夜照君归处山。","山中松桂花尽發，头白屬君如等闲。"]', '诗', 'shi', '', NULL, '送暢當還舊山 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c269ef5-b94d-4fe7-ad07-da7baa370c63', '斅顏魯公送挺贇歸翠微寺', '斅顏魯公送挺贇归翠微寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["挺贇惠學該儒釋，袖有顏徐真草跡。","一齋三請紀行詩，誚我垂鞭弄鳴鏑。","寺懸金榜半山隅，石路荒涼松樹枯。","虎跡印雪大如斗，閏月暮天過得無。"]', '["挺贇惠学該儒釋，袖有顏徐真草跡。","一斋三請紀行诗，誚我垂鞭弄鳴鏑。","寺懸金榜半山隅，石路荒涼松樹枯。","虎跡印雪大如斗，閏月暮天過得無。"]', '诗', 'shi', '', NULL, '斅顏魯公送挺贇歸翠微寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30176746-2898-4ae6-be84-c496504a227b', '送契玄法師赴內道場', '送契玄法師赴內道場', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["昏昏醉老夫，灌頂遇醍醐。","嬪御呈心鏡，君王賜髻珠。","降魔須戰否，問疾敢行無。","深契何相秘，儒宗本不殊。"]', '["昏昏醉老夫，灌頂遇醍醐。","嬪御呈心镜，君王賜髻珠。","降魔須戰否，问疾敢行無。","深契何相秘，儒宗本不殊。"]', '诗', 'shi', '', NULL, '送契玄法師赴內道場 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3157dc45-54a2-4643-a4bd-9eec2441ca2c', '送暢當赴山南幕', '送暢當赴山南幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["含情脫佩刀，持以佐賢豪。","是月霜霰下，伊人行役勞。","事將名共易，文與行空高。","去矣奉戎律，悲君爲我曹。"]', '["含情脫佩刀，持以佐賢豪。","是月霜霰下，伊人行役勞。","事將名共易，文與行空高。","去矣奉戎律，悲君爲我曹。"]', '诗', 'shi', '', NULL, '送暢當赴山南幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb57168-b7d4-4c36-9df0-e08236a5bf7d', '顏侍御廳叢篁詠送薛存誠', '顏侍御廳叢篁詠送薛存誠', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉幹百餘莖，生君此堂側。","拂簾寒雨響，擁砌深溪色。","何事鳳皇雛，茲焉理歸翼。"]', '["玉幹百餘莖，生君此堂側。","拂簾寒雨响，擁砌深溪色。","何事鳳皇雛，茲焉理归翼。"]', '诗', 'shi', '', NULL, '顏侍御廳叢篁詠送薛存誠 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0dc4078-378a-471e-8eb0-4343879ae9c9', '秋晚河西縣樓送渾中允赴朝闕', '秋晚河西縣楼送渾中允赴朝闕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高樓吹玉簫，車馬上河橋。","岐路自奔隘，壺觴終寂寥。","芳蘭生貴里，片玉立清朝。","今日台庭望，心遙非地遙。"]', '["高楼吹玉簫，车马上河橋。","岐路自奔隘，壺觴終寂寥。","芳蘭生貴里，片玉立清朝。","今日台庭望，心遙非地遙。"]', '诗', 'shi', '', NULL, '秋晚河西縣樓送渾中允赴朝闕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5c3f87-a819-4c5a-9960-4881d6d03273', '達奚中丞東齋壁畫山水各賦一物得樹杪懸泉送長安趙元陽少府', '達奚中丞东斋壁畫山水各賦一物得樹杪懸泉送长安趙元陽少府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["素壁畫飛泉，從雲落樹顛。","練垂疑葉響，雲幷覺枝偏。","利物得雙劒，爲儒當一賢。","應思灑塵陌，調膳亦芳鮮。"]', '["素壁畫飞泉，從云落樹顛。","練垂疑葉响，云幷覺枝偏。","利物得雙劒，爲儒當一賢。","應思灑塵陌，調膳亦芳鲜。"]', '诗', 'shi', '', NULL, '達奚中丞東齋壁畫山水各賦一物得樹杪懸泉送長安趙元陽少府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1051bde-d8a9-4348-973a-c6acd003e327', '送信州姚使君', '送信州姚使君', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["朱幡徐轉候羣官，猨鳥無聲郡宇寬。","楚國上腴收賦重，漢家良牧得人難。","銅鉛滿穴山能富，鴻鴈連羣地亦寒。","幾日政聲聞戶外，九江行旅得相歡。"]', '["朱幡徐轉候羣官，猨鸟無声郡宇寬。","楚国上腴收賦重，漢家良牧得人难。","銅鉛满穴山能富，鴻鴈連羣地亦寒。","幾日政声闻戶外，九江行旅得相歡。"]', '诗', 'shi', '', NULL, '送信州姚使君 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633c72af-1ed0-4cd5-8aac-00ecea86a65f', '送暢當', '送暢當', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["四望無極路，千里流大河。","秋風滿離袂，唯老事唯多。"]', '["四望無極路，千里流大河。","秋风满離袂，唯老事唯多。"]', '诗', 'shi', '', NULL, '送暢當 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb3248c-abec-4a64-8c24-8577c6893fb7', '送史兵曹判官赴樓煩', '送史兵曹判官赴楼煩', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["渥洼龍種散雲時，千里繁花乍別離。","中有重臣承霈澤，外無輕虜犯旌旗。","山川自與郊坰合，帳幕時因水草移。","敢謝親賢得瓊玉，仲宣能賦亦能詩。"]', '["渥洼龙種散云时，千里繁花乍別離。","中有重臣承霈澤，外無轻虜犯旌旗。","山川自與郊坰合，帳幕时因水草移。","敢謝親賢得瓊玉，仲宣能賦亦能诗。"]', '诗', 'shi', '', NULL, '送史兵曹判官赴樓煩 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc316afd-c02e-4dfc-84c4-6b10d3d78219', '送曇延法師講罷赴上都', '送曇延法師講罷赴上都', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["金縷架裟國大師，能銷壞宅火燒時。","復來擁膝說無住，知向人天何處期。"]', '["金縷架裟国大師，能銷壞宅火燒时。","复来擁膝说無住，知向人天何处期。"]', '诗', 'shi', '', NULL, '送曇延法師講罷赴上都 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a9e2b4-fa9f-4951-ab79-8b92b6d1621b', '送道士郄彝素歸內道場', '送道士郄彝素归內道場', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["病老正相仍，忽逢張道陵。","羽衣風淅淅，仙貌玉稜稜。","叱我問中壽，教人祈上昇。","樓居五雲裏，幾與武皇登。"]', '["病老正相仍，忽逢張道陵。","羽衣风淅淅，仙貌玉稜稜。","叱我问中壽，教人祈上昇。","楼居五云裏，幾與武皇登。"]', '诗', 'shi', '', NULL, '送道士郄彝素歸內道場 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea61eaf5-a7f3-44da-aeb8-6d7ebe3c288c', '賦得彭祖樓送楊德宗歸徐州幕', '賦得彭祖楼送楊德宗归徐州幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["四戶八窗明，玲瓏逼上清。","外欄黃鵠下，中柱紫芝生。","每帶雲霞色，時聞簫管聲。","望君兼有月，幢蓋儼層城。"]', '["四戶八窗明，玲瓏逼上清。","外欄黄鵠下，中柱紫芝生。","每带云霞色，时闻簫管声。","望君兼有月，幢蓋儼層城。"]', '诗', 'shi', '', NULL, '賦得彭祖樓送楊德宗歸徐州幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e24d80f-7b9a-4fd8-896e-a34db37feb5e', '送餞從叔辭豐州幕歸嵩陽舊居', '送餞從叔辞豐州幕归嵩陽旧居', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["白鬚宗孫侍坐時，願持壽酒前致詞。","鄙詞何所擬，請自邊城始。","邊城貴者李將軍，戰鼓遙疑天上聞。","屯田布錦周千里，牧馬攢花溢萬羣。","白雲本是喬松伴，來遶青營復飛散。","三聲畫角咽不通，萬里蓬根一時斷。","豐州聞說似涼州，沙塞晴明部落稠。","行客已去依獨戍，主人猶自在高樓。","夢親旌斾何由見，每阻清風一回面。","洞裏先生那怪遲，人天無路自無期。","砂泉丹井非同味，桂樹榆林不並枝。","吾翁致身殊得計，地仙亦是三千歲。","莫著戎衣期上清，東方曼倩逢人輕。"]', '["白鬚宗孫侍坐时，願持壽酒前致词。","鄙词何所擬，請自邊城始。","邊城貴者李將軍，戰鼓遙疑天上闻。","屯田布錦周千里，牧马攢花溢万羣。","白云本是喬松伴，来遶青營复飞散。","三声畫角咽不通，万里蓬根一时斷。","豐州闻说似涼州，沙塞晴明部落稠。","行客已去依独戍，主人猶自在高楼。","梦親旌斾何由见，每阻清风一回面。","洞裏先生那怪遲，人天無路自無期。","砂泉丹井非同味，桂樹榆林不並枝。","吾翁致身殊得計，地仙亦是三千歲。","莫著戎衣期上清，东方曼倩逢人轻。"]', '诗', 'shi', '', NULL, '送餞從叔辭豐州幕歸嵩陽舊居 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95aa10ba-37dc-4e03-98d3-01b062a33b46', '送靜居法師', '送静居法師', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["五色香幢重復重，寶輿升座發神鐘。","薝蔔名花飄不斷，醍醐法味灑何濃。","九天論道當宸眷，七祖傳心合聖蹤。","願比靈山前世別，多生還得此相逢。"]', '["五色香幢重复重，寶輿升座發神鐘。","薝蔔名花飄不斷，醍醐法味灑何濃。","九天論道當宸眷，七祖傳心合聖蹤。","願比靈山前世別，多生還得此相逢。"]', '诗', 'shi', '', NULL, '送靜居法師 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9baa1d59-a041-4057-974b-b2b7a95fba87', '送劉判官赴豐州', '送劉判官赴豐州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["銜杯吹急管，滿眼起風砂。","大漠山沈雪，長城草發花。","策行須耻戰，虜在莫言家。","余亦祈勳者，如何別左車。"]', '["銜杯吹急管，满眼起风砂。","大漠山沈雪，长城草發花。","策行須耻戰，虜在莫言家。","余亦祈勳者，如何別左车。"]', '诗', 'shi', '', NULL, '送劉判官赴豐州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8335908b-31c3-42ea-86f1-79923f863695', '將赴京留獻令公', '將赴京留獻令公', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["沙鶴驚鳴野雨收，大河風物颯然秋。","力微恩重諒難報，不是行人不解愁。"]', '["沙鹤驚鳴野雨收，大河风物颯然秋。","力微恩重諒难報，不是行人不解愁。"]', '诗', 'shi', '', NULL, '將赴京留獻令公 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e2719bc-e145-4d72-a9ed-344080a291ed', '落第後歸山下舊居留別劉起居昆季', '落第後归山下旧居留別劉起居昆季', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["寂寞過朝昏，沈憂豈易論。","有時空卜命，無事可酬恩。","寄食依鄰里，成家望子孫。","風塵知世路，衰賤到君門。","醉裏因多感，愁中欲強言。","花林逢廢井，戰地識荒園。","悵別臨晴野，悲春上古原。","鳥歸山外樹，人過水邊村。","潘岳方稱老，嵇康本厭喧。","誰堪將落羽，迴首仰飛翻。"]', '["寂寞過朝昏，沈憂豈易論。","有时空卜命，無事可酬恩。","寄食依鄰里，成家望子孫。","风塵知世路，衰賤到君门。","醉裏因多感，愁中欲強言。","花林逢廢井，戰地識荒园。","悵別臨晴野，悲春上古原。","鸟归山外樹，人過水邊村。","潘岳方稱老，嵇康本厭喧。","誰堪將落羽，迴首仰飞翻。"]', '诗', 'shi', '', NULL, '落第後歸山下舊居留別劉起居昆季 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38ac5aee-b8ad-4472-9514-957044c782b2', '將赴閿鄉灞上留別錢起員外', '將赴閿乡灞上留別錢起員外', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["暖景登橋望，分明春色來。","離心自惆悵，車馬亦裴回。","遠雪和霜積，高花占日開。","從官竟何事，憂患已相催。"]', '["暖景登橋望，分明春色来。","離心自惆悵，车马亦裴回。","远雪和霜積，高花占日开。","從官竟何事，憂患已相催。"]', '诗', 'shi', '', NULL, '將赴閿鄉灞上留別錢起員外 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d7f3b7-f997-4255-bbb2-aaaefc780b82', '虢州逢侯釗同尋南觀因贈別', '虢州逢侯釗同尋南观因贈別', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["相見翻惆悵，應憐責廢官。","過深慙祿在，識淺賴刑寬。","獨失耕農業，同思弟姪歡。","衰貧羞客過，卑束會君難。","放鶴登雲壁，澆花遶石壇。","興遠江海上，跡在是非端。","林密風聲細，山高雨色寒。","悠然此中別，賓僕亦闌干。"]', '["相见翻惆悵，應怜責廢官。","過深慙祿在，識淺賴刑寬。","独失耕農業，同思弟姪歡。","衰貧羞客過，卑束會君难。","放鹤登云壁，澆花遶石壇。","兴远江海上，跡在是非端。","林密风声細，山高雨色寒。","悠然此中別，賓僕亦闌干。"]', '诗', 'shi', '', NULL, '虢州逢侯釗同尋南觀因贈別 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dea3cc6-b281-4169-83bb-9a9391f826bf', '赴池州拜覲舅氏留上考功郎中舅', '赴池州拜覲舅氏留上考功郎中舅', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["孤賤易磋砣，其如酷似何。","衰榮同族少，生長外家多。","別國桑楡在，沾衣血淚和。","應憐失行鴈，霜霰寄煙波。"]', '["孤賤易磋砣，其如酷似何。","衰榮同族少，生长外家多。","別国桑楡在，沾衣血泪和。","應怜失行鴈，霜霰寄煙波。"]', '诗', 'shi', '', NULL, '赴池州拜覲舅氏留上考功郎中舅 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27984721-9a86-47a3-b942-b6e1264f4d12', '送從姪滁州覲省', '送從姪滁州覲省', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["愛爾似龍媒，翩翩千里迴。","書從外氏學，竹自晉時栽。","擁棹逢鷗舞，憑闌見雨來。","上堂多慶樂，不醉莫停杯。"]', '["愛爾似龙媒，翩翩千里迴。","书從外氏学，竹自晉时栽。","擁棹逢鷗舞，憑闌见雨来。","上堂多慶乐，不醉莫停杯。"]', '诗', 'shi', '', NULL, '送從姪滁州覲省 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb7ac565-d4bb-42c0-b034-033d94795030', '奉和聖製麟德殿宴百僚', '奉和聖製麟德殿宴百僚', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲闢御筵張，山呼聖壽長。","玉欄豐瑞草，金陛立神羊。","台鼎資庖膳，天星奉酒漿。","蠻夷陪作位，犀象舞成行。","網已祛三面，歌因守四方。","千秋不可極，花發滿宮香。"]', '["云闢御筵張，山呼聖壽长。","玉欄豐瑞草，金陛立神羊。","台鼎資庖膳，天星奉酒漿。","蠻夷陪作位，犀象舞成行。","網已祛三面，歌因守四方。","千秋不可極，花發满宮香。"]', '诗', 'shi', '', NULL, '奉和聖製麟德殿宴百僚 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea43bd0-2636-4ca4-a38a-653a9bff0ba2', '和考功王員外杪秋憶終南舊居', '和考功王員外杪秋憶終南旧居', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["靜憶溪邊宅，知君許謝公。","曉霜凝耒耜，初日照梧桐。","澗鼠喧藤蔓，山禽竄石藂。","白雲當嶺雨，黃葉遶堦風。","野果垂橋上，高泉落水中。","歡榮來自間，羸賤賞曾同。","月滿珠藏海，天晴鶴在籠。","餘陰如可寄，願得隱牆東。"]', '["静憶溪邊宅，知君許謝公。","晓霜凝耒耜，初日照梧桐。","澗鼠喧藤蔓，山禽竄石藂。","白云當嶺雨，黄葉遶堦风。","野果垂橋上，高泉落水中。","歡榮来自间，羸賤賞曾同。","月满珠藏海，天晴鹤在籠。","餘陰如可寄，願得隐牆东。"]', '诗', 'shi', '', NULL, '和考功王員外杪秋憶終南舊居 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbb02e08-ae97-4c87-b015-1db60f13b045', '詶暢當尋嵩岳麻道士見寄', '詶暢當尋嵩岳麻道士见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["聞逐樵夫閑看棋，忽逢人世是秦時。","開雲種玉嫌山淺，渡海傳書怪鶴遲。","陰洞石牀微有字，古壇松樹半無枝。","煩君遠示青囊籙，願得相從一問師。"]', '["闻逐樵夫闲看棋，忽逢人世是秦时。","开云種玉嫌山淺，渡海傳书怪鹤遲。","陰洞石牀微有字，古壇松樹半無枝。","煩君远示青囊籙，願得相從一问師。"]', '诗', 'shi', '', NULL, '詶暢當尋嵩岳麻道士見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93751d8f-6384-4713-abd4-bca9a7a64b29', '詶李端長安寓居偶詠見寄', '詶李端长安寓居偶詠见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["自別前峰隱，同爲外累侵。","幾年親酒會，此日有僧尋。","學稼功還棄，論邊事亦沈。","衆歡徒滿目，專愛久離心。","覽鬢絲垂鏡，彈琴淚灑襟。","訪田悲洛下，寄宅憶山陰。","薄溜漫青石，橫雲架碧林。","壞簷藤障密，衰菜棘籬深。","流散俱多故，憂傷併在今。","唯當竢高躅，歸止共抽簪。"]', '["自別前峰隐，同爲外累侵。","幾年親酒會，此日有僧尋。","学稼功還棄，論邊事亦沈。","衆歡徒满目，專愛久離心。","覽鬢絲垂镜，彈琴泪灑襟。","訪田悲洛下，寄宅憶山陰。","薄溜漫青石，橫云架碧林。","壞簷藤障密，衰菜棘籬深。","流散俱多故，憂傷併在今。","唯當竢高躅，归止共抽簪。"]', '诗', 'shi', '', NULL, '詶李端長安寓居偶詠見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3605101a-e5e1-49fb-b520-9f2279355a4f', '和常舍人晚秋集賢院即事十二韻寄贈江南徐薛二侍郎', '和常舍人晚秋集賢院即事十二韻寄贈江南徐薛二侍郎', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["綸閣九華前，森沈綵仗連。","洞門開旭日，清禁肅秋天。","霜滿朝容備，鐘餘漏唱傳。","搖璫陪羽扇，端弁入爐煙。","麟筆刪金篆，龍綃薦玉編。","汲書荀勖定，漢史蔡邕專。","御竹潛通筍，宮池暗瀉泉。","亂藂縈弱蕙，墮葉灑枯蓮。","列署齊遊日，重江並謫年。","登封思議草，侍講憶同筵。","滄海風濤廣，黝山瘴雨偏。","唯應緘上寶，贈遠一呈妍。"]', '["綸閣九华前，森沈綵仗連。","洞门开旭日，清禁肅秋天。","霜满朝容備，鐘餘漏唱傳。","搖璫陪羽扇，端弁入爐煙。","麟笔刪金篆，龙綃薦玉編。","汲书荀勖定，漢史蔡邕專。","御竹潛通筍，宮池暗瀉泉。","亂藂縈弱蕙，墮葉灑枯蓮。","列署齊游日，重江並謫年。","登封思議草，侍講憶同筵。","滄海风濤廣，黝山瘴雨偏。","唯應緘上寶，贈远一呈妍。"]', '诗', 'shi', '', NULL, '和常舍人晚秋集賢院即事十二韻寄贈江南徐薛二侍郎 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e309ab-ec52-493a-80a5-205fb3ff8174', '詶苗員外仲夏歸郊居遇雨見寄', '詶苗員外仲夏归郊居遇雨见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雷響風仍急，人歸鳥亦還。","亂雲方至水，驟雨已喧山。","田鼠依林上，池魚戲草間。","因茲屏埃霧，一詠一開顏。"]', '["雷响风仍急，人归鸟亦還。","亂云方至水，驟雨已喧山。","田鼠依林上，池鱼戲草间。","因茲屏埃霧，一詠一开顏。"]', '诗', 'shi', '', NULL, '詶苗員外仲夏歸郊居遇雨見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0f4f2b-3fc2-4db3-91c1-daf5136b080e', '和太常王卿立秋日即事', '和太常王卿立秋日即事', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["嵩高雲日明，潘岳賦初成。","籬槿花無色，堦桐葉有聲。","絳紗垂簟淨，白羽拂衣輕。","鴻鴈悲天遠，龜魚覺水清。","別弦添楚思，牧馬動邊情。","田雨農官問，林風苑吏驚。","松篁終茂盛，蓬艾自衰榮。","遙仰憑軒夕，惟應喜宋生。"]', '["嵩高云日明，潘岳賦初成。","籬槿花無色，堦桐葉有声。","絳紗垂簟淨，白羽拂衣轻。","鴻鴈悲天远，龟鱼覺水清。","別弦添楚思，牧马动邊情。","田雨農官问，林风苑吏驚。","松篁終茂盛，蓬艾自衰榮。","遙仰憑軒夕，惟應喜宋生。"]', '诗', 'shi', '', NULL, '和太常王卿立秋日即事 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f4a9b7f-91db-47bf-872c-ba4513834339', '和李使君三郎早秋城北亭樓宴崔司士因寄關中弟張評事時遇', '和李使君三郎早秋城北亭楼宴崔司士因寄关中弟張評事时遇', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["黃花古城路，上盡見青山。","桑柘晴川口，牛羊落照間。","野情隨卷幔，軍士隔重關。","道合偏多賞，官微獨不閑。","鶴分琴久罷，書到鴈應還。","爲謝登龍客，瓊枝寄一攀。"]', '["黄花古城路，上尽见青山。","桑柘晴川口，牛羊落照间。","野情隨卷幔，軍士隔重关。","道合偏多賞，官微独不闲。","鹤分琴久罷，书到鴈應還。","爲謝登龙客，瓊枝寄一攀。"]', '诗', 'shi', '', NULL, '和李使君三郎早秋城北亭樓宴崔司士因寄關中弟張評事時遇 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b065fd72-f420-4476-b08f-b1e469421154', '和趙端公九日登石亭上和州家兄', '和趙端公九日登石亭上和州家兄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["洛浦想江津，悲懽共此辰。","採花湖岸菊，望國舊樓人。","鴈別聲偏苦，松寒色轉新。","傳書問漁叟，借寇爾何因。"]', '["洛浦想江津，悲懽共此辰。","採花湖岸菊，望国旧楼人。","鴈別声偏苦，松寒色轉新。","傳书问漁叟，借寇爾何因。"]', '诗', 'shi', '', NULL, '和趙端公九日登石亭上和州家兄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f83eb9a-3855-4c71-b041-3930a9a7af6b', '酬趙少尹戲示諸姪元陽等因以見贈', '酬趙少尹戲示諸姪元陽等因以见贈', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["八龍三虎儼成行，瓊樹花開鶴翼張。","且請同觀舞鸜鵒，何須竟哂食檳榔。","歸時每愛懷朱橘，戲處常聞佩紫囊。","謬入阮家逢慶樂，竹林因得奉壺觴。"]', '["八龙三虎儼成行，瓊樹花开鹤翼張。","且請同观舞鸜鵒，何須竟哂食檳榔。","归时每愛懷朱橘，戲处常闻佩紫囊。","謬入阮家逢慶乐，竹林因得奉壺觴。"]', '诗', 'shi', '', NULL, '酬趙少尹戲示諸姪元陽等因以見贈 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089d0bcb-2a45-4012-b073-5ab3e3dabeb9', '奉和戶曹叔夏夜寓直寄呈同曹諸公幷見示', '奉和戶曹叔夏夜寓直寄呈同曹諸公幷见示', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["歛板捧清詞，恭聞侍直時。","暮塵歸衆騎，邃宇捨諸司。","華月先燈至，清風與簟隨。","亂螢光熠熠，行樹影離離。","龍臥人寧識，鵬摶鷃豈知。","便因當五夜，敢望竹林期。"]', '["歛板捧清词，恭闻侍直时。","暮塵归衆騎，邃宇捨諸司。","华月先灯至，清风與簟隨。","亂螢光熠熠，行樹影離離。","龙臥人寧識，鵬摶鷃豈知。","便因當五夜，敢望竹林期。"]', '诗', 'shi', '', NULL, '奉和戶曹叔夏夜寓直寄呈同曹諸公幷見示 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e09aa83-4156-40d8-b632-18c601d5ddd4', '和金吾裴將軍使往河北宣慰因訪張氏昆季舊居兼寄趙侍郎趙卿拜陵未迴', '和金吾裴將軍使往河北宣慰因訪張氏昆季旧居兼寄趙侍郎趙卿拜陵未迴', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["飛軒不駐輪，感激漢儒臣。","氣懾千夫勇，恩傳萬里春。","古原收野燎，寒笛怨空鄰。","書此達良友，五陵風雨頻。"]', '["飞軒不駐輪，感激漢儒臣。","氣懾千夫勇，恩傳万里春。","古原收野燎，寒笛怨空鄰。","书此達良友，五陵风雨頻。"]', '诗', 'shi', '', NULL, '和金吾裴將軍使往河北宣慰因訪張氏昆季舊居兼寄趙侍郎趙卿拜陵未迴 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba87093f-936d-411c-badb-8c3003ae0fdb', '和太常李主簿秋中山下別墅即事', '和太常李主簿秋中山下別墅即事', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["清秋來幾時，宋玉已先知。","曠朗霞映竹，澄明山滿池。","葺橋雙鶴赴，收果衆猨隨。","韶樂方今奏，雲林徒蔽虧。"]', '["清秋来幾时，宋玉已先知。","曠朗霞映竹，澄明山满池。","葺橋雙鹤赴，收果衆猨隨。","韶乐方今奏，云林徒蔽虧。"]', '诗', 'shi', '', NULL, '和太常李主簿秋中山下別墅即事 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f12745a-3ef3-42fb-9a16-60e838ba3516', '詶韋渚秋夜有懷見寄', '詶韋渚秋夜有懷见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["蕭條良夜永，秋草對衰顏。","露下鳥初定，月明人自閑。","獨悲無舊業，共喜出時艱。","爲問功成後，同遊何處山。"]', '["蕭條良夜永，秋草对衰顏。","露下鸟初定，月明人自闲。","独悲無旧業，共喜出时艱。","爲问功成後，同游何处山。"]', '诗', 'shi', '', NULL, '詶韋渚秋夜有懷見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef4d4ca2-59ea-4c84-b360-b63252700998', '同吉中孚夢桃源 一', '同吉中孚梦桃源 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["春雨夜不散，夢中山亦陰。","雲中碧潭水，路暗紅花林。","花水自深淺，無人知古今。"]', '["春雨夜不散，梦中山亦陰。","云中碧潭水，路暗紅花林。","花水自深淺，無人知古今。"]', '诗', 'shi', '', NULL, '同吉中孚夢桃源 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('738fc3d5-b2e3-4f00-8a81-496c103cdd58', '同吉中孚夢桃源 二', '同吉中孚梦桃源 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["夜靜春夢長，夢逐仙山客。","園林滿芝朮，雞犬傍籬柵。","幾處花下人，看予笑頭白。"]', '["夜静春梦长，梦逐仙山客。","园林满芝朮，雞犬傍籬柵。","幾处花下人，看予笑头白。"]', '诗', 'shi', '', NULL, '同吉中孚夢桃源 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7686a0a-7362-4c2f-94d2-e18d8640534a', '同柳侍郎題侯釗侍郎新昌里', '同柳侍郎題侯釗侍郎新昌里', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["清源君子居，左右盡圖書。","三逕春自足，一飄歡有餘。","庭莎成野席，闌藥是家蔬。","幽顯豈殊迹，昔賢徒病諸。"]', '["清源君子居，左右尽圖书。","三逕春自足，一飄歡有餘。","庭莎成野席，闌藥是家蔬。","幽显豈殊迹，昔賢徒病諸。"]', '诗', 'shi', '', NULL, '同柳侍郎題侯釗侍郎新昌里 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ea4507-5110-4770-beaf-12ff42e511b1', '詶孫侍御春日見寄', '詶孫侍御春日见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["經過里巷春，同是謝家鄰。","願我覺衰早，荷君留醉頻。","松高猶覆草，鶴起暫縈塵。","始悟達人志，患名非患貧。"]', '["經過里巷春，同是謝家鄰。","願我覺衰早，荷君留醉頻。","松高猶覆草，鹤起暫縈塵。","始悟達人志，患名非患貧。"]', '诗', 'shi', '', NULL, '詶孫侍御春日見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ae1fbb-2b3a-43c9-818e-bf8bc851e13d', '和王員外冬夜寓直', '和王員外冬夜寓直', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高步長裾錦帳郎，居然自是漢賢良。","潘岳敘年因鬢髮，揚雄託諫在文章。","九天韶樂飄寒月，萬戶香塵裛曉霜。","坐見重門儼朝騎，可憐雲路獨翺翔。"]', '["高步长裾錦帳郎，居然自是漢賢良。","潘岳敘年因鬢髮，揚雄託諫在文章。","九天韶乐飄寒月，万戶香塵裛晓霜。","坐见重门儼朝騎，可怜云路独翺翔。"]', '诗', 'shi', '', NULL, '和王員外冬夜寓直 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7b45a8-c4df-4a01-89e8-5e5578683daa', '詶金部王郎中省中春日見寄', '詶金部王郎中省中春日见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["南宮樹色曉森森，雖有春光未有陰。","鶴侶正疑芳景引，玉人那爲簿書沈。","山含瑞氣偏當日，鶯逐輕風不在林。","更有阮郎迷路處，萬株紅樹一溪深。"]', '["南宮樹色晓森森，雖有春光未有陰。","鹤侶正疑芳景引，玉人那爲簿书沈。","山含瑞氣偏當日，鶯逐轻风不在林。","更有阮郎迷路处，万株紅樹一溪深。"]', '诗', 'shi', '', NULL, '詶金部王郎中省中春日見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e6b7b3-2a83-4c52-ad75-3cfc8dd085fb', '奉和陝州十四翁中丞寄雷州二十翁司戶', '奉和陝州十四翁中丞寄雷州二十翁司戶', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["聯飛獨不前，迥落海南天。","賈傅竟行矣，邵公唯泫然。","瘴開山更遠，路極水無邊。","沈劣本多感，況聞原上篇。"]', '["聯飞独不前，迥落海南天。","賈傅竟行矣，邵公唯泫然。","瘴开山更远，路極水無邊。","沈劣本多感，況闻原上篇。"]', '诗', 'shi', '', NULL, '奉和陝州十四翁中丞寄雷州二十翁司戶 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246d388f-1a6f-4b5d-a153-617a64578503', '和李中丞詶萬年房署少府過汾州景雲觀因以寄上房與李早年同居此觀', '和李中丞詶万年房署少府過汾州景云观因以寄上房與李早年同居此观', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["顯晦澹無迹，賢哉常晏如。","如何警孤鶴，忽乃傳雙魚。","敘以泉石舊，悵然風景餘。","低回青油幕，夢寐白雲居。","玉洞桂香滿，雪壇松影疎。","沈思矚仙侶，紓組正軍書。","積學早成道，感恩難遂初。","梅生諒多感，歸止豈吾廬。"]', '["显晦澹無迹，賢哉常晏如。","如何警孤鹤，忽乃傳雙鱼。","敘以泉石旧，悵然风景餘。","低回青油幕，梦寐白云居。","玉洞桂香满，雪壇松影疎。","沈思矚仙侶，紓組正軍书。","積学早成道，感恩难遂初。","梅生諒多感，归止豈吾廬。"]', '诗', 'shi', '', NULL, '和李中丞詶萬年房署少府過汾州景雲觀因以寄上房與李早年同居此觀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('015761cf-2c04-44fa-8974-aafe4fa19be3', '詶陳翃郎中冬至攜柳郎竇郎歸河中舊居見寄', '詶陳翃郎中冬至携柳郎竇郎归河中旧居见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["三旬一休沐，清景滿林廬。","南郭羣儒從，東牀兩客居。","燒煙浮雪野，麥隴潤冰渠。","班白皆持酒，蓬茅盡有書。","終期買寒渚，同此利蒲魚。"]', '["三旬一休沐，清景满林廬。","南郭羣儒從，东牀兩客居。","燒煙浮雪野，麦隴潤冰渠。","班白皆持酒，蓬茅尽有书。","終期買寒渚，同此利蒲鱼。"]', '诗', 'shi', '', NULL, '詶陳翃郎中冬至攜柳郎竇郎歸河中舊居見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c2d6f0-617e-4bf9-a17b-470adf7131d7', '詶李益端公夜宴見贈', '詶李益端公夜宴见贈', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["戚戚一西東，十年今始同。","可憐歌酒夜，相對兩衰翁。"]', '["戚戚一西东，十年今始同。","可怜歌酒夜，相对兩衰翁。"]', '诗', 'shi', '', NULL, '詶李益端公夜宴見贈 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6727d4be-e69f-40c9-b0ce-f3c2e0c65143', '和陳翃郎中拜本府少尹兼侍御史獻上侍中因呈同院諸公', '和陳翃郎中拜本府少尹兼侍御史獻上侍中因呈同院諸公', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["金印垂鞍白馬肥，不同疏廣老方歸。","三千士裏文章伯，四十年來錦繡衣。","節比青松當澗直，心隨黃雀繞簷飛。","鄉中賀者唯爭路，不識傳呼獬豸威。"]', '["金印垂鞍白马肥，不同疏廣老方归。","三千士裏文章伯，四十年来錦繡衣。","節比青松當澗直，心隨黄雀繞簷飞。","乡中賀者唯爭路，不識傳呼獬豸威。"]', '诗', 'shi', '', NULL, '和陳翃郎中拜本府少尹兼侍御史獻上侍中因呈同院諸公 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dfa55a6-539d-4845-8345-a0b0ef54aabf', '和王倉少尹暇日言懷', '和王倉少尹暇日言懷', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["清秋多暇日，況乃是夫君。","習靜通仙事，書空閱篆文。","劒飛終上漢，鶴夢不離雲。","無限煙霄路，何嗟迹未分。"]', '["清秋多暇日，況乃是夫君。","習静通仙事，书空閱篆文。","劒飞終上漢，鹤梦不離云。","無限煙霄路，何嗟迹未分。"]', '诗', 'shi', '', NULL, '和王倉少尹暇日言懷 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c653586e-9b23-4c63-999c-d0a29808e14b', '和崔侍郎遊萬固寺', '和崔侍郎游万固寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["聞說中方高樹林，曙華先照囀春禽。","風雲才子冶遊思，蒲柳老人惆悵心。","石路青苔花漫漫，雪簷垂溜玉森森。","賀君此去君方至，河水東流西日沈。"]', '["闻说中方高樹林，曙华先照囀春禽。","风云才子冶游思，蒲柳老人惆悵心。","石路青苔花漫漫，雪簷垂溜玉森森。","賀君此去君方至，河水东流西日沈。"]', '诗', 'shi', '', NULL, '和崔侍郎遊萬固寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412f8f86-fdee-4f41-ac00-b5f134ea11c3', '和裴延齡尚書寄題果州謝舍人仙居', '和裴延齡尚书寄題果州謝舍人仙居', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["飄然去謁八仙翁，自地從天香滿空。","紫蓋迥標雙鶴上，語音猶在五雲中。","青溪不接漁樵路，丹井唯傳草木風。","歌此因思捧金液，露盤長慶漢皇宮。"]', '["飄然去謁八仙翁，自地從天香满空。","紫蓋迥標雙鹤上，語音猶在五云中。","青溪不接漁樵路，丹井唯傳草木风。","歌此因思捧金液，露盤长慶漢皇宮。"]', '诗', 'shi', '', NULL, '和裴延齡尚書寄題果州謝舍人仙居 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cf6d87-a180-405b-941e-9ed8a5ed7146', '詶崔侍御早秋臥病書情見寄時君亦抱疾在假中', '詶崔侍御早秋臥病书情见寄时君亦抱疾在假中', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["擲地金聲信有之，瑩然冰玉見清詞。","元凱癖成官始貴，相如渴甚貌逾衰。","荒園每覺蟲鳴早，華館常聞客散遲。","寂寞罷琴風滿樹，幾多黃葉落蛛絲。"]', '["擲地金声信有之，瑩然冰玉见清词。","元凱癖成官始貴，相如渴甚貌逾衰。","荒园每覺蟲鳴早，华館常闻客散遲。","寂寞罷琴风满樹，幾多黄葉落蛛絲。"]', '诗', 'shi', '', NULL, '詶崔侍御早秋臥病書情見寄時君亦抱疾在假中 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa8c472-79b3-4383-ab05-f1435539897a', '詶靈澈上人', '詶靈澈上人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["軍人奉役本無期，落葉花開總不知。","走馬城中頭雪白，若爲將面見湯師。"]', '["軍人奉役本無期，落葉花开總不知。","走马城中头雪白，若爲將面见湯師。"]', '诗', 'shi', '', NULL, '詶靈澈上人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2e11c61-f2e3-455d-bbad-c8d74a3bc578', '敬詶大府二十四舅覽詩卷因以見示', '敬詶大府二十四舅覽诗卷因以见示', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["郄公憐戇亦憐愚，忽贈金盤徑寸珠。","徹底碧潭滋涸溜，壓枝紅豔照枯株。","九門洞啓延高論，百辟聯行挹大儒。","顧己文章非酷似，敢將幽劣俟洪爐。"]', '["郄公怜戇亦怜愚，忽贈金盤徑寸珠。","徹底碧潭滋涸溜，壓枝紅豔照枯株。","九门洞啓延高論，百辟聯行挹大儒。","顧己文章非酷似，敢將幽劣俟洪爐。"]', '诗', 'shi', '', NULL, '敬詶大府二十四舅覽詩卷因以見示 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e36ecfc7-f33c-4091-b1a1-ca0451106ac1', '雨中酬友人', '雨中酬友人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["看山獨行歸竹院，水遶前堦草生遍。","空林細雨暗無聲，唯有愁心兩相見。"]', '["看山独行归竹院，水遶前堦草生遍。","空林細雨暗無声，唯有愁心兩相见。"]', '诗', 'shi', '', NULL, '雨中酬友人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0524aa8b-ee7d-44e6-a9bb-d52e213faeb9', '詶人失題', '詶人失題', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["孤鸞將鶴羣，晴日麗春雲。","何幸晚飛者，清音長此聞。"]', '["孤鸾將鹤羣，晴日丽春云。","何幸晚飞者，清音长此闻。"]', '诗', 'shi', '', NULL, '詶人失題 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3963634a-eeb5-4f05-b1e4-05bf1aedeb0c', '哭司農苗主簿', '哭司農苗主簿', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["原頭殯御遶新塋，原下行人望哭聲。","更想秋山連古木，唯應石上見君名。"]', '["原头殯御遶新塋，原下行人望哭声。","更想秋山連古木，唯應石上见君名。"]', '诗', 'shi', '', NULL, '哭司農苗主簿 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a1ab97-d8c8-4380-b75e-c95a9337f5c7', '得耿湋司法書因敘長安故友零落兵部苗員外發祕省李校書端相次傾逝潞府崔功曹峒長林司空丞曙俱謫遠方余以搖落之時對書增歎因呈河中鄭倉曹暢參軍昆季', '得耿湋司法书因敘长安故友零落兵部苗員外發祕省李校书端相次傾逝潞府崔功曹峒长林司空丞曙俱謫远方余以搖落之时对书增歎因呈河中鄭倉曹暢參軍昆季', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鬢似衰蓬心似灰，驚悲相集老相催。","故友九泉留語別，逐臣千里寄書來。","塵容帶病何堪問，淚眼逢秋不喜開。","幸接野居宜屣步，冀君清夜一申哀。"]', '["鬢似衰蓬心似灰，驚悲相集老相催。","故友九泉留語別，逐臣千里寄书来。","塵容带病何堪问，泪眼逢秋不喜开。","幸接野居宜屣步，冀君清夜一申哀。"]', '诗', 'shi', '', NULL, '得耿湋司法書因敘長安故友零落兵部苗員外發祕省李校書端相次傾逝潞府崔功曹峒長林司空丞曙俱謫遠方余以搖落之時對書增歎因呈河中鄭倉曹暢參軍昆季 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75188bd-f549-459c-bdd6-61aec76cef31', '同兵部李紓侍郎刑部包佶侍郎哭皇甫侍御曾', '同兵部李紓侍郎刑部包佶侍郎哭皇甫侍御曾', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["攀龍與泣麟，哀樂不同塵。","九陌霄漢侶，一燈冥漠人。","舟沈驚海闊，蘭折怨霜頻。","已矣復何見，故山應更春。"]', '["攀龙與泣麟，哀乐不同塵。","九陌霄漢侶，一灯冥漠人。","舟沈驚海闊，蘭折怨霜頻。","已矣复何见，故山應更春。"]', '诗', 'shi', '', NULL, '同兵部李紓侍郎刑部包佶侍郎哭皇甫侍御曾 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b91ff41f-b0e8-404c-a50c-c0a288abe784', '綸與吉侍郎中孚司空郎中曙苗員外發崔補闕峒耿拾遺湋李校書端風塵追遊向三十載數公皆負當時盛稱榮耀未幾俱沈下泉暢博士當感懷前蹤有五十韻見寄輙有所詶以申悲舊兼寄夏侯侍御審侯倉曹釗', '綸與吉侍郎中孚司空郎中曙苗員外發崔補闕峒耿拾遺湋李校书端风塵追游向三十載數公皆負當时盛稱榮耀未幾俱沈下泉暢博士當感懷前蹤有五十韻见寄輙有所詶以申悲旧兼寄夏侯侍御審侯倉曹釗', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["稟命孤且賤，少爲病所嬰。","八歲始讀書，四方遂有兵。","童心幸不羈，此去負平生。","是月胡入洛，明年天隕星。","夜行登灞陵，惝怳靡所征。","雲海一翻蕩，魚龍俱不寧。","因浮襄江流，遠寄鄱陽城。","鄱陽富學徒，誚我戇無營。","諭以詩禮義，朂隨賓薦名。","舟車更滯留，水陸互陰晴。","曉望怯雲陣，夜愁驚鶴聲。","淒淒指宋郊，浩浩入秦京。","沴氣既風散，皇威如日明。","方逢粟比金，未識公與卿。","十上不可待，三年竟無成。","偶爲達者知，揚我于王廷。","素志且不立，青袍徒見縈。","昏孱夙自保，靜躁本殊形。","始趨甘棠陰，旋遇密人迎。","考實績無取，責能才固輕。","新豐古離宮，宮樹鎖雲扃。","中復蒞茲邑，往惟曾所經。","繚垣何逶迤，水殿亦崢嶸。","夜雨滴金砌，陰風吹玉楹。","官曹雖檢率，國步日夷平。","命蹇固安分，禍來非有萌。","因逢駭浪飄，幾落無辜刑。","巍巍登壇臣，獨正天柱傾。","悄悄失途子，分將秋草幷。","百年甘守素，一顧乃拾青。","相逢十月交，衆卉飄已零。","感舊諒戚戚，問孤懇煢煢。","侍郎文章宗，傑出淮楚靈。","掌賦若吹籟，司言如建瓴。","郎中善餘慶，雅韻與琴清。","鬱鬱松帶雪，蕭蕭鴻入冥。","員外真貴儒，弱冠被華纓。","月香飄桂實，乳溜滴瓊英。","補闕思沖融，巾拂藝亦精。","綵蝶戲芳圃，瑞雲凝翠屏。","拾遺興難侔，逸調曠無程。","九醞貯彌潔，三花寒轉馨。","校書才智雄，舉世一娉婷。","賭墅鬼神變，屬詞鸞鳳驚。","差肩曳長裾，總轡奉和鈴。","共賦瑤臺雪，同觀金谷箏。","倚天方比劒，沈井忽如瓶。","神昧不可問，天高莫爾聽。","君持玉盤珠，瀉我懷袖盈。","讀罷涕交頤，願言躋百齡。"]', '["稟命孤且賤，少爲病所嬰。","八歲始读书，四方遂有兵。","童心幸不羈，此去負平生。","是月胡入洛，明年天隕星。","夜行登灞陵，惝怳靡所征。","云海一翻蕩，鱼龙俱不寧。","因浮襄江流，远寄鄱陽城。","鄱陽富学徒，誚我戇無營。","諭以诗禮義，朂隨賓薦名。","舟车更滯留，水陸互陰晴。","晓望怯云陣，夜愁驚鹤声。","淒淒指宋郊，浩浩入秦京。","沴氣既风散，皇威如日明。","方逢粟比金，未識公與卿。","十上不可待，三年竟無成。","偶爲達者知，揚我于王廷。","素志且不立，青袍徒见縈。","昏孱夙自保，静躁本殊形。","始趨甘棠陰，旋遇密人迎。","考實績無取，責能才固轻。","新豐古離宮，宮樹鎖云扃。","中复蒞茲邑，往惟曾所經。","繚垣何逶迤，水殿亦崢嶸。","夜雨滴金砌，陰风吹玉楹。","官曹雖檢率，国步日夷平。","命蹇固安分，禍来非有萌。","因逢駭浪飄，幾落無辜刑。","巍巍登壇臣，独正天柱傾。","悄悄失途子，分將秋草幷。","百年甘守素，一顧乃拾青。","相逢十月交，衆卉飄已零。","感旧諒戚戚，问孤懇煢煢。","侍郎文章宗，傑出淮楚靈。","掌賦若吹籟，司言如建瓴。","郎中善餘慶，雅韻與琴清。","鬱鬱松带雪，蕭蕭鴻入冥。","員外真貴儒，弱冠被华纓。","月香飄桂實，乳溜滴瓊英。","補闕思沖融，巾拂藝亦精。","綵蝶戲芳圃，瑞云凝翠屏。","拾遺兴难侔，逸調曠無程。","九醞貯彌潔，三花寒轉馨。","校书才智雄，舉世一娉婷。","賭墅鬼神变，屬词鸾鳳驚。","差肩曳长裾，總轡奉和鈴。","共賦瑤台雪，同观金谷箏。","倚天方比劒，沈井忽如瓶。","神昧不可问，天高莫爾听。","君持玉盤珠，瀉我懷袖盈。","读罷涕交頤，願言躋百齡。"]', '诗', 'shi', '', NULL, '綸與吉侍郎中孚司空郎中曙苗員外發崔補闕峒耿拾遺湋李校書端風塵追遊向三十載數公皆負當時盛稱榮耀未幾俱沈下泉暢博士當感懷前蹤有五十韻見寄輙有所詶以申悲舊兼寄夏侯侍御審侯倉曹釗 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd8df32-0601-4f93-b0d9-37ce1f01be95', '詶李叔度秋夜喜相遇因傷關東僚友喪逝見贈', '詶李叔度秋夜喜相遇因傷关东僚友喪逝见贈', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["寒月照秋城，秋風泉澗鳴。","過時見蘭蕙，獨夜感衰榮。","酒散同移疾，心悲似遠行。","以愚求作友，何德敢稱兄。","谷變波長急，松枯藥未成。","恐看新鬢色，怯問故人名。","野澤雲陰散，荒原日氣生。","羈飛本難定，非是惡弦驚。"]', '["寒月照秋城，秋风泉澗鳴。","過时见蘭蕙，独夜感衰榮。","酒散同移疾，心悲似远行。","以愚求作友，何德敢稱兄。","谷变波长急，松枯藥未成。","恐看新鬢色，怯问故人名。","野澤云陰散，荒原日氣生。","羈飞本难定，非是惡弦驚。"]', '诗', 'shi', '', NULL, '詶李叔度秋夜喜相遇因傷關東僚友喪逝見贈 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72524f5-d40b-4922-99ae-861a0fb0c509', '同李益傷秋', '同李益傷秋', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["歲去人頭白，秋來樹葉黃。","搔頭向黃葉，與爾共悲傷。"]', '["歲去人头白，秋来樹葉黄。","搔头向黄葉，與爾共悲傷。"]', '诗', 'shi', '', NULL, '同李益傷秋 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1092a9c6-64db-4054-aafb-291adc717d8a', '白髮嘆', '白髮嘆', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["髮白曉梳頭，女驚妻淚流。","不知絲色後，堪得幾回秋。"]', '["髮白晓梳头，女驚妻泪流。","不知絲色後，堪得幾回秋。"]', '诗', 'shi', '', NULL, '白髮嘆 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb5c9df-2eb5-4dd6-bf38-0b01d4081f6d', '逢病軍人', '逢病軍人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["行多有病住無糧，萬里還鄉未到鄉。","蓬鬢哀吟古城下，不堪秋氣入金瘡。"]', '["行多有病住無糧，万里還乡未到乡。","蓬鬢哀吟古城下，不堪秋氣入金瘡。"]', '诗', 'shi', '', NULL, '逢病軍人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1dce3e-e0f6-4da4-b110-e8686d1c1119', '村南逢病叟', '村南逢病叟', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雙膝過頤頂在肩，四鄰知姓不知年。","臥驅鳥雀惜禾黍，猶恐諸孫無社錢。"]', '["雙膝過頤頂在肩，四鄰知姓不知年。","臥驱鸟雀惜禾黍，猶恐諸孫無社錢。"]', '诗', 'shi', '', NULL, '村南逢病叟 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9402122-80d2-4755-9cf1-1a6bd5a9a6de', '七夕詩', '七夕诗', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["祥光若可求，閨女夜登樓。","月露浩方下，河雲凝不流。","鉛華潛警曙，機杼暗傳秋。","迴想歛餘睠，人天俱是愁。"]', '["祥光若可求，閨女夜登楼。","月露浩方下，河云凝不流。","鉛华潛警曙，機杼暗傳秋。","迴想歛餘睠，人天俱是愁。"]', '诗', 'shi', '', NULL, '七夕詩 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2b993c-ca63-4e68-bcce-20f953689061', '七夕詩', '七夕诗', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["涼風吹玉露，河漢有幽期。","星彩光仍隱，雲容掩復離。","良宵驚曙早，閏歲怨秋遲。","何事金閨子，空傳得網絲。"]', '["涼风吹玉露，河漢有幽期。","星彩光仍隐，云容掩复離。","良宵驚曙早，閏歲怨秋遲。","何事金閨子，空傳得網絲。"]', '诗', 'shi', '', NULL, '七夕詩 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7751487-3843-42df-a0ff-1dba49722fa7', '長門怨', '长门怨', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["空空古廊殿，寒月落斜暉。","臥聽未央曲，滿箱歌舞衣。"]', '["空空古廊殿，寒月落斜暉。","臥听未央曲，满箱歌舞衣。"]', '诗', 'shi', '', NULL, '長門怨 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d462584-b67d-405d-941a-a59f28f03d94', '妾薄命', '妾薄命', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["妾年初二八，兩度嫁狂夫。","薄命今猶在，堅貞掃地無。"]', '["妾年初二八，兩度嫁狂夫。","薄命今猶在，堅貞掃地無。"]', '诗', 'shi', '', NULL, '妾薄命 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a49c55f-ed4f-4f9c-8662-db588b07163b', '倫開府席上賦得詠美人名解愁', '倫开府席上賦得詠美人名解愁', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["不敢苦相留，明知不自由。","嚬眉乍欲語，歛笑又低頭。","舞態兼些醉，歌聲似帶羞。","今朝總見也，只不解人愁。"]', '["不敢苦相留，明知不自由。","嚬眉乍欲語，歛笑又低头。","舞態兼些醉，歌声似带羞。","今朝總见也，只不解人愁。"]', '诗', 'shi', '', NULL, '倫開府席上賦得詠美人名解愁 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25178caa-eeb3-44b5-a538-725e4ce06950', '王評事駙馬花燭詩 一', '王評事駙马花燭诗 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["萬條銀燭引天人，十月長安半夜春。","步障三千隘將斷，幾多珠翠落香塵。"]', '["万條銀燭引天人，十月长安半夜春。","步障三千隘將斷，幾多珠翠落香塵。"]', '诗', 'shi', '', NULL, '王評事駙馬花燭詩 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('869d28be-f4c6-4370-ad21-272fac45cfbf', '王評事駙馬花燭詩 二', '王評事駙马花燭诗 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["一人女壻萬人憐，一夜調疎抵百年。","爲報司徒好將息，明珠解轉又能圓。"]', '["一人女壻万人怜，一夜調疎抵百年。","爲報司徒好將息，明珠解轉又能圓。"]', '诗', 'shi', '', NULL, '王評事駙馬花燭詩 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfe365b-47f5-46c8-bde6-e49325ec8d9a', '王評事駙馬花燭詩 三', '王評事駙马花燭诗 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["人主人臣是親家，千秋萬歲保榮華。","幾時曾向高天上，得見今宵月裏花。"]', '["人主人臣是親家，千秋万歲保榮华。","幾时曾向高天上，得见今宵月裏花。"]', '诗', 'shi', '', NULL, '王評事駙馬花燭詩 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70499d47-c193-4631-915f-262d7054f691', '王評事駙馬花燭詩 四', '王評事駙马花燭诗 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["比翼和鳴雙鳳皇，欲棲金帳滿城香。","平明却入天泉裏，日氣曈曨五色光。"]', '["比翼和鳴雙鳳皇，欲棲金帳满城香。","平明却入天泉裏，日氣曈曨五色光。"]', '诗', 'shi', '', NULL, '王評事駙馬花燭詩 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ac328e-9028-4ed3-9929-20caeac0360c', '和趙給事白蠅拂歌', '和趙給事白蠅拂歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["華堂多衆珍，白拂稱殊異。","柄裁沈節香襲人，上結爲文下垂穗。","霜縷霏微瑩且柔，虎鬚乍細龍髯稠。","皎然素色不因染，淅爾涼風非爲秋。","羣蠅青蒼恣遊息，廣庖萬品無顏色。","金屏成點玉成瑕，晝眠宛轉空咨嗟。","此時滿筵看一舉，荻花忽旋楊花舞。","砉如寒隼驚暮禽，颯若繁埃得輕雨。","主人說是故人留，每誡如新比白頭。","若將揮玩閑臨水，願接波中一白鷗。"]', '["华堂多衆珍，白拂稱殊異。","柄裁沈節香襲人，上結爲文下垂穗。","霜縷霏微瑩且柔，虎鬚乍細龙髯稠。","皎然素色不因染，淅爾涼风非爲秋。","羣蠅青蒼恣游息，廣庖万品無顏色。","金屏成点玉成瑕，晝眠宛轉空咨嗟。","此时满筵看一舉，荻花忽旋楊花舞。","砉如寒隼驚暮禽，颯若繁埃得轻雨。","主人说是故人留，每誡如新比白头。","若將揮玩闲臨水，願接波中一白鷗。"]', '诗', 'shi', '', NULL, '和趙給事白蠅拂歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('504f86af-688b-4077-91e2-a7e62f7d8ebf', '蕭常侍癭柏亭歌', '蕭常侍癭柏亭歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["柏之異者山中靈，何人斷絕爲君亭。","雲翻浪卷不可識，鳥獸成形花倒植。","莓苔舊點色尚青，霹靂殘痕節猶黑。","金貂主人漢三老，構此窮年下朝早。","心規目製不暫疲，匠者受之無一詞。","清晨拂匣菱生鏡，落日憑闌星滿池。","攢甍鬬拱無斤跡，根癭聯懸同素壁。","數層亂瀉雲裏峯，萬片爭呈雪中石。","重簾不動自飄香，似到瀛洲白玉堂。","水精如意刁金色，雲母屏風透掩光。","四堦綿綿被纖草，草上依微衆山道。","松間汲井煙翠寒，洞裏圍碁天景好。","愚儒敢欲賀成功，鸞鳳棲翔固不同。","應念廢材今接地，一枝思寄戶庭中。"]', '["柏之異者山中靈，何人斷絕爲君亭。","云翻浪卷不可識，鸟獸成形花倒植。","莓苔旧点色尚青，霹靂殘痕節猶黑。","金貂主人漢三老，構此窮年下朝早。","心規目製不暫疲，匠者受之無一词。","清晨拂匣菱生镜，落日憑闌星满池。","攢甍鬬拱無斤跡，根癭聯懸同素壁。","數層亂瀉云裏峯，万片爭呈雪中石。","重簾不动自飄香，似到瀛洲白玉堂。","水精如意刁金色，云母屏风透掩光。","四堦綿綿被纖草，草上依微衆山道。","松间汲井煙翠寒，洞裏圍碁天景好。","愚儒敢欲賀成功，鸾鳳棲翔固不同。","應念廢材今接地，一枝思寄戶庭中。"]', '诗', 'shi', '', NULL, '蕭常侍癭柏亭歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a62a396-b658-4be2-aa22-46516a64676d', '慈恩寺石磬歌', '慈恩寺石磬歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["靈山石磬生海西，海濤平處與山齊。","長眉老僧同佛力，呪使鮫人往求得。","珠穴沈成綠浪痕，天衣拂盡蒼苔色。","星漢徘徊山有風，禪翁靜扣月明中。","羣仙下雲龍出水，鸞鶴交飛半空裏。","山精木魅不可聽，落葉秋砧一時起。","花宮杳杳響泠泠，無數沙門昏夢醒。","古廊燈下見行道，疎林池邊聞誦經。","徒壯洪鐘祕高閣，萬金費盡工雕鑿。","豈如全質挂青松，數葉殘雲一片峯。","吾師寶之壽中國，願同劫石無終極。"]', '["靈山石磬生海西，海濤平处與山齊。","长眉老僧同佛力，呪使鮫人往求得。","珠穴沈成綠浪痕，天衣拂尽蒼苔色。","星漢徘徊山有风，禪翁静扣月明中。","羣仙下云龙出水，鸾鹤交飞半空裏。","山精木魅不可听，落葉秋砧一时起。","花宮杳杳响泠泠，無數沙门昏梦醒。","古廊灯下见行道，疎林池邊闻誦經。","徒壯洪鐘祕高閣，万金費尽工雕鑿。","豈如全質挂青松，數葉殘云一片峯。","吾師寶之壽中国，願同劫石無終極。"]', '诗', 'shi', '', NULL, '慈恩寺石磬歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1df671-910d-4111-9d6b-b002d51f5dff', '送張郎中還蜀歌', '送張郎中還蜀歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["秦家御史漢家郎，親專兩印征殊方。","功成走馬朝天子，伏檻論邊若流水。","曉離僊署趨紫微，夜接高儒讀青史。","瀘南五將望君還，願以天書示百蠻。","曲棧重江初過雨，前旌後騎不同山。","迎車拜舞多耆老，舊卒新營遍青草。","塞口雲生火候遲，煙中鶴唳軍行早。","黃花川下水交橫，遠映孤霞蜀國晴。","邛竹筍長椒瘴起，荔枝花發杜鵑鳴。","迴首岷峨半天黑，傳觴接膝何由得。","空令豪士仰威名，無復貧交恃顏色。","垂楊不動雨紛紛，錦帳胡瓶爭送君。","須臾醉起簫笳發，空見紅旌入白雲。"]', '["秦家御史漢家郎，親專兩印征殊方。","功成走马朝天子，伏檻論邊若流水。","晓離僊署趨紫微，夜接高儒读青史。","瀘南五將望君還，願以天书示百蠻。","曲棧重江初過雨，前旌後騎不同山。","迎车拜舞多耆老，旧卒新營遍青草。","塞口云生火候遲，煙中鹤唳軍行早。","黄花川下水交橫，远映孤霞蜀国晴。","邛竹筍长椒瘴起，荔枝花發杜鵑鳴。","迴首岷峨半天黑，傳觴接膝何由得。","空令豪士仰威名，無复貧交恃顏色。","垂楊不动雨紛紛，錦帳胡瓶爭送君。","須臾醉起簫笳發，空见紅旌入白云。"]', '诗', 'shi', '', NULL, '送張郎中還蜀歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f79e6af-b9f2-4c6e-84d3-d345e546f87b', '宴席賦得姚美人拍箏歌', '宴席賦得姚美人拍箏歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["出簾仍有鈿箏隨，見罷翻令恨識遲。","微收皓腕纏紅袖，深遏朱弦低翠眉。","忽然高張應繁節，玉指迴旋若飛雪。","鳳簫韶管寂不喧，繡幕紗窗儼秋月。","有時輕弄和郎歌，慢處聲遲情更多。","已愁紅臉能佯醉，又恐朱門難再過。","昭陽伴裏最聰明，出到人間纔長成。","遙知禁曲難翻處，猶是君王說小名。"]', '["出簾仍有鈿箏隨，见罷翻令恨識遲。","微收皓腕纏紅袖，深遏朱弦低翠眉。","忽然高張應繁節，玉指迴旋若飞雪。","鳳簫韶管寂不喧，繡幕紗窗儼秋月。","有时轻弄和郎歌，慢处声遲情更多。","已愁紅臉能佯醉，又恐朱门难再過。","昭陽伴裏最聰明，出到人间纔长成。","遙知禁曲难翻处，猶是君王说小名。"]', '诗', 'shi', '', NULL, '宴席賦得姚美人拍箏歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7239ccda-ca26-4fdb-9542-8991cc908308', '陳翃郎中北亭送侯釗侍御賦得帶冰流歌', '陳翃郎中北亭送侯釗侍御賦得带冰流歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["溪中鳥鳴春景旦，一派寒冰忽開散。","璧方鏡員流不斷，白雲鱗鱗滿河漢。","疊處淺，旋處深。","撇捩寒魚上復沈，羣鵝鼓舞揚清音。","主人有客簪白筆，玉壺貯水光如一。","持此贈君君飲之，聖君識君冰玉姿。"]', '["溪中鸟鳴春景旦，一派寒冰忽开散。","璧方镜員流不斷，白云鱗鱗满河漢。","叠处淺，旋处深。","撇捩寒鱼上复沈，羣鵝鼓舞揚清音。","主人有客簪白笔，玉壺貯水光如一。","持此贈君君饮之，聖君識君冰玉姿。"]', '诗', 'shi', '', NULL, '陳翃郎中北亭送侯釗侍御賦得帶冰流歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96ea27ae-1f85-4a5f-a9c8-9dc195803c00', '棲巖寺隋文帝馬腦盞歌', '棲巖寺隋文帝马腦盞歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["天宮寶器隋朝物，鏁在金函比金骨。","開函捧之光乃發，阿修羅王掌中月。","五雲如拳輕復濃，昔曾噀酒今藏龍。","規形環影相透徹，亂雪繁花千萬重。","可憐貞質無今名，可嘆隋陵一抔土。","宮中豔女滿宮春，得親此寶能幾人。","一留寒殿殿將壞，唯有幽光通隙塵。","山中老僧眉似雪，忍死相傳保扃鐍。"]', '["天宮寶器隋朝物，鏁在金函比金骨。","开函捧之光乃發，阿修羅王掌中月。","五云如拳轻复濃，昔曾噀酒今藏龙。","規形环影相透徹，亂雪繁花千万重。","可怜貞質無今名，可嘆隋陵一抔土。","宮中豔女满宮春，得親此寶能幾人。","一留寒殿殿將壞，唯有幽光通隙塵。","山中老僧眉似雪，忍死相傳保扃鐍。"]', '诗', 'shi', '', NULL, '棲巖寺隋文帝馬腦盞歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b717c8-6254-4218-8b27-d4629e9e6e49', '難綰刀子歌', '难綰刀子歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["黃金鞘裏青蘆葉，麗若翦成銛且翣。","輕冰薄玉狀不分，一尺寒光堪決雲。","吹毛可試不可觸，似有蟲搜闕裂文。","淬之幾墮前池水，焉知不是蛟龍子。","割雞刺虎皆若空，願應君心逐君指。","幷州難綰竟何人，每成此物如有神。"]', '["黄金鞘裏青蘆葉，丽若翦成銛且翣。","轻冰薄玉狀不分，一尺寒光堪決云。","吹毛可試不可觸，似有蟲搜闕裂文。","淬之幾墮前池水，焉知不是蛟龙子。","割雞刺虎皆若空，願應君心逐君指。","幷州难綰竟何人，每成此物如有神。"]', '诗', 'shi', '', NULL, '難綰刀子歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f707e02-465c-43ed-8090-97ddb552d49e', '臘日觀咸寧王部曲娑勒擒豹歌', '臘日观咸寧王部曲娑勒擒豹歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["山頭曈曈日將出，山下獵圍照初日。","前林有獸未識名，將軍促騎無人聲。","潛形踠伏草不動，雙鵰旋轉羣鴉鳴。","陰方質子才三十，譯語受詞蕃語揖。","捨鞍解甲疾如風，人忽虎蹲獸人立。","歘然扼顙批其頤，爪牙委地涎淋漓。","既蘇復吼拗仍怒，果叶英謀生致之。","拖自深叢目如電，萬夫失容千馬戰。","傳呼賀拜聲相連，殺氣騰凌陰滿川。","始知縛虎如縛鼠，敗虜降羌生眼前。","祝爾嘉詞爾無苦，獻爾將隨犀象舞。","苑中流水禁中山，期爾攫搏開天顏。","非熊之兆慶無極，願紀雄名傳百蠻。"]', '["山头曈曈日將出，山下獵圍照初日。","前林有獸未識名，將軍促騎無人声。","潛形踠伏草不动，雙鵰旋轉羣鴉鳴。","陰方質子才三十，譯語受词蕃語揖。","捨鞍解甲疾如风，人忽虎蹲獸人立。","歘然扼顙批其頤，爪牙委地涎淋漓。","既蘇复吼拗仍怒，果叶英謀生致之。","拖自深叢目如電，万夫失容千马戰。","傳呼賀拜声相連，殺氣腾凌陰满川。","始知縛虎如縛鼠，敗虜降羌生眼前。","祝爾嘉词爾無苦，獻爾將隨犀象舞。","苑中流水禁中山，期爾攫搏开天顏。","非熊之兆慶無極，願紀雄名傳百蠻。"]', '诗', 'shi', '', NULL, '臘日觀咸寧王部曲娑勒擒豹歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef44f5be-493e-4ff9-b01a-5d98d783323f', '賦得白鷗歌送李伯康歸使', '賦得白鷗歌送李伯康归使', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["積水深源，白鷗翻翻。","倒影光素，于潭之間。","銜魚魚落亂驚鳴，爭撲蓮藂蓮葉傾。","爾不見波中鷗鳥閑無營，何必汲汲勞其生。","柳花冥濛大堤口，悠揚相和乍無有。","輕隨去浪杳不分，細舞清風亦何有。","似君換得白鵝時，獨凭闌干雪滿池。","今日還同看鷗鳥，如何羽翮復參差。","復參差，海濤瀾漫何由期。"]', '["積水深源，白鷗翻翻。","倒影光素，于潭之间。","銜鱼鱼落亂驚鳴，爭撲蓮藂蓮葉傾。","爾不见波中鷗鸟闲無營，何必汲汲勞其生。","柳花冥濛大堤口，悠揚相和乍無有。","轻隨去浪杳不分，細舞清风亦何有。","似君換得白鵝时，独凭闌干雪满池。","今日還同看鷗鸟，如何羽翮复參差。","复參差，海濤瀾漫何由期。"]', '诗', 'shi', '', NULL, '賦得白鷗歌送李伯康歸使 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c05d199-be70-4e04-b2bc-f7161e7bd561', '皇帝感詞 一', '皇帝感词 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["提劒風雷動，垂衣日月明。","禁花呈瑞色，國老見星精。","發棹魚先躍，窺巢鳥不驚。","山呼一萬歲，直入九重城。"]', '["提劒风雷动，垂衣日月明。","禁花呈瑞色，国老见星精。","發棹鱼先躍，窺巢鸟不驚。","山呼一万歲，直入九重城。"]', '诗', 'shi', '', NULL, '皇帝感詞 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02583ad3-2e64-4a5f-a99c-13177f8ef1da', '皇帝感詞 二', '皇帝感词 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["天香五鳳彩，御馬六龍文。","雨露清馳道，風雷翊上軍。","高旍花外轉，行漏樂前聞。","時見金鞭舉，空中指瑞雲。"]', '["天香五鳳彩，御马六龙文。","雨露清驰道，风雷翊上軍。","高旍花外轉，行漏乐前闻。","时见金鞭舉，空中指瑞云。"]', '诗', 'shi', '', NULL, '皇帝感詞 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28779907-c939-4880-95dd-473e44509ccc', '皇帝感詞 三', '皇帝感词 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["妙算干戈止，神謀宇宙清。","兩堦文物盛，七德武功成。","校獵長楊苑，屯軍細柳營。","歸來獻明主，歌舞溢春城。"]', '["妙算干戈止，神謀宇宙清。","兩堦文物盛，七德武功成。","校獵长楊苑，屯軍細柳營。","归来獻明主，歌舞溢春城。"]', '诗', 'shi', '', NULL, '皇帝感詞 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a64c6d0c-5b69-4a33-a9e2-bbb487aba962', '皇帝感詞 四', '皇帝感词 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["天樂下天中，雲輧儼在空。","鉛黃豔河漢，笑語合笙鏞。","已見長隨鳳，仍聞不避熊。","君王親試舞，閶闔靜無風。"]', '["天乐下天中，云輧儼在空。","鉛黄豔河漢，笑語合笙鏞。","已见长隨鳳，仍闻不避熊。","君王親試舞，閶闔静無风。"]', '诗', 'shi', '', NULL, '皇帝感詞 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e4b5280-a671-4c3b-9274-9fcf7672b98a', '天長久詞 一', '天长久词 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉砌紅花樹，香風不敢吹。","春光解天意，偏發殿南枝。"]', '["玉砌紅花樹，香风不敢吹。","春光解天意，偏發殿南枝。"]', '诗', 'shi', '', NULL, '天長久詞 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2603fcfa-7099-44ef-881b-c864e8ec60b5', '天長久詞 二', '天长久词 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["虹橋千步廊，半在水中央。","天子方清暑，宮娃起夜妝。"]', '["虹橋千步廊，半在水中央。","天子方清暑，宮娃起夜妝。"]', '诗', 'shi', '', NULL, '天長久詞 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f24c492-f3b5-4901-b453-def9efaf8a4c', '天長久詞 三', '天长久词 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["辭輦復當熊，傾心奉六宮。","君王若看貌，甘在衆妃中。"]', '["辞輦复當熊，傾心奉六宮。","君王若看貌，甘在衆妃中。"]', '诗', 'shi', '', NULL, '天長久詞 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ffd8211-af0c-4f02-a289-527e3bcbdb55', '天長久詞 四', '天长久词 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲日呈祥禮物殊，彤庭生獻五單于。","塞垣萬里無飛鳥，可是邊城用郅都。"]', '["云日呈祥禮物殊，彤庭生獻五單于。","塞垣万里無飞鸟，可是邊城用郅都。"]', '诗', 'shi', '', NULL, '天長久詞 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a46c844-7de3-401f-8809-f2cf8fcd9313', '天長久詞 五', '天长久词 五', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["臺殿雲深秋色微，君王初賜六宮衣。","樓船泛罷歸猶早，行遣才人鬬射飛。"]', '["台殿云深秋色微，君王初賜六宮衣。","楼船泛罷归猶早，行遣才人鬬射飞。"]', '诗', 'shi', '', NULL, '天長久詞 五 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce491725-b96b-46a7-b83c-463d2094ef3f', '和張僕射塞下曲 一', '和張僕射塞下曲 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鷲翎金僕姑，燕尾繡蝥弧。","獨立揚新令，千營共一呼。"]', '["鷲翎金僕姑，燕尾繡蝥弧。","独立揚新令，千營共一呼。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2e12c0-c1b8-4242-888c-9dba1a8f93ce', '和張僕射塞下曲 二', '和張僕射塞下曲 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["林暗草驚風，將軍夜引弓。","平明尋白羽，沒在石稜中。"]', '["林暗草驚风，將軍夜引弓。","平明尋白羽，沒在石稜中。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2a3000-9127-43fa-8618-89a1937322cb', '和張僕射塞下曲 三', '和張僕射塞下曲 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["月黑鴈飛高，單于夜遁逃。","欲將輕騎逐，大雪滿弓刀。"]', '["月黑鴈飞高，單于夜遁逃。","欲將轻騎逐，大雪满弓刀。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a4d3eae-fe01-46c7-a28b-8b518614a508', '和張僕射塞下曲 四', '和張僕射塞下曲 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["野幕敞瓊筵，羌戎賀勞旋。","醉和金甲舞，雷鼓動山川。"]', '["野幕敞瓊筵，羌戎賀勞旋。","醉和金甲舞，雷鼓动山川。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb62728-c9c8-473d-b1f7-0fafd4bb9772', '和張僕射塞下曲 五', '和張僕射塞下曲 五', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["調箭又呼鷹，俱聞出世能。","奔狐將迸雉，掃盡古丘陵。"]', '["調箭又呼鷹，俱闻出世能。","奔狐將迸雉，掃尽古丘陵。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 五 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e3ec52-8f20-404d-9e4a-6c4580075a7a', '和張僕射塞下曲 六', '和張僕射塞下曲 六', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["亭亭七葉貴，蕩蕩一隅清。","他日題麟閣，唯應獨不名。"]', '["亭亭七葉貴，蕩蕩一隅清。","他日題麟閣，唯應独不名。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 六 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4271d12f-c540-4b19-be04-f2d71fb82f40', '古豔詩 一', '古豔诗 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["殘妝色淺髻鬟開，笑映朱簾覰客來。","推醉誰知弄花鈿，潘郎不敢使人催。"]', '["殘妝色淺髻鬟开，笑映朱簾覰客来。","推醉誰知弄花鈿，潘郎不敢使人催。"]', '诗', 'shi', '', NULL, '古豔詩 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb7faec-a27f-49e5-bbed-967ea1c2bd96', '古豔詩 二', '古豔诗 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["自拈裙帶結同心，暖處偏知香氣深。","愛捉狂夫問閑事，不知歌舞用黃金。"]', '["自拈裙带結同心，暖处偏知香氣深。","愛捉狂夫问闲事，不知歌舞用黄金。"]', '诗', 'shi', '', NULL, '古豔詩 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e908c7aa-5607-4668-b79d-7ec2e1eb7cf9', '孤松吟詶渾贊善', '孤松吟詶渾贊善', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["深山荒松枝，雪壓半離披。","朱門青松樹，萬葉承清露。","露重色逾鮮，吟風似遠泉。","天寒香自發，日麗影常圓。","陰郊一夜雪，榆柳皆枯折。","迴首望君家，翠蓋滿瓊花。","捧君青松曲，自顧同衰木。","曲罷不相親，深山頭白人。"]', '["深山荒松枝，雪壓半離披。","朱门青松樹，万葉承清露。","露重色逾鲜，吟风似远泉。","天寒香自發，日丽影常圓。","陰郊一夜雪，榆柳皆枯折。","迴首望君家，翠蓋满瓊花。","捧君青松曲，自顧同衰木。","曲罷不相親，深山头白人。"]', '诗', 'shi', '', NULL, '孤松吟詶渾贊善 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7488a1f-8791-4a51-8205-264270e8afc4', '從軍行', '從軍行', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["二十在邊城，軍中得勇名。","卷旗收敗馬，占磧擁殘兵。","覆陣烏鳶起，燒山草木明。","塞閑思遠獵，師老厭分營。","雪嶺無人跡，冰河足鴈聲。","李陵甘此沒，惆悵漢公卿。"]', '["二十在邊城，軍中得勇名。","卷旗收敗马，占磧擁殘兵。","覆陣烏鳶起，燒山草木明。","塞闲思远獵，師老厭分營。","雪嶺無人跡，冰河足鴈声。","李陵甘此沒，惆悵漢公卿。"]', '诗', 'shi', '', NULL, '從軍行 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db9b77d3-ce1e-4143-8d08-d5c4e741988a', '和馬郎中畫鶴贊', '和马郎中畫鹤贊', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高高華亭，有鶴在屏。","削玉點漆，乘軒姓丁。","暮雲冥冥，雙垂雪翎。","晨光炯炯，一直朱頂。","含音儼容，絕粒遺影。","君以爲真，相期緱嶺。"]', '["高高华亭，有鹤在屏。","削玉点漆，乘軒姓丁。","暮云冥冥，雙垂雪翎。","晨光炯炯，一直朱頂。","含音儼容，絕粒遺影。","君以爲真，相期緱嶺。"]', '诗', 'shi', '', NULL, '和馬郎中畫鶴贊 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a6a4a34-3991-49ca-becb-b58ca5a1ec17', '送朝長史赴荆南舊幕', '送朝长史赴荆南旧幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["元瑜思舊幕，幾夜夢旌旃。","暑退蒹葭雨，秋生鼓角天。","月明三峽路，浪裏九江船。","囗囗囗囗囗，囗囗囗囗囗。"]', '["元瑜思旧幕，幾夜梦旌旃。","暑退蒹葭雨，秋生鼓角天。","月明三峽路，浪裏九江船。","囗囗囗囗囗，囗囗囗囗囗。"]', '诗', 'shi', '', NULL, '送朝長史赴荆南舊幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98faa139-30a5-497b-af90-9d87ff063d29', '送渭南崔少府歸徐郎中幕', '送渭南崔少府归徐郎中幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["葉下山邊路，行人見自悲。","夜寒逢雪處，日暖到村時。","語少心常苦，愁深醉自遲。","囗囗囗囗囗，羨有幕中期。"]', '["葉下山邊路，行人见自悲。","夜寒逢雪处，日暖到村时。","語少心常苦，愁深醉自遲。","囗囗囗囗囗，羨有幕中期。"]', '诗', 'shi', '', NULL, '送渭南崔少府歸徐郎中幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('514e7fd5-3b68-497c-a61e-4f1764d76286', '寄鄭七綱', '寄鄭七綱', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["小來落托復迍邅，一辱君知二十年。","舍去形骸容傲慢，引隨兄弟共團圓。","羈遊不定同雲聚，薄宦相縈若網牽。","他日吳公如記問，願將黃綬比青氈。"]', '["小来落托复迍邅，一辱君知二十年。","舍去形骸容傲慢，引隨兄弟共團圓。","羈游不定同云聚，薄宦相縈若網牽。","他日吳公如記问，願將黄綬比青氈。"]', '诗', 'shi', '', NULL, '寄鄭七綱 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8148f2cb-e975-4ab1-9757-569da2556693', '逢南中使因寄嶺外故人', '逢南中使因寄嶺外故人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["見說南來處，蒼梧接桂林。","過秋天更暖，邊海日長陰。","巴路緣雲出，蠻鄉入洞深。","信迴人自老，夢到月應沈。","碧水通春色，青山寄遠心。","炎方難久客，爲爾一沾襟。"]', '["见说南来处，蒼梧接桂林。","過秋天更暖，邊海日长陰。","巴路緣云出，蠻乡入洞深。","信迴人自老，梦到月應沈。","碧水通春色，青山寄远心。","炎方难久客，爲爾一沾襟。"]', '诗', 'shi', '', NULL, '逢南中使因寄嶺外故人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c117e63-4e0e-4a74-b897-56dbdb49d296', '代員將軍罷戰後歸舊里贈朔北故人', '代員將軍罷戰後归旧里贈朔北故人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["結髮事疆場，全生俱到鄉。","連雲防鐵嶺，同日破漁陽。","牧馬胡天晚，移軍磧路長。","枕戈眠古戍，吹角立繁霜。","歸老勳仍在，酬恩虜未亡。","獨行過邑里，多病對農桑。","雄劒依塵橐，陰符寄藥囊。","空餘麾下將，猶逐羽林郎。"]', '["結髮事疆場，全生俱到乡。","連云防鐵嶺，同日破漁陽。","牧马胡天晚，移軍磧路长。","枕戈眠古戍，吹角立繁霜。","归老勳仍在，酬恩虜未亡。","独行過邑里，多病对農桑。","雄劒依塵橐，陰符寄藥囊。","空餘麾下將，猶逐羽林郎。"]', '诗', 'shi', '', NULL, '代員將軍罷戰後歸舊里贈朔北故人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e1b5ac-d83c-483c-a5eb-5b33172fc16f', '江北憶崔汶', '江北憶崔汶', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["夜問江西客，還知在楚鄉。","全身出部伍，盡室逐漁商。","晴日遊瓜步，新年對漢陽。","月昏驚浪白，瘴起覺雲黃。","望嶺家何處，登山淚幾行。","閩中傳有雪，應且住南康。"]', '["夜问江西客，還知在楚乡。","全身出部伍，尽室逐漁商。","晴日游瓜步，新年对漢陽。","月昏驚浪白，瘴起覺云黄。","望嶺家何处，登山泪幾行。","閩中傳有雪，應且住南康。"]', '诗', 'shi', '', NULL, '江北憶崔汶 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db414e3-350f-44a1-9898-10a15365b4ec', '早春歸盩厔舊居却寄耿拾遺湋李校書端', '早春归盩厔旧居却寄耿拾遺湋李校书端', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["野日初晴麥壠分，竹園相接鹿成羣。","幾家廢井生青草，一樹繁花傍古墳。","引水忽驚冰滿澗，向田空見石和雲。","可憐荒歲青山下，惟有松枝好寄君。"]', '["野日初晴麦壠分，竹园相接鹿成羣。","幾家廢井生青草，一樹繁花傍古墳。","引水忽驚冰满澗，向田空见石和云。","可怜荒歲青山下，惟有松枝好寄君。"]', '诗', 'shi', '', NULL, '早春歸盩厔舊居却寄耿拾遺湋李校書端 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d5a4c2-3ee0-4e9a-bd93-e60c3124915b', '春日山中憶崔峒吉中孚', '春日山中憶崔峒吉中孚', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["延步愛清晨，空山日照春。","蜜房那有主，石室自無鄰。","泉急魚依藻，花繁鳥近人。","誰言失徒侶，唯與老相親。"]', '["延步愛清晨，空山日照春。","蜜房那有主，石室自無鄰。","泉急鱼依藻，花繁鸟近人。","誰言失徒侶，唯與老相親。"]', '诗', 'shi', '', NULL, '春日山中憶崔峒吉中孚 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59aa6d87-8666-4bf0-bb92-e3e3e8d811f4', '客舍喜崔補闕司空拾遺訪宿', '客舍喜崔補闕司空拾遺訪宿', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["步月訪諸鄰，蓬居宿近臣。","烏裘先醉客，清鏡早朝人。","壞壁煙垂網，香街火照塵。","悲榮俱是分，吾亦樂吾貧。"]', '["步月訪諸鄰，蓬居宿近臣。","烏裘先醉客，清镜早朝人。","壞壁煙垂網，香街火照塵。","悲榮俱是分，吾亦乐吾貧。"]', '诗', 'shi', '', NULL, '客舍喜崔補闕司空拾遺訪宿 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('816a135b-333b-4c37-a2b7-96f5e40e34c9', '苦雨聞包諫議欲見訪戲贈', '苦雨闻包諫議欲见訪戲贈', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["草氣廚煙咽不開，繞牀連壁盡生苔。","常時多病因多雨，那敢煩君車馬來。"]', '["草氣廚煙咽不开，繞牀連壁尽生苔。","常时多病因多雨，那敢煩君车马来。"]', '诗', 'shi', '', NULL, '苦雨聞包諫議欲見訪戲贈 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b5f760-c5a9-4cf9-a751-00bf3b79857e', '客舍苦雨即事寄錢起郎士元二員外', '客舍苦雨即事寄錢起郎士元二員外', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["積雨暮淒淒，羈人狀鳥棲。","響空宮樹接，覆水野雲低。","穴蟻多隨草，巢蜂半墜泥。","遶池牆蘚合，擁溜瓦松齊。","舊圃平如海，新溝曲似溪。","壞闌留衆蝶，欹棟止羣雞。","莠盛終無實，槎枯返有荑。","綠萍藏廢井，黃葉隱危堤。","閭里歡將絕，朝昏望亦迷。","不知霄漢侶，何路可相攜。"]', '["積雨暮淒淒，羈人狀鸟棲。","响空宮樹接，覆水野云低。","穴蟻多隨草，巢蜂半墜泥。","遶池牆蘚合，擁溜瓦松齊。","旧圃平如海，新溝曲似溪。","壞闌留衆蝶，欹棟止羣雞。","莠盛終無實，槎枯返有荑。","綠萍藏廢井，黄葉隐危堤。","閭里歡將絕，朝昏望亦迷。","不知霄漢侶，何路可相携。"]', '诗', 'shi', '', NULL, '客舍苦雨即事寄錢起郎士元二員外 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d4c69a-9803-4863-bb93-8b0be8420bbd', '郊居對雨寄趙涓給事包佶郎中', '郊居对雨寄趙涓給事包佶郎中', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["暑雨青山裏，隨風到野居。","亂漚浮曲砌，懸溜響前除。","塵鏡愁多掩，蓬頭嬾更梳。","夜窗淒枕席，陰壁潤圖書。","蕭颯宜新竹，龍鐘拾野蔬。","石泉空自咽，藥圃不堪鋤。","濁水淙深轍，荒蘭擁敗渠。","繁枝留宿鳥，碎浪出寒魚。","桑屐時登望，荷衣自卷舒。","應憐在泥滓，無路託高車。"]', '["暑雨青山裏，隨风到野居。","亂漚浮曲砌，懸溜响前除。","塵镜愁多掩，蓬头嬾更梳。","夜窗淒枕席，陰壁潤圖书。","蕭颯宜新竹，龙鐘拾野蔬。","石泉空自咽，藥圃不堪鋤。","濁水淙深轍，荒蘭擁敗渠。","繁枝留宿鸟，碎浪出寒鱼。","桑屐时登望，荷衣自卷舒。","應怜在泥滓，無路託高车。"]', '诗', 'shi', '', NULL, '郊居對雨寄趙涓給事包佶郎中 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a9162d7-ab6c-4cd2-9f64-b2883eef14c1', '藍溪期蕭道士採藥不至', '藍溪期蕭道士採藥不至', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["春風生百藥，幾處术苗香。","人遠花空落，溪深日復長。","病多知藥性，老近憶仙方。","清節何由見，三山桂自芳。"]', '["春风生百藥，幾处术苗香。","人远花空落，溪深日复长。","病多知藥性，老近憶仙方。","清節何由见，三山桂自芳。"]', '诗', 'shi', '', NULL, '藍溪期蕭道士採藥不至 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b30b4f-a9d1-4c84-8cd9-fdf6a29b7e86', '雪謗後書事上皇甫大夫', '雪謗後书事上皇甫大夫', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["盛德總羣英，高標仰國楨。","獨安巡狩日，曾掩趙張名。","業就難辭寵，朝回更授兵。","曉川分牧馬，夜雪覆連營。","長策威殊俗，嘉謀翊聖明。","畫圖規陣勢，夢筆紀山行。","綬拂池中影，珂搖竹外聲。","賜歡徵妓樂，陪醉問公卿。","却憶經前事，翻疑得此生。","分深存沒感，恩在子孫榮。","覽鏡愁將老，捫心喜復驚。","豈言沈族重，但覺殺身輕。","有淚沾墳典，無家集弟兄。","東西遭世難，流浪識交情。","閱古宗文舉，推才慕正平。","應憐守貧賤，又欲事躬耕。"]', '["盛德總羣英，高標仰国楨。","独安巡狩日，曾掩趙張名。","業就难辞寵，朝回更授兵。","晓川分牧马，夜雪覆連營。","长策威殊俗，嘉謀翊聖明。","畫圖規陣勢，梦笔紀山行。","綬拂池中影，珂搖竹外声。","賜歡徵妓乐，陪醉问公卿。","却憶經前事，翻疑得此生。","分深存沒感，恩在子孫榮。","覽镜愁將老，捫心喜复驚。","豈言沈族重，但覺殺身轻。","有泪沾墳典，無家集弟兄。","东西遭世难，流浪識交情。","閱古宗文舉，推才慕正平。","應怜守貧賤，又欲事躬耕。"]', '诗', 'shi', '', NULL, '雪謗後書事上皇甫大夫 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e78cd3-673f-4831-8941-a3a83d59514b', '春日憶司空文明', '春日憶司空文明', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["桃李風多日欲陰，百勞飛處落花深。","貧居靜久難逢信，知隔春山不可尋。"]', '["桃李风多日欲陰，百勞飞处落花深。","貧居静久难逢信，知隔春山不可尋。"]', '诗', 'shi', '', NULL, '春日憶司空文明 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b80351f-2530-4619-a607-1bb4968bbf41', '臥病寓居龍興觀枉馮十七著作書知罷攝洛陽赴緱氏因題十四韻寄馮生幷贈喬尊師', '臥病寓居龙兴观枉馮十七著作书知罷攝洛陽赴緱氏因題十四韻寄馮生幷贈喬尊師', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["乞假依山宅，蹉跎屬歲周。","弱荑輕採拾，鈍質稱歸休。","潘岳衰將至，劉楨病未瘳。","步遲乘羽客，起晏滯書郵。","幸以編方驗，終貽骨肉憂。","灼龜爐氣冷，曝藥樹陰稠。","語命心堪醉，傷離夢亦愁。","葷羶居已絕，鸞鶴見無由。","世累如塵積，年光劇水流。","躡雲知有路，濟海豈無舟。","倚玉翻成難，投磚敢望詶。","卑棲君就祿，羸憊我逢秋。","腐葉填荒轍，陰螢出古溝。","依然在遐想，願子勵風猷。"]', '["乞假依山宅，蹉跎屬歲周。","弱荑轻採拾，鈍質稱归休。","潘岳衰將至，劉楨病未瘳。","步遲乘羽客，起晏滯书郵。","幸以編方驗，終貽骨肉憂。","灼龟爐氣冷，曝藥樹陰稠。","語命心堪醉，傷離梦亦愁。","葷羶居已絕，鸾鹤见無由。","世累如塵積，年光劇水流。","躡云知有路，濟海豈無舟。","倚玉翻成难，投磚敢望詶。","卑棲君就祿，羸憊我逢秋。","腐葉填荒轍，陰螢出古溝。","依然在遐想，願子勵风猷。"]', '诗', 'shi', '', NULL, '臥病寓居龍興觀枉馮十七著作書知罷攝洛陽赴緱氏因題十四韻寄馮生幷贈喬尊師 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1fc49eb-32c7-4240-85bf-8a8d80e95d87', '秋夜寄馮著作', '秋夜寄馮著作', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["河漢淨無雲，鴻聲此夜聞。","素心難比石，蒼鬢欲如君。","露槿月中落，風螢池上分。","何言千載友，同迹不同羣。"]', '["河漢淨無云，鴻声此夜闻。","素心难比石，蒼鬢欲如君。","露槿月中落，风螢池上分。","何言千載友，同迹不同羣。"]', '诗', 'shi', '', NULL, '秋夜寄馮著作 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a1fb5f-9390-4ccb-b4e2-9bde13822508', '洛陽早春憶吉中孚校書司空曙主簿因寄清江上人', '洛陽早春憶吉中孚校书司空曙主簿因寄清江上人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["值迥逢高駐馬頻，雪晴閑看洛陽春。","鶯聲報遠同芳信，柳色邀歡似故人。","酒貌昔將花共豔，鬢毛今與草爭新。","年來百事皆無緒，唯與湯師結淨因。"]', '["值迥逢高駐马頻，雪晴闲看洛陽春。","鶯声報远同芳信，柳色邀歡似故人。","酒貌昔將花共豔，鬢毛今與草爭新。","年来百事皆無緒，唯與湯師結淨因。"]', '诗', 'shi', '', NULL, '洛陽早春憶吉中孚校書司空曙主簿因寄清江上人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be8852b-d630-40f1-9584-590cb6839e9c', '偶逢姚校書憑附書達河南郄推官因以戲贈', '偶逢姚校书憑附书達河南郄推官因以戲贈', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["寄書常切到常遲，今日憑君君莫辭。","若問玉人殊易識，蓮花府裏最清羸。"]', '["寄书常切到常遲，今日憑君君莫辞。","若问玉人殊易識，蓮花府裏最清羸。"]', '诗', 'shi', '', NULL, '偶逢姚校書憑附書達河南郄推官因以戲贈 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144549cb-a706-4f83-b11f-b49271de13be', '夜中得循州趙司馬侍郎書因寄回使', '夜中得循州趙司马侍郎书因寄回使', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["瘴海寄雙魚，中宵達我居。","兩行燈下淚，一紙嶺南書。","地說炎蒸極，人稱老病餘。","殷勤報賈傅，莫共酒杯疎。"]', '["瘴海寄雙鱼，中宵達我居。","兩行灯下泪，一紙嶺南书。","地说炎蒸極，人稱老病餘。","殷勤報賈傅，莫共酒杯疎。"]', '诗', 'shi', '', NULL, '夜中得循州趙司馬侍郎書因寄回使 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18734c96-6ba5-4e4d-9150-fa5d31b646d9', '晚次新豐北野老家書事呈贈韓質明府', '晚次新豐北野老家书事呈贈韓質明府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["機鳴舂響日暾暾，雞犬相和漢古村。","數派清泉黃菊盛，一林寒露紫棃繁。","衰翁正席矜新社，稚子齊襟讀古論。","共說年來但無事，不知何者是君恩。"]', '["機鳴舂响日暾暾，雞犬相和漢古村。","數派清泉黄菊盛，一林寒露紫棃繁。","衰翁正席矜新社，稚子齊襟读古論。","共说年来但無事，不知何者是君恩。"]', '诗', 'shi', '', NULL, '晚次新豐北野老家書事呈贈韓質明府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d1c18b-c3b4-406e-affa-137bbd0fb0f8', '書情上大尹十兄', '书情上大尹十兄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["紫陌絕纖埃，油幢千騎來。","剖辭紛若雨，犇吏殷成雷。","聖澤初憂壅，羣心本在台。","海鱗方潑刺，雲翼暫徘徊。","芳室芝蘭茂，春蹊桃李開。","江湖餘派少，鴻鴈遠聲哀。","命厭蓍龜誘，年驚弟姪催。","磨鉛慙砥礪，揮策愧駑駘。","玉管能喧谷，金爐可變灰。","應憐費思者，銜淚亦銜枚。"]', '["紫陌絕纖埃，油幢千騎来。","剖辞紛若雨，犇吏殷成雷。","聖澤初憂壅，羣心本在台。","海鱗方潑刺，云翼暫徘徊。","芳室芝蘭茂，春蹊桃李开。","江湖餘派少，鴻鴈远声哀。","命厭蓍龟誘，年驚弟姪催。","磨鉛慙砥礪，揮策愧駑駘。","玉管能喧谷，金爐可变灰。","應怜費思者，銜泪亦銜枚。"]', '诗', 'shi', '', NULL, '書情上大尹十兄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc9bd94a-0f69-47d0-a149-3b2e50cf6b65', '春思貽李方陵', '春思貽李方陵', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["長安三月春，難別復難親。","不識冶遊伴，多逢憔悴人。","漸知歡澹薄，轉覺老殷勤。","去矣盡如此，此辭悲未陳。"]', '["长安三月春，难別复难親。","不識冶游伴，多逢憔悴人。","漸知歡澹薄，轉覺老殷勤。","去矣尽如此，此辞悲未陳。"]', '诗', 'shi', '', NULL, '春思貽李方陵 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b58530-a019-48b3-b7a8-02193f503ea8', '驛中望山戲贈渭南陸贄主簿', '驛中望山戲贈渭南陸贄主簿', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["官微多懼事多同，拙性偏無主驛功。","山在門前登不得，鬢毛衰盡路塵中。"]', '["官微多懼事多同，拙性偏無主驛功。","山在门前登不得，鬢毛衰尽路塵中。"]', '诗', 'shi', '', NULL, '驛中望山戲贈渭南陸贄主簿 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b36cb0-42da-4635-a1f9-3d2b48c3abae', '太白西峯偶宿車祝二尊師石室晨登前巘憑眺書懷即事寄呈鳳翔齊員外張侍御', '太白西峯偶宿车祝二尊師石室晨登前巘憑眺书懷即事寄呈鳳翔齊員外張侍御', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["弱齡誠昧鄙，遇勝惟求止。","如何羈滯中，得步青冥裏。","青冥有桂藂，冰雪兩仙翁。","毛節未歸海，丹梯閑倚空。","逍遙擬上清，洞府不知名。","醮罷雨雷至，客辭山忽明。","山明鳥聲樂，日氣生嵓壑。","嵓壑樹脩脩，白雲如水流。","白雲消散盡，隴塞儼然秋。","積阻關河固，綿聯烽戍稠。","五營承廟略，四野失邊愁。","吁嗟繫塵役，又負靈仙迹。","芝朮自芳香，泥沙幾沈溺。","書此欲沾衣，平生事每違。","煙霄不可仰，鸞鶴自追隨。"]', '["弱齡誠昧鄙，遇勝惟求止。","如何羈滯中，得步青冥裏。","青冥有桂藂，冰雪兩仙翁。","毛節未归海，丹梯闲倚空。","逍遙擬上清，洞府不知名。","醮罷雨雷至，客辞山忽明。","山明鸟声乐，日氣生嵓壑。","嵓壑樹脩脩，白云如水流。","白云消散尽，隴塞儼然秋。","積阻关河固，綿聯烽戍稠。","五營承廟略，四野失邊愁。","吁嗟繫塵役，又負靈仙迹。","芝朮自芳香，泥沙幾沈溺。","书此欲沾衣，平生事每違。","煙霄不可仰，鸾鹤自追隨。"]', '诗', 'shi', '', NULL, '太白西峯偶宿車祝二尊師石室晨登前巘憑眺書懷即事寄呈鳳翔齊員外張侍御 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fa4a1c0-0475-4a90-9027-3432d0f578b1', '贈韓山人', '贈韓山人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["見君何事不慙顏，白髮生來未到山。","更嘆無家又無藥，往來唯在酒徒間。"]', '["见君何事不慙顏，白髮生来未到山。","更嘆無家又無藥，往来唯在酒徒间。"]', '诗', 'shi', '', NULL, '贈韓山人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3f9214-bf48-47ef-b538-8056b8eefe55', '贈李果毅', '贈李果毅', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["向日磨金鏃，當風著錦衣。","上城邀賊語，走馬截鵰飛。"]', '["向日磨金鏃，當风著錦衣。","上城邀賊語，走马截鵰飞。"]', '诗', 'shi', '', NULL, '贈李果毅 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7242db95-41ec-4932-af0b-3d5d9b362775', '春日書情贈別司空曙', '春日书情贈別司空曙', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["壯志隨年盡，謀身意未安。","風塵交契闊，老大別離難。","臘近晴多暖，春遲夜却寒。","誰堪少兄弟，三十又無官。"]', '["壯志隨年尽，謀身意未安。","风塵交契闊，老大別離难。","臘近晴多暖，春遲夜却寒。","誰堪少兄弟，三十又無官。"]', '诗', 'shi', '', NULL, '春日書情贈別司空曙 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('312f2a22-db98-4759-9025-9ef361ae82b7', '冬曉呈鄰里', '冬晓呈鄰里', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["終夜寢衣冷，開門思曙光。","空堦一藂葉，華室四鄰霜。","望闕覺天迥，憶山愁路荒。","途中一留滯，雙鬢颯然蒼。"]', '["終夜寢衣冷，开门思曙光。","空堦一藂葉，华室四鄰霜。","望闕覺天迥，憶山愁路荒。","途中一留滯，雙鬢颯然蒼。"]', '诗', 'shi', '', NULL, '冬曉呈鄰里 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04fda886-d1fd-4fc8-828d-86e1a0e1fe94', '首冬寄河東昭德里書事貽鄭損倉曹', '首冬寄河东昭德里书事貽鄭損倉曹', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["清冬和暖天，老鈍晝多眠。","日愛閭巷靜，每聞官吏賢。","寒葅供家食，腐葉宿廚煙。","且復執杯酒，無煩輕議邊。"]', '["清冬和暖天，老鈍晝多眠。","日愛閭巷静，每闻官吏賢。","寒葅供家食，腐葉宿廚煙。","且复執杯酒，無煩轻議邊。"]', '诗', 'shi', '', NULL, '首冬寄河東昭德里書事貽鄭損倉曹 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2605b02f-f4c1-40c3-b7ae-aba62fbd5605', '渾贊善東齋戲贈陳歸', '渾贊善东斋戲贈陳归', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["長裾珠履颯輕塵，閒以琴書列上賓。","公子無讐可邀請，侯嬴此坐是何人。"]', '["长裾珠履颯轻塵，閒以琴书列上賓。","公子無讐可邀請，侯嬴此坐是何人。"]', '诗', 'shi', '', NULL, '渾贊善東齋戲贈陳歸 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d11f731-4427-4c00-b5d4-57ae9a74d472', '春日臥病示趙季黃', '春日臥病示趙季黄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["病中饒淚眼常昏，聞說花開亦閉門。","語少漸知琴思苦，臥多唯覺鳥聲喧。","黃埃滿市圖書賤，黑霧連山虎豹尊。","今日支離顧形影，向君凡在幾重恩。"]', '["病中饒泪眼常昏，闻说花开亦閉门。","語少漸知琴思苦，臥多唯覺鸟声喧。","黄埃满市圖书賤，黑霧連山虎豹尊。","今日支離顧形影，向君凡在幾重恩。"]', '诗', 'shi', '', NULL, '春日臥病示趙季黃 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02c0f61-8c1a-42b9-9a22-2e361bf9add4', '秋幕中夜獨坐遲明因陪陳翃郎中晨謁上公因書即事兼呈同院諸公', '秋幕中夜独坐遲明因陪陳翃郎中晨謁上公因书即事兼呈同院諸公', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["風淒露泫然，明月在山巔。","獨倚古庭樹，仰看深夜天。","葉翻螢不定，蟲思草無邊。","南舍機杼發，東方雲景鮮。","簪裘肅已整，車騎儼將前。","百雉拱雙戟，萬夫尊一賢。","琳瑯多謀蘊，律呂更相宣。","曉桂香浥露，新鴻晴滿川。","熙熙造化功，穆穆唐堯年。","顧己草同賤，誓心金匪堅。","蹇辭慙自寡，渴病老難痊。","書此更何問，邊韶唯晝眠。"]', '["风淒露泫然，明月在山巔。","独倚古庭樹，仰看深夜天。","葉翻螢不定，蟲思草無邊。","南舍機杼發，东方云景鲜。","簪裘肅已整，车騎儼將前。","百雉拱雙戟，万夫尊一賢。","琳瑯多謀蘊，律呂更相宣。","晓桂香浥露，新鴻晴满川。","熙熙造化功，穆穆唐堯年。","顧己草同賤，誓心金匪堅。","蹇辞慙自寡，渴病老难痊。","书此更何问，邊韶唯晝眠。"]', '诗', 'shi', '', NULL, '秋幕中夜獨坐遲明因陪陳翃郎中晨謁上公因書即事兼呈同院諸公 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8efaf10-41da-4520-91e5-5835a4b4275a', '寄贈庫部王郎中', '寄贈庫部王郎中', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["諤諤漢名臣，從天令若春。","敘辭皆詔旨，稱宦即星辰。","草木承風偃，雲雷施澤均。","威懲治粟尉，恩洽讓田人。","泉貨方將散，京坻自此陳。","五營俱益竈，千里不停輪。","未遠金門籍，旋清玉塞塵。","碩儒推慶重，良友頌公頻。","鶴髮逢新鏡，龍門躍舊鱗。","荷君偏有問，深感浩難申。"]', '["諤諤漢名臣，從天令若春。","敘辞皆詔旨，稱宦即星辰。","草木承风偃，云雷施澤均。","威懲治粟尉，恩洽讓田人。","泉貨方將散，京坻自此陳。","五營俱益竈，千里不停輪。","未远金门籍，旋清玉塞塵。","碩儒推慶重，良友頌公頻。","鹤髮逢新镜，龙门躍旧鱗。","荷君偏有问，深感浩难申。"]', '诗', 'shi', '', NULL, '寄贈庫部王郎中 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24d615c-41c3-459a-9a8c-cfa6e31c1843', '寄贈暢當山居', '寄贈暢當山居', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["古村荒石路，歲晏獨言歸。","山雪厚三尺，社楡麄十圍。","虯龍寧守蟄，鸞鶴豈矜飛。","君子固安分，毋聽勞者譏。"]', '["古村荒石路，歲晏独言归。","山雪厚三尺，社楡麄十圍。","虯龙寧守蟄，鸾鹤豈矜飞。","君子固安分，毋听勞者譏。"]', '诗', 'shi', '', NULL, '寄贈暢當山居 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67bc6252-c7b9-4c64-a664-c6ae86126ca7', '偶宿山中憶暢當', '偶宿山中憶暢當', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["深山夜雪晴，坐憶曉山明。","讀易罷三卷，彈琴當五更。","薜蘿枯有影，嵓壑凍無聲。","此夕一相望，君應知我誠。"]', '["深山夜雪晴，坐憶晓山明。","读易罷三卷，彈琴當五更。","薜蘿枯有影，嵓壑凍無声。","此夕一相望，君應知我誠。"]', '诗', 'shi', '', NULL, '偶宿山中憶暢當 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a012a1-ef54-45a4-91f1-c144d22f0d43', '秋中野望寄舍弟綬兼令呈上西川尚書舅', '秋中野望寄舍弟綬兼令呈上西川尚书舅', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["憂來思遠望，高處殊非愜。","夜露濕蒼山，秋陂滿黃葉。","人隨鴈迢遰，棧與雲重疊。","骨肉暫分離，形神遂疲薾。","紅旌渭陽騎，幾日勞登涉。","蜀道藹松筠，巴江盛舟檝。","小生即何限，簡誨偏盈篋。","舊恨尚填膺，新悲復縈睫。","因求種瓜利，自喜歸耕捷。","井臼賴依鄰，兒童亦勝汲。","塵容不在照，雪鬢那堪鑷。","唯有飡霞心，知夫與天接。"]', '["憂来思远望，高处殊非愜。","夜露濕蒼山，秋陂满黄葉。","人隨鴈迢遰，棧與云重叠。","骨肉暫分離，形神遂疲薾。","紅旌渭陽騎，幾日勞登涉。","蜀道藹松筠，巴江盛舟檝。","小生即何限，簡誨偏盈篋。","旧恨尚填膺，新悲复縈睫。","因求種瓜利，自喜归耕捷。","井臼賴依鄰，兒童亦勝汲。","塵容不在照，雪鬢那堪鑷。","唯有飡霞心，知夫與天接。"]', '诗', 'shi', '', NULL, '秋中野望寄舍弟綬兼令呈上西川尚書舅 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a6e3ba4-efc2-445e-93c9-e317ea169438', '行藥前軒呈董山人', '行藥前軒呈董山人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["不覺老將至，瘦來方自驚。","朝昏多病色，起坐有勞聲。","腠暖苦肌痒，藏虛唯耳鳴。","桑公富靈術，一爲保餘生。"]', '["不覺老將至，瘦来方自驚。","朝昏多病色，起坐有勞声。","腠暖苦肌痒，藏虛唯耳鳴。","桑公富靈術，一爲保餘生。"]', '诗', 'shi', '', NULL, '行藥前軒呈董山人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c976833f-2332-4e4d-9c60-77d9f498cded', '翫春因寄馮衞二補闕戲呈李益', '翫春因寄馮衞二補闕戲呈李益', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["掖垣春色自天來，紅藥當堦次第開。","萱草藂藂爾何物，等閑穿破綠莓苔。"]', '["掖垣春色自天来，紅藥當堦次第开。","萱草藂藂爾何物，等闲穿破綠莓苔。"]', '诗', 'shi', '', NULL, '翫春因寄馮衞二補闕戲呈李益 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b58e563-cbb2-432f-a622-8585c5fdd32b', '新移北廳因貽同院諸公兼呈暢博士', '新移北廳因貽同院諸公兼呈暢博士', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["華軒邇台座，顧影忝時倫。","弱質偃彌曠，清風來亦頻。","恩輝坐凌邁，景物恣芳新。","終乃愧吾友，無容私此身。"]', '["华軒邇台座，顧影忝时倫。","弱質偃彌曠，清风来亦頻。","恩輝坐凌邁，景物恣芳新。","終乃愧吾友，無容私此身。"]', '诗', 'shi', '', NULL, '新移北廳因貽同院諸公兼呈暢博士 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46366210-a3b7-4846-84b4-4883a5abbabb', '與張擢對酌', '與張擢对酌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["張翁對盧叟，一榼山村酒。","傾酒請予歌，忽蒙張翁呵。","呵予官非屈，曲有怨詞多。","歌罷謝張翁，所思殊不同。","予悲方爲老，君責一何空。","曾看樂官錄，向是悲翁曲。","張老聞此詞，汪汪泪盈目。","盧叟醉言麄，一杯凡數呼。","迴頭顧張老，敢欲戲爲儒。"]', '["張翁对盧叟，一榼山村酒。","傾酒請予歌，忽蒙張翁呵。","呵予官非屈，曲有怨词多。","歌罷謝張翁，所思殊不同。","予悲方爲老，君責一何空。","曾看乐官錄，向是悲翁曲。","張老闻此词，汪汪泪盈目。","盧叟醉言麄，一杯凡數呼。","迴头顧張老，敢欲戲爲儒。"]', '诗', 'shi', '', NULL, '與張擢對酌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db767b4-e9a3-4828-ad37-1ae91a54e510', '喜從弟激初至', '喜從弟激初至', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["儒服策羸車，惠然過我廬。","敘年慙已長，稱從意何疎。","作吏清無比，爲文麗有餘。","應嗤受恩者，頭白讀兵書。"]', '["儒服策羸车，惠然過我廬。","敘年慙已长，稱從意何疎。","作吏清無比，爲文丽有餘。","應嗤受恩者，头白读兵书。"]', '诗', 'shi', '', NULL, '喜從弟激初至 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf4a9ee-ba26-46f5-89b3-320d9435bcb0', '尋賈尊師', '尋賈尊師', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉洞秦時客，焚香映綠蘿。","新傳左慈訣，曾與右軍鵝。","井臼陰苔遍，方書古字多。","成都今日雨，應與酒相和。"]', '["玉洞秦时客，焚香映綠蘿。","新傳左慈訣，曾與右軍鵝。","井臼陰苔遍，方书古字多。","成都今日雨，應與酒相和。"]', '诗', 'shi', '', NULL, '尋賈尊師 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1ed996-f5c2-4358-8bcf-4a2d8ad4ef32', '秋中過獨孤郊居', '秋中過独孤郊居', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["開園過水到郊居，共引家童拾野蔬。","高樹夕陽連古巷，菊花棃葉滿荒渠。","秋山近處行過寺，夜雨寒時起讀書。","帝里諸親別來久，豈知王粲愛樵漁。"]', '["开园過水到郊居，共引家童拾野蔬。","高樹夕陽連古巷，菊花棃葉满荒渠。","秋山近处行過寺，夜雨寒时起读书。","帝里諸親別来久，豈知王粲愛樵漁。"]', '诗', 'shi', '', NULL, '秋中過獨孤郊居 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46784cdb-ab3d-4172-ab28-7c8bfb346b81', '同耿拾遺春中題第四郎新修書院', '同耿拾遺春中題第四郎新修书院', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["得接西園會，多因野性同。","引藤連樹影，移石間花叢。","學就晨昏外，歡生禮樂中。","春遊隨墨客，夜宿伴潛公。","散帙燈驚燕，開簾月帶風。","朝朝在門下，自與五侯通。"]', '["得接西园會，多因野性同。","引藤連樹影，移石间花叢。","学就晨昏外，歡生禮乐中。","春游隨墨客，夜宿伴潛公。","散帙灯驚燕，开簾月带风。","朝朝在门下，自與五侯通。"]', '诗', 'shi', '', NULL, '同耿拾遺春中題第四郎新修書院 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1155dc-ba1e-4236-9fc5-af57baed0d94', '春日題杜叟山下別業', '春日題杜叟山下別業', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["白鳥羣飛山半晴，渚田相接有泉聲。","園中曉露青叢合，橋上春風綠野明。","雲影斷來峯影出，林花落盡草花生。","今朝醉舞同君樂，始信幽人不愛榮。"]', '["白鸟羣飞山半晴，渚田相接有泉声。","园中晓露青叢合，橋上春风綠野明。","云影斷来峯影出，林花落尽草花生。","今朝醉舞同君乐，始信幽人不愛榮。"]', '诗', 'shi', '', NULL, '春日題杜叟山下別業 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c438e3-3f13-4895-9f90-c59ce043671d', '過終南柳處士', '過終南柳处士', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["五老正相尋，圍棋到煮金。","石摧丹井閉，月過洞門深。","猨鳥三時下，藤蘿十里陰。","綠泉多草氣，青壁少花林。","自愧非仙侶，何言見道心。","悠哉宿山口，雷雨夜沈沈。"]', '["五老正相尋，圍棋到煮金。","石摧丹井閉，月過洞门深。","猨鸟三时下，藤蘿十里陰。","綠泉多草氣，青壁少花林。","自愧非仙侶，何言见道心。","悠哉宿山口，雷雨夜沈沈。"]', '诗', 'shi', '', NULL, '過終南柳處士 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b0f871-802e-4fe6-bfac-0b56699e8e5c', '宿澄上人院', '宿澄上人院', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["竹窗聞遠水，月出似溪中。","香覆經年火，幡飄後夜風。","性昏知道晚，學淺喜言同。","一悟歸身處，何山路不通。"]', '["竹窗闻远水，月出似溪中。","香覆經年火，幡飄後夜风。","性昏知道晚，学淺喜言同。","一悟归身处，何山路不通。"]', '诗', 'shi', '', NULL, '宿澄上人院 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab3a8e1-1960-4bb1-baf7-44b161d9c7fe', '題李沆林園', '題李沆林园', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["古巷牛羊出，重門接柳陰。","閑看入竹路，自有向山心。","種藥齊幽石，耕田到遠林。","願同詞賦客，得興謝家深。"]', '["古巷牛羊出，重门接柳陰。","闲看入竹路，自有向山心。","種藥齊幽石，耕田到远林。","願同词賦客，得兴謝家深。"]', '诗', 'shi', '', NULL, '題李沆林園 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('424be0b8-1f41-4659-9e87-3e9bcbb7cab9', '過司空曙村居', '過司空曙村居', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["南北與山鄰，蓬菴庇一身。","繁霜疑有雪，枯草似無人。","遂性在耕稼，所交唯賤貧。","何言張掾傲，每重德璋親。"]', '["南北與山鄰，蓬菴庇一身。","繁霜疑有雪，枯草似無人。","遂性在耕稼，所交唯賤貧。","何言張掾傲，每重德璋親。"]', '诗', 'shi', '', NULL, '過司空曙村居 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19030dce-1827-4555-8798-1204b4e5f797', '題念濟寺暈上人院', '題念濟寺暈上人院', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["泉響竹瀟瀟，潛公居處遙。","虛空聞偈夜，清淨雨花朝。","放鶴臨山閣，降龍步石橋。","世塵徒委積，劫火定焚燒。","苔壁雲難聚，風篁露易搖。","浮生亦無著，況乃是芭蕉。"]', '["泉响竹瀟瀟，潛公居处遙。","虛空闻偈夜，清淨雨花朝。","放鹤臨山閣，降龙步石橋。","世塵徒委積，劫火定焚燒。","苔壁云难聚，风篁露易搖。","浮生亦無著，況乃是芭蕉。"]', '诗', 'shi', '', NULL, '題念濟寺暈上人院 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3764f95f-0f5c-4dcd-96f9-2fab476f9018', '題楊虢縣竹亭', '題楊虢縣竹亭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["夜宿密公室，話馀將晝興。","遶堦三逕雪，當戶一池冰。","家訓資風化，心源隱政能。","明朝復何見，萊草古溝堘。"]', '["夜宿密公室，話馀將晝兴。","遶堦三逕雪，當戶一池冰。","家訓資风化，心源隐政能。","明朝复何见，萊草古溝堘。"]', '诗', 'shi', '', NULL, '題楊虢縣竹亭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4515056-4457-4190-88e6-403c600a3cb4', '過樓觀李尊師', '過楼观李尊師', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["城闕望煙霞，常悲仙路賒。","寧知樵子徑，得到葛洪家。","犬吠松間月，人行洞裏花。","留詩千歲鶴，送客五雲車。","訪世山空在，觀棋日未斜。","不知塵俗士，誰解種胡麻。"]', '["城闕望煙霞，常悲仙路賒。","寧知樵子徑，得到葛洪家。","犬吠松间月，人行洞裏花。","留诗千歲鹤，送客五云车。","訪世山空在，观棋日未斜。","不知塵俗士，誰解種胡麻。"]', '诗', 'shi', '', NULL, '過樓觀李尊師 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d4774b-0b97-4392-8dbb-7449b91a4f61', '雪謗後逢李叔度', '雪謗後逢李叔度', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["相逢空握手，往事不堪思。","見少情難盡，愁深語自遲。","草生分路處，雨散出山時。","強得寬離恨，唯當說後期。"]', '["相逢空握手，往事不堪思。","见少情难尽，愁深語自遲。","草生分路处，雨散出山时。","強得寬離恨，唯當说後期。"]', '诗', 'shi', '', NULL, '雪謗後逢李叔度 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960d0408-85e2-4cda-a276-cf679352a25d', '春日過李侍御', '春日過李侍御', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高柳滿春城，東園有鳥聲。","折花朝露滴，漱石野泉清。","心許陶家醉，詩逢謝客呈。","應憐末行吏，曾是魯諸生。"]', '["高柳满春城，东园有鸟声。","折花朝露滴，漱石野泉清。","心許陶家醉，诗逢謝客呈。","應怜末行吏，曾是魯諸生。"]', '诗', 'shi', '', NULL, '春日過李侍御 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b05a92e-9007-448e-9ba1-69f8f5adfb84', '出山逢耿湋', '出山逢耿湋', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲雪離披山萬里，別來曾住最高峰。","暫到人間歸不得，長安陌上又相逢。"]', '["云雪離披山万里，別来曾住最高峰。","暫到人间归不得，长安陌上又相逢。"]', '诗', 'shi', '', NULL, '出山逢耿湋 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4654a06-5fba-4ba0-9957-82ddd3ca77bb', '題金吾郭將軍石伏茅堂', '題金吾郭將軍石伏茅堂', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲戟曙沈沈，軒墀清且深。","家傳成棟美，堯寵結茅心。","玉佩多依石，油幢亦在林。","爐香諸洞暖，殿影衆山陰。","草奏風生筆，筵開雪滿琴。","客從龍闕至，僧自虎溪尋。","蕭灑延清賞，風流會素襟。","終朝息塵步，一醉間華簪。"]', '["云戟曙沈沈，軒墀清且深。","家傳成棟美，堯寵結茅心。","玉佩多依石，油幢亦在林。","爐香諸洞暖，殿影衆山陰。","草奏风生笔，筵开雪满琴。","客從龙闕至，僧自虎溪尋。","蕭灑延清賞，风流會素襟。","終朝息塵步，一醉间华簪。"]', '诗', 'shi', '', NULL, '題金吾郭將軍石伏茅堂 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c41b9e42-1d4c-4670-8488-88ee2f887cc4', '題賈山人園林', '題賈山人园林', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["竹影朦朧松影長，素琴清簟好風涼。","連春詩會煙花滿，半夜酒醒蘭蕙香。","五字每將稱玉友，一尊曾不顧金囊。","長沙流謫君非遠，莫遣英名負洛陽。"]', '["竹影朦朧松影长，素琴清簟好风涼。","連春诗會煙花满，半夜酒醒蘭蕙香。","五字每將稱玉友，一尊曾不顧金囊。","长沙流謫君非远，莫遣英名負洛陽。"]', '诗', 'shi', '', NULL, '題賈山人園林 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f895e219-77e0-401e-a8e2-66f105ac7f60', '秋夜同暢當宿藏公院', '秋夜同暢當宿藏公院', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["禮足一垂淚，醫王知病由。","風螢方喜夜，露槿已傷秋。","顧以兒童愛，每從仁者求。","將祈竟何得，滅跡在緇流。"]', '["禮足一垂泪，醫王知病由。","风螢方喜夜，露槿已傷秋。","顧以兒童愛，每從仁者求。","將祈竟何得，滅跡在緇流。"]', '诗', 'shi', '', NULL, '秋夜同暢當宿藏公院 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8146d939-bf5f-4866-9216-20e78ee0808b', '重同暢當奘公院聞琴', '重同暢當奘公院闻琴', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["悞以音聲祈遠公，請將徽軫付秋風。","漾漾硤流吹不盡，月華如在白波中。"]', '["悞以音声祈远公，請將徽軫付秋风。","漾漾硤流吹不尽，月华如在白波中。"]', '诗', 'shi', '', NULL, '重同暢當奘公院聞琴 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea84eeff-95f0-4013-a68c-12fe776e74e9', '同耿湋宿陸澧旅舍', '同耿湋宿陸澧旅舍', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["當軒雲月開，清夜故人桮。","擁褐覺霜下，抱琴聞鴈來。","迎風君顧步，臨路我遲迴。","雙鬢共如此，此懽非易陪。"]', '["當軒云月开，清夜故人桮。","擁褐覺霜下，抱琴闻鴈来。","迎风君顧步，臨路我遲迴。","雙鬢共如此，此懽非易陪。"]', '诗', 'shi', '', NULL, '同耿湋宿陸澧旅舍 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bec6ec5-bac0-4fc3-9c26-c1ef63cd1d0a', '題苗員外竹間亭', '題苗員外竹间亭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高甃絕行塵，開簾似有春。","風傾竹上雪，山對酒邊人。","步暖先逢日，書空遠見鄰。","還同內齋暇，登賞及諸姻。"]', '["高甃絕行塵，开簾似有春。","风傾竹上雪，山对酒邊人。","步暖先逢日，书空远见鄰。","還同內斋暇，登賞及諸姻。"]', '诗', 'shi', '', NULL, '題苗員外竹間亭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce177fb4-f5f7-4f41-b4c8-d9721f8b26cf', '奉陪侍中登白樓', '奉陪侍中登白楼', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高樓倚玉梯，朱檻與雲齊。","顧盼親霄漢，談諧息鼓鼙。","洪河斜更直，野雨急仍低。","今日陪尊俎，唯當醉似泥。"]', '["高楼倚玉梯，朱檻與云齊。","顧盼親霄漢，談諧息鼓鼙。","洪河斜更直，野雨急仍低。","今日陪尊俎，唯當醉似泥。"]', '诗', 'shi', '', NULL, '奉陪侍中登白樓 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('390ef3f6-deb4-4314-80b7-6603639ce19a', '九日奉陪侍郎登白樓', '九日奉陪侍郎登白楼', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["碧霄孤鶴發清音，上宰因添望闕心。","睥睨三層連步障，茱萸一朵映華簪。","紅霞似綺河如帶，白露團珠菊散金。","此日所從何所問，儼然冠劍擁成林。"]', '["碧霄孤鹤發清音，上宰因添望闕心。","睥睨三層連步障，茱萸一朵映华簪。","紅霞似綺河如带，白露團珠菊散金。","此日所從何所问，儼然冠劍擁成林。"]', '诗', 'shi', '', NULL, '九日奉陪侍郎登白樓 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50d2c736-138a-4997-86dd-687edad966a0', '春日喜雨奉和馬侍中宴白樓', '春日喜雨奉和马侍中宴白楼', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鸛鶴相呼綠野寬，鼎臣閑倚玉欄干。","洪河擁沫流仍急，蒼嶺和雲色更寒。","豔豔風光呈瑞歲，泠泠歌頌振琱盤。","今朝醉舞共鄉老，不覺傾欹獬豸冠。"]', '["鸛鹤相呼綠野寬，鼎臣闲倚玉欄干。","洪河擁沫流仍急，蒼嶺和云色更寒。","豔豔风光呈瑞歲，泠泠歌頌振琱盤。","今朝醉舞共乡老，不覺傾欹獬豸冠。"]', '诗', 'shi', '', NULL, '春日喜雨奉和馬侍中宴白樓 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36534c86-ee76-44e0-88ab-a7c682f052d9', '奉陪侍中遊石笋溪十二韻', '奉陪侍中游石笋溪十二韻', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["朝日照靈山，山溪浩紛錯。","圖書無舊記，鯀禹應新鑿。","雙壁瀉天河，一峰吐蓮萼。","潭心亂雪卷，嵓腹繁珠落。","彩蛤攢錦囊，芳蘿嫋花索。","猨羣曝陽嶺，龍穴腥陰壑。","靜得漁者言，閑聞洞仙博。","欹松倚朱幰，廣石屯油幕。","國泰事留侯，山春縱康樂。","間關殊狀鳥，爛熳無名藥。","欲驗少君方，還吟大隱作。","旌幢不可駐，古塞新沙漠。"]', '["朝日照靈山，山溪浩紛錯。","圖书無旧記，鯀禹應新鑿。","雙壁瀉天河，一峰吐蓮萼。","潭心亂雪卷，嵓腹繁珠落。","彩蛤攢錦囊，芳蘿嫋花索。","猨羣曝陽嶺，龙穴腥陰壑。","静得漁者言，闲闻洞仙博。","欹松倚朱幰，廣石屯油幕。","国泰事留侯，山春縱康乐。","间关殊狀鸟，爛熳無名藥。","欲驗少君方，還吟大隐作。","旌幢不可駐，古塞新沙漠。"]', '诗', 'shi', '', NULL, '奉陪侍中遊石笋溪十二韻 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5a8a19-778e-4be1-8298-06a118996ada', '九日奉陪侍中宴白樓', '九日奉陪侍中宴白楼', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["露白菊氛氳，西樓盛襲文。","玉筵秋令節，金鉞漢元勳。","說劍風生座，抽琴鶴遶雲。","謏儒無以荅，願得備前軍。"]', '["露白菊氛氳，西楼盛襲文。","玉筵秋令節，金鉞漢元勳。","说劍风生座，抽琴鹤遶云。","謏儒無以荅，願得備前軍。"]', '诗', 'shi', '', NULL, '九日奉陪侍中宴白樓 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e996578-5146-498d-be5f-60db1a241d10', '九日奉陪侍中宴後亭', '九日奉陪侍中宴後亭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉壺傾菊酒，一顧得淹留。","彩筆徵枚叟，花筵舞莫愁。","管弦能駐景，松桂不停秋。","爲謝蓬蒿輩，如何霜霰稠。"]', '["玉壺傾菊酒，一顧得淹留。","彩笔徵枚叟，花筵舞莫愁。","管弦能駐景，松桂不停秋。","爲謝蓬蒿輩，如何霜霰稠。"]', '诗', 'shi', '', NULL, '九日奉陪侍中宴後亭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1fdef6-f900-4fbc-8542-43c3cdd6eab7', '九日奉陪令公登白樓同詠菊', '九日奉陪令公登白楼同詠菊', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["瓊尊猶有菊，可以獻留侯。","願比三花秀，非同百卉秋。","金英分蘂細，玉露結房稠。","黃雀知恩在，銜飛亦上樓。"]', '["瓊尊猶有菊，可以獻留侯。","願比三花秀，非同百卉秋。","金英分蘂細，玉露結房稠。","黄雀知恩在，銜飞亦上楼。"]', '诗', 'shi', '', NULL, '九日奉陪令公登白樓同詠菊 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8850438a-1e84-4df0-910c-08684407652a', '奉陪渾侍中上巳日泛渭河', '奉陪渾侍中上巳日泛渭河', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["青舸錦帆開，浮天接上台。","晚鶯和玉笛，春浪動金罍。","舟檝方朝海，鯨鯢自曝腮。","應憐似萍者，空逐榜人回。"]', '["青舸錦帆开，浮天接上台。","晚鶯和玉笛，春浪动金罍。","舟檝方朝海，鯨鯢自曝腮。","應怜似萍者，空逐榜人回。"]', '诗', 'shi', '', NULL, '奉陪渾侍中上巳日泛渭河 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b524fd-d865-49c7-9c91-25375f7fd9d5', '奉陪侍中春日過武安君廟', '奉陪侍中春日過武安君廟', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["長裾間貔虎，遺廟盛攀登。","白羽三千騎，紅林一萬層。","元臣達幽契，祝史告明徵。","撫坐悲今古，瞻容感廢興。","迴風卷藂栢，驟雨濕諸陵。","倏忽煙花霽，當營看月生。"]', '["长裾间貔虎，遺廟盛攀登。","白羽三千騎，紅林一万層。","元臣達幽契，祝史告明徵。","撫坐悲今古，瞻容感廢兴。","迴风卷藂栢，驟雨濕諸陵。","倏忽煙花霽，當營看月生。"]', '诗', 'shi', '', NULL, '奉陪侍中春日過武安君廟 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b60a93e-e8d1-42fd-a650-0fdcf911cd33', '過玉[真]公主影殿', '過玉[真]公主影殿', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["夕照臨窗起暗塵，青松繞殿不知春。","君看白髮誦經者，半是宮中歌舞人。"]', '["夕照臨窗起暗塵，青松繞殿不知春。","君看白髮誦經者，半是宮中歌舞人。"]', '诗', 'shi', '', NULL, '過玉[真]公主影殿 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03f1cdd-2f8b-45b0-adfc-6cbbd85fcf44', '題嘉祥殿南溪印禪師壁畫影堂', '題嘉祥殿南溪印禪師壁畫影堂', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雙屐參差錫杖斜，衲衣交膝對天花。","瞻容悟問修持劫，似指前溪無數沙。"]', '["雙屐參差錫杖斜，衲衣交膝对天花。","瞻容悟问修持劫，似指前溪無數沙。"]', '诗', 'shi', '', NULL, '題嘉祥殿南溪印禪師壁畫影堂 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2684095-6f5c-47ed-9950-a38e96c24156', '題伯夷廟', '題伯夷廟', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["中條山下黃礓石，壘作夷齊廟裏神。","落葉滿堦塵滿座，不知澆酒爲何人。"]', '["中條山下黄礓石，壘作夷齊廟裏神。","落葉满堦塵满座，不知澆酒爲何人。"]', '诗', 'shi', '', NULL, '題伯夷廟 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d741dfa2-f686-4dd7-be3d-9a60077fd371', '早春遊樊川野居却寄李端校書兼呈崔峒補闕司空曙主簿耿湋拾遺', '早春游樊川野居却寄李端校书兼呈崔峒補闕司空曙主簿耿湋拾遺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["白水遍溝堘，青山對杜陵。","晴明人望鶴，曠野鹿隨僧。","古柳連巢折，荒堤帶草崩。","陰橋全覆雪，瀑溜半垂冰。","鬬鼠搖松影，遊龜落石層。","韶光偏不待，衰敗巧相仍。","桂樹曾爭折，龍門幾共登。","琴師阮校尉，詩和柳吳興。","舐筆求書扇，張屏看畫蠅。","卜鄰空遂約，問卦獨無徵。","投足經危路，收才遇直繩。","守農窮自固，行樂病何能。","掩帙蓬蒿晚，臨川景氣澄。","颯然成一叟，誰更慕騫騰。"]', '["白水遍溝堘，青山对杜陵。","晴明人望鹤，曠野鹿隨僧。","古柳連巢折，荒堤带草崩。","陰橋全覆雪，瀑溜半垂冰。","鬬鼠搖松影，游龟落石層。","韶光偏不待，衰敗巧相仍。","桂樹曾爭折，龙门幾共登。","琴師阮校尉，诗和柳吳兴。","舐笔求书扇，張屏看畫蠅。","卜鄰空遂約，问卦独無徵。","投足經危路，收才遇直繩。","守農窮自固，行乐病何能。","掩帙蓬蒿晚，臨川景氣澄。","颯然成一叟，誰更慕騫腾。"]', '诗', 'shi', '', NULL, '早春遊樊川野居却寄李端校書兼呈崔峒補闕司空曙主簿耿湋拾遺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e5874b-7c28-4b1b-b4b9-b5aacb5c8bb1', '同錢郎中晚春過慈恩寺', '同錢郎中晚春過慈恩寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["不見僧中舊，仍逢雨後春。","惜花將愛寺，俱是白頭人。"]', '["不见僧中旧，仍逢雨後春。","惜花將愛寺，俱是白头人。"]', '诗', 'shi', '', NULL, '同錢郎中晚春過慈恩寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d77a6c-e09f-48a5-ab62-2dca745fa59d', '曲江春望 一', '曲江春望 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["菖蒲飜葉柳交枝，暗上蓮舟鳥不知。","更到無花最深處，玉樓金殿影參差。"]', '["菖蒲飜葉柳交枝，暗上蓮舟鸟不知。","更到無花最深处，玉楼金殿影參差。"]', '诗', 'shi', '', NULL, '曲江春望 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd29a52-42a8-470f-b8b5-a5108ebe4a8e', '曲江春望 二', '曲江春望 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["翠黛紅粧畫鷁中，共驚雲色帶微風。","簫管曲長吹未盡，花南水北雨濛濛。"]', '["翠黛紅粧畫鷁中，共驚云色带微风。","簫管曲长吹未尽，花南水北雨濛濛。"]', '诗', 'shi', '', NULL, '曲江春望 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b5cac2-ccf5-4765-92c2-ffef34039480', '曲江春望 三', '曲江春望 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["泉聲遍野入芳洲，擁沫吹花草上流。","落日行人漸無路，巢烏乳燕滿高樓。"]', '["泉声遍野入芳洲，擁沫吹花草上流。","落日行人漸無路，巢烏乳燕满高楼。"]', '诗', 'shi', '', NULL, '曲江春望 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3edd72-f585-43a7-b9bd-fc7d08ec5e8b', '春日陪李庶子遵善寺東院曉望', '春日陪李庶子遵善寺东院晓望', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["映竹水田分，當山起鴈羣。","陽峰高對寺，陰井下通雲。","雪晝唯逢鶴，花時此見君。","由來禪誦地，多有謝公文。"]', '["映竹水田分，當山起鴈羣。","陽峰高对寺，陰井下通云。","雪晝唯逢鹤，花时此见君。","由来禪誦地，多有謝公文。"]', '诗', 'shi', '', NULL, '春日陪李庶子遵善寺東院曉望 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967b8be5-0c22-4b50-a5b5-413ccfa8781d', '華清宮 一', '华清宮 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["漢家天子好經過，白日青山宮殿多。","見說只今生草處，禁泉荒石已相和。"]', '["漢家天子好經過，白日青山宮殿多。","见说只今生草处，禁泉荒石已相和。"]', '诗', 'shi', '', NULL, '華清宮 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8235c933-4770-43e6-a451-9a6053db5ffb', '華清宮 二', '华清宮 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["水氣朦朧滿畫梁，一迴開殿滿山香。","宮娃幾許經歌舞，白首翻令憶建章。"]', '["水氣朦朧满畫梁，一迴开殿满山香。","宮娃幾許經歌舞，白首翻令憶建章。"]', '诗', 'shi', '', NULL, '華清宮 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac6b68c-0089-4377-9105-9792eff20509', '題興善寺後池', '題兴善寺後池', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["隔窗棲白鶴，似與鏡湖鄰。","月照何年樹，花逢幾遍人。","岸莎青有路，苔徑綠無塵。","永願容依止，僧中老此身。"]', '["隔窗棲白鹤，似與镜湖鄰。","月照何年樹，花逢幾遍人。","岸莎青有路，苔徑綠無塵。","永願容依止，僧中老此身。"]', '诗', 'shi', '', NULL, '題興善寺後池 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3a1e4c-6c93-48e3-84bd-7f16820ef72f', '陪中書李紓舍人夜泛東池', '陪中书李紓舍人夜泛东池', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["看月復聽琴，移舟出樹陰。","夜村機杼急，秋水芰荷深。","石靜龜潛上，萍開果暗沈。","何言奉杯酒，得見五湖心。"]', '["看月复听琴，移舟出樹陰。","夜村機杼急，秋水芰荷深。","石静龟潛上，萍开果暗沈。","何言奉杯酒，得见五湖心。"]', '诗', 'shi', '', NULL, '陪中書李紓舍人夜泛東池 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5457e6-fca7-481b-9ae1-bb2f00266eb5', '宴趙氏昆季書院因與會文幷率爾投贈', '宴趙氏昆季书院因與會文幷率爾投贈', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["詩禮挹餘波，相懽在琢磨。","琴尊方會集，珠玉忽駢羅。","謝族風流盛，于門福慶多。","花攢騏驥櫪，錦絢鳳凰窠。","詠雪因饒妹，書經爲愛鵝。","仍聞廣練被，更有遠儒過。"]', '["诗禮挹餘波，相懽在琢磨。","琴尊方會集，珠玉忽駢羅。","謝族风流盛，于门福慶多。","花攢騏驥櫪，錦絢鳳凰窠。","詠雪因饒妹，书經爲愛鵝。","仍闻廣練被，更有远儒過。"]', '诗', 'shi', '', NULL, '宴趙氏昆季書院因與會文幷率爾投贈 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b9e95f6-5336-4b11-b52d-7be1ed7e9fd2', '題天華觀', '題天华观', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["峰嶂徘徊霞景新，一潭寒水絕纖鱗。","朱字靈書千萬軸，蒼髯道士兩三人。","芝童解說壺中事，玉管能留天上春。","眼見仙丹求不得，漢家簪紱在羸身。"]', '["峰嶂徘徊霞景新，一潭寒水絕纖鱗。","朱字靈书千万軸，蒼髯道士兩三人。","芝童解说壺中事，玉管能留天上春。","眼见仙丹求不得，漢家簪紱在羸身。"]', '诗', 'shi', '', NULL, '題天華觀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e254317e-0b37-455b-80dd-7e78ddd2f518', '宿石甕寺', '宿石甕寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["殿有寒燈草有螢，千林萬壑寂無聲。","烟凝積水龍蛇蟄，露濕空山星漢明。","昏靄霧中悲世界，曙霞光裏見王城。","迴瞻相好因垂淚，苦海波濤何日平。"]', '["殿有寒灯草有螢，千林万壑寂無声。","烟凝積水龙蛇蟄，露濕空山星漢明。","昏靄霧中悲世界，曙霞光裏见王城。","迴瞻相好因垂泪，苦海波濤何日平。"]', '诗', 'shi', '', NULL, '宿石甕寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e181d6-bcec-4b0e-8128-8345f2a0793e', '題悟真寺', '題悟真寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["萬峯交掩一峰開，曉色常從天上來。","似到西方諸佛國，蓮花影裏數樓臺。"]', '["万峯交掩一峰开，晓色常從天上来。","似到西方諸佛国，蓮花影裏數楼台。"]', '诗', 'shi', '', NULL, '題悟真寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('507c8bf7-2f91-4ee5-9849-118d47567db3', '題雲際寺上方', '題云際寺上方', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["松高蘿蔓輕，中有石牀平。","下界水長急，上方燈自明。","空門不易啓，初地本無程。","迴步忽山盡，萬緣從此生。"]', '["松高蘿蔓轻，中有石牀平。","下界水长急，上方灯自明。","空门不易啓，初地本無程。","迴步忽山尽，万緣從此生。"]', '诗', 'shi', '', NULL, '題雲際寺上方 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('814b7a6c-d3a8-49c6-8166-82839b954c03', '九日同司直九叔崔侍御登寶雞南樓', '九日同司直九叔崔侍御登寶雞南楼', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["把菊歎將老，上樓悲未還。","短長新白髮，重疊舊青山。","霜氣清衿袖，琴聲引醉顏。","竹林唯七友，何幸亦登攀。"]', '["把菊歎將老，上楼悲未還。","短长新白髮，重叠旧青山。","霜氣清衿袖，琴声引醉顏。","竹林唯七友，何幸亦登攀。"]', '诗', 'shi', '', NULL, '九日同司直九叔崔侍御登寶雞南樓 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcf88d70-488c-40a7-b7bf-febc7ab7c797', '同王員外雨後登開元寺南樓因寄西巖警上人', '同王員外雨後登开元寺南楼因寄西巖警上人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["過雨開樓看晚虹，白雲相逐水相通。","寒蟬噪暮野無日，古樹傷秋天有風。","數穗遠煙凝壠上，一枝繁果憶山中。","何言暫別東林友，惆悵人間事不同。"]', '["過雨开楼看晚虹，白云相逐水相通。","寒蟬噪暮野無日，古樹傷秋天有风。","數穗远煙凝壠上，一枝繁果憶山中。","何言暫別东林友，惆悵人间事不同。"]', '诗', 'shi', '', NULL, '同王員外雨後登開元寺南樓因寄西巖警上人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e2c3ead-9db7-4794-a163-eb9068df4f7e', '同趙進馬元陽春日登長春宮古城望河中因寄鄭損倉曹', '同趙進马元陽春日登长春宮古城望河中因寄鄭損倉曹', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["城頭春靄曉濛濛，指望關橋滿袖風。","雲騎閑嘶宮柳外，玉人愁立草花中。","鐘分寺路山光綠，河繞軍州日氣紅。","跡忝已成方戀賞，此時離恨與君同。"]', '["城头春靄晓濛濛，指望关橋满袖风。","云騎闲嘶宮柳外，玉人愁立草花中。","鐘分寺路山光綠，河繞軍州日氣紅。","跡忝已成方戀賞，此时離恨與君同。"]', '诗', 'shi', '', NULL, '同趙進馬元陽春日登長春宮古城望河中因寄鄭損倉曹 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dd839a3-a410-4f62-adf6-f4e991320d05', '同崔峒補闕慈恩寺避暑', '同崔峒補闕慈恩寺避暑', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["寺涼高樹合，臥石綠陰中。","伴鶴慙僊侶，依僧學老翁。","魚沈荷葉露，鳥散竹林風。","始悟塵居者，應將火宅同。"]', '["寺涼高樹合，臥石綠陰中。","伴鹤慙僊侶，依僧学老翁。","鱼沈荷葉露，鸟散竹林风。","始悟塵居者，應將火宅同。"]', '诗', 'shi', '', NULL, '同崔峒補闕慈恩寺避暑 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b294c9-0f25-43d0-80bd-33b10735013f', '春日登樓有懷', '春日登楼有懷', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["花正濃時人正愁，逢花却欲替花羞。","年來笑伴皆歸去，今日晴明獨上樓。"]', '["花正濃时人正愁，逢花却欲替花羞。","年来笑伴皆归去，今日晴明独上楼。"]', '诗', 'shi', '', NULL, '春日登樓有懷 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584ceb64-f0cf-4ac3-a353-922b9fe4df37', '長安春望', '长安春望', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["東風吹雨過青山，却望千門草色閑。","家在夢中何日到，春生江上幾人還。","川原繚繞浮雲外，宮闕參差落照間。","誰念爲儒逢世難，獨將衰鬢客秦關。"]', '["东风吹雨過青山，却望千门草色闲。","家在梦中何日到，春生江上幾人還。","川原繚繞浮云外，宮闕參差落照间。","誰念爲儒逢世难，独將衰鬢客秦关。"]', '诗', 'shi', '', NULL, '長安春望 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331717a0-f3ea-4ed4-a496-75786a54add0', '冬日登城樓有懷因贈程騰', '冬日登城楼有懷因贈程腾', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["生涯何事多羈束，賴此登臨暢心目。","郭南郭北無數山，萬井逶迤流水間。","彈琴對酒不知暮，岸幘題詩身自閑。","風聲肅肅鴈飛絕，雲色茫茫欲成雪。","遙思海客天外歸，坐想征人兩頭別。","世情多以風塵隔，泣盡無因畫籌策。","誰知白首窗下人，不接朱門坐中客。","賤亦不足歎，貴亦不足陳。","長卿未遇楊朱泣，蔡澤無媒原憲貧。","如今萬乘方用武，國命天威借貔虎。","窮達皆爲身外名，公侯可廢刀頭取。","君不見漢家邊將在邊庭，白羽三千出井陘。","當風看獵擁珠翠，豈在終年窮一經。"]', '["生涯何事多羈束，賴此登臨暢心目。","郭南郭北無數山，万井逶迤流水间。","彈琴对酒不知暮，岸幘題诗身自闲。","风声肅肅鴈飞絕，云色茫茫欲成雪。","遙思海客天外归，坐想征人兩头別。","世情多以风塵隔，泣尽無因畫籌策。","誰知白首窗下人，不接朱门坐中客。","賤亦不足歎，貴亦不足陳。","长卿未遇楊朱泣，蔡澤無媒原憲貧。","如今万乘方用武，国命天威借貔虎。","窮達皆爲身外名，公侯可廢刀头取。","君不见漢家邊將在邊庭，白羽三千出井陘。","當风看獵擁珠翠，豈在終年窮一經。"]', '诗', 'shi', '', NULL, '冬日登城樓有懷因贈程騰 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('074be5cc-8238-4abc-8d7a-8e99aaf09e8a', '過仙遊寺', '過仙游寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["上方下方雪中路，白雲流水如閑步。","數峰行盡猶未歸，寂寞經聲竹陰暮。"]', '["上方下方雪中路，白云流水如闲步。","數峰行尽猶未归，寂寞經声竹陰暮。"]', '诗', 'shi', '', NULL, '過仙遊寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c856ebd-7d5a-4bda-83e4-4d4489ee133f', '同路郎中韓侍御春日題野寺', '同路郎中韓侍御春日題野寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["寺前山遠古陂寬，寺裏人稀春草寒。","何事最堪悲色相，折花將與老僧看。"]', '["寺前山远古陂寬，寺裏人稀春草寒。","何事最堪悲色相，折花將與老僧看。"]', '诗', 'shi', '', NULL, '同路郎中韓侍御春日題野寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e7eab5-45c4-40db-9181-579644ec9319', '奉和李益遊栖巖寺', '奉和李益游栖巖寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["林香雨氣新，山寺綠無塵。","遂結雲外賞，共遊天上春。","鶴鳴金闕麗，僧語竹房鄰。","待月水流急，惜花風起頻。","何方非壞境，此地有歸人。","迴首空門路，皤然一幻身。"]', '["林香雨氣新，山寺綠無塵。","遂結云外賞，共游天上春。","鹤鳴金闕丽，僧語竹房鄰。","待月水流急，惜花风起頻。","何方非壞境，此地有归人。","迴首空门路，皤然一幻身。"]', '诗', 'shi', '', NULL, '奉和李益遊栖巖寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1104b2-9609-4824-ba0a-3680acb44f5c', '秋夜同暢當宿潭上西亭', '秋夜同暢當宿潭上西亭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["圓月出山頭，七賢林下遊。","梢梢寒葉墜，灩灩月波流。","鳧鵠共思曉，菰蒲相與秋。","明當此中別，一爲望汀洲。"]', '["圓月出山头，七賢林下游。","梢梢寒葉墜，灩灩月波流。","鳧鵠共思晓，菰蒲相與秋。","明當此中別，一爲望汀洲。"]', '诗', 'shi', '', NULL, '秋夜同暢當宿潭上西亭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aae5d437-93ed-47e5-9f38-ea37b07ca0d0', '山中一絕', '山中一絕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["飢食松花渴飲泉，偶從山後到山前。","陽坡軟草厚如織，因與鹿麛相伴眠。"]', '["飢食松花渴饮泉，偶從山後到山前。","陽坡軟草厚如织，因與鹿麛相伴眠。"]', '诗', 'shi', '', NULL, '山中一絕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71fa681-8a48-4641-ba97-d18e5fec888a', '與暢當夜泛秋潭', '與暢當夜泛秋潭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["螢火颺蓮叢，水涼多夜風。","離人將落葉，俱在一船中。"]', '["螢火颺蓮叢，水涼多夜风。","離人將落葉，俱在一船中。"]', '诗', 'shi', '', NULL, '與暢當夜泛秋潭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6e69558-07fd-4006-9af0-7d1acd2881ad', '秋夜宴集陳翃郎中圃亭美校書郎張正元歸鄉', '秋夜宴集陳翃郎中圃亭美校书郎張正元归乡', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["泉清蘭菊稠，紅果落城溝。","保慶臺榭古，感時琴瑟秋。","碩儒歡頗至，名士禮能周。","爲謝邑中少，無驚池上鷗。"]', '["泉清蘭菊稠，紅果落城溝。","保慶台榭古，感时琴瑟秋。","碩儒歡頗至，名士禮能周。","爲謝邑中少，無驚池上鷗。"]', '诗', 'shi', '', NULL, '秋夜宴集陳翃郎中圃亭美校書郎張正元歸鄉 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2286a23a-2f64-4c07-8b16-b0197951c174', '春遊東潭', '春游东潭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["移舟試望家，漾漾似天涯。","日暮滿潭雪，白鷗和柳花。"]', '["移舟試望家，漾漾似天涯。","日暮满潭雪，白鷗和柳花。"]', '诗', 'shi', '', NULL, '春遊東潭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502e2867-98a2-4e87-8a7b-a4b253c9ac36', '同薛存誠登栖巖寺', '同薛存誠登栖巖寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["衰蹇步難前，上山如上天。","塵泥來自晚，猨鶴到何先。","萬壑應孤磬，百花通一泉。","蒼蒼此明月，下界正沈眠。"]', '["衰蹇步难前，上山如上天。","塵泥来自晚，猨鹤到何先。","万壑應孤磬，百花通一泉。","蒼蒼此明月，下界正沈眠。"]', '诗', 'shi', '', NULL, '同薛存誠登栖巖寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c077aa12-36d4-4881-92ed-c3836023cab8', '河中府崇福寺看花', '河中府崇福寺看花', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["聞道山花如火紅，平明登寺已經風。","老僧無見亦無說，應與看人心不同。"]', '["闻道山花如火紅，平明登寺已經风。","老僧無见亦無说，應與看人心不同。"]', '诗', 'shi', '', NULL, '河中府崇福寺看花 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d9bfae7-0969-4230-959d-e668e926a474', '冬日宴郭監林亭', '冬日宴郭監林亭', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉勒聚如雲，森森鸞鶴羣。","據梧花罽接，沃盥石泉分。","華味慙初識，新聲喜盡聞。","此山招老賤，敢不謝夫君。"]', '["玉勒聚如云，森森鸾鹤羣。","據梧花罽接，沃盥石泉分。","华味慙初識，新声喜尽闻。","此山招老賤，敢不謝夫君。"]', '诗', 'shi', '', NULL, '冬日宴郭監林亭 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d406ba9-ada0-4d04-a7c4-349cc4f486fb', '奉和李舍人昆季詠玫瑰花寄贈徐侍郎', '奉和李舍人昆季詠玫瑰花寄贈徐侍郎', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["獨鶴寄煙霜，雙鸞思晚芳。","舊陰依謝宅，新豔出蕭牆。","蝶散搖輕露，鶯銜入夕陽。","雨朝勝濯錦，風夜劇焚香。","斷日千層豔，孤霞一片光。","密來驚葉少，動處覺枝長。","布影期高賞，留春爲遠方。","嘗聞贈瓊玖，叨和愧升堂。"]', '["独鹤寄煙霜，雙鸾思晚芳。","旧陰依謝宅，新豔出蕭牆。","蝶散搖轻露，鶯銜入夕陽。","雨朝勝濯錦，风夜劇焚香。","斷日千層豔，孤霞一片光。","密来驚葉少，动处覺枝长。","布影期高賞，留春爲远方。","嘗闻贈瓊玖，叨和愧升堂。"]', '诗', 'shi', '', NULL, '奉和李舍人昆季詠玫瑰花寄贈徐侍郎 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cff4821-416d-4899-bf9d-fd1020452c94', '同耿湋司空曙二拾遺題韋員外東齋花樹', '同耿湋司空曙二拾遺題韋員外东斋花樹', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["綠砌紅花樹，狂風獨未吹。","光中疑有燄，密處似無枝。","鳥動香輕發，人愁影屢移。","今朝數片落，爲報漢郎知。"]', '["綠砌紅花樹，狂风独未吹。","光中疑有燄，密处似無枝。","鸟动香轻發，人愁影屢移。","今朝數片落，爲報漢郎知。"]', '诗', 'shi', '', NULL, '同耿湋司空曙二拾遺題韋員外東齋花樹 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311a0b0d-e31a-46d4-8524-10a809e299b6', '觀袁修侍郎漲新池', '观袁修侍郎漲新池', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["引水香山近，穿雲復遶林。","纔聞籬外響，已覺石邊深。","滿處侵苔色，澄來見柳陰。","微風月明夜，知有五湖心。"]', '["引水香山近，穿云复遶林。","纔闻籬外响，已覺石邊深。","满处侵苔色，澄来见柳陰。","微风月明夜，知有五湖心。"]', '诗', 'shi', '', NULL, '觀袁修侍郎漲新池 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea2ee88a-1def-4bda-833b-762f75314d5d', '和徐法曹贈崔洛陽斑竹杖以詩見荅', '和徐法曹贈崔洛陽斑竹杖以诗见荅', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉幹一尋餘，苔花錦不如。","勁堪和醉倚，輕好向空書。","采拂稽山曲，因依釋氏居。","方辰將獨步，豈與此君疎。"]', '["玉幹一尋餘，苔花錦不如。","勁堪和醉倚，轻好向空书。","采拂稽山曲，因依釋氏居。","方辰將独步，豈與此君疎。"]', '诗', 'shi', '', NULL, '和徐法曹贈崔洛陽斑竹杖以詩見荅 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59271a8-1f19-433e-b66f-4af6de7f383d', '早秋望華清宮中樹因以成詠', '早秋望华清宮中樹因以成詠', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["可憐雲木藂，滿禁碧濛濛。","色潤靈泉近，陰清輦路通。","玉壇標八桂，金井識雙桐。","交映凝寒露，相和起夜風。","數枝盤石上，幾葉落雲中。","燕拂宜秋霽，蟬鳴覺晝空。","翠屏更隱見，珠綴共玲瓏。","雷雨生成早，樵蘇禁令雄。","野藤高助綠，仙果迥呈紅。","惆悵繚垣暮，茲山聞暗蛩。"]', '["可怜云木藂，满禁碧濛濛。","色潤靈泉近，陰清輦路通。","玉壇標八桂，金井識雙桐。","交映凝寒露，相和起夜风。","數枝盤石上，幾葉落云中。","燕拂宜秋霽，蟬鳴覺晝空。","翠屏更隐见，珠綴共玲瓏。","雷雨生成早，樵蘇禁令雄。","野藤高助綠，仙果迥呈紅。","惆悵繚垣暮，茲山闻暗蛩。"]', '诗', 'shi', '', NULL, '早秋望華清宮中樹因以成詠 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55933b19-ff43-40e9-9579-56ad52c53ec3', '小魚詠寄涇州楊侍郎', '小鱼詠寄涇州楊侍郎', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["蓮花影裏暫相離，纔出浮萍值罟師。","上得龍門還失浪，九江何處是歸期。"]', '["蓮花影裏暫相離，纔出浮萍值罟師。","上得龙门還失浪，九江何处是归期。"]', '诗', 'shi', '', NULL, '小魚詠寄涇州楊侍郎 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('859029cc-5ab7-4855-9de7-68c231882523', '賊中與嚴越卿曲江看花', '賊中與嚴越卿曲江看花', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["紅枝欲折紫枝殷，隔水連宮不用攀。","會待長風吹落盡，始能開眼向青山。"]', '["紅枝欲折紫枝殷，隔水連宮不用攀。","會待长风吹落尽，始能开眼向青山。"]', '诗', 'shi', '', NULL, '賊中與嚴越卿曲江看花 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8faefeef-eb7b-4616-8d11-874633dee69d', '同暢當詠蒲團', '同暢當詠蒲團', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["團團錦花結，乃是前溪蒲。","擁坐稱儒褐，倚眠宜病夫。","唯當學禪寂，終老與之俱。"]', '["團團錦花結，乃是前溪蒲。","擁坐稱儒褐，倚眠宜病夫。","唯當学禪寂，終老與之俱。"]', '诗', 'shi', '', NULL, '同暢當詠蒲團 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35b59fb5-75cd-4bf0-ac6e-86b0dd9cb22a', '焦籬店醉題', '焦籬店醉題', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["洛下渠頭百卉新，滿筵歌笑獨傷春。","何須更弄邵翁伯，即我此身如此人。"]', '["洛下渠头百卉新，满筵歌笑独傷春。","何須更弄邵翁伯，即我此身如此人。"]', '诗', 'shi', '', NULL, '焦籬店醉題 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42cc8c7e-4053-4201-a328-74623b23f242', '陳翃中丞東齋賦白玉簪', '陳翃中丞东斋賦白玉簪', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["美矣新成太華峰，翠蓮枝折葉重重。","松陰滿澗閑飛鶴，潭影通雲暗上龍。","漠漠水香風頗馥，涓涓乳溜味何濃。","因聲遠報浮丘子，不奏登封時不容。"]', '["美矣新成太华峰，翠蓮枝折葉重重。","松陰满澗闲飞鹤，潭影通云暗上龙。","漠漠水香风頗馥，涓涓乳溜味何濃。","因声远報浮丘子，不奏登封时不容。"]', '诗', 'shi', '', NULL, '陳翃中丞東齋賦白玉簪 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767fa394-5a2e-4ccc-8be4-d4a4b71d6fa5', '新茶詠寄上西川相公二十三舅大夫二十舅', '新茶詠寄上西川相公二十三舅大夫二十舅', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["三獻蓬萊始一嘗，日調金鼎閱芳香。","貯之玉合才半餅，寄與阿連題數行。"]', '["三獻蓬萊始一嘗，日調金鼎閱芳香。","貯之玉合才半餅，寄與阿連題數行。"]', '诗', 'shi', '', NULL, '新茶詠寄上西川相公二十三舅大夫二十舅 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e54bd063-69d0-46b6-9605-a83abb8faa2b', '泊揚子江岸', '泊揚子江岸', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["山映南徐暮，千帆入古津。","魚驚出浦火，月照渡江人。","清鏡催雙鬢，滄波寄一身。","空憐莎草色，長接故園春。"]', '["山映南徐暮，千帆入古津。","鱼驚出浦火，月照渡江人。","清镜催雙鬢，滄波寄一身。","空怜莎草色，长接故园春。"]', '诗', 'shi', '', NULL, '泊揚子江岸 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae577a5-da28-4672-83ff-94c97ae2a4a4', '晚次鄂州', '晚次鄂州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲開遠見漢陽城，猶是孤帆一日程。","估客晝眠知浪靜，舟人夜語覺潮生。","三湘衰鬢逢秋色，萬里歸心對月明。","舊業已隨征戰盡，更堪江上鼓鼙聲。"]', '["云开远见漢陽城，猶是孤帆一日程。","估客晝眠知浪静，舟人夜語覺潮生。","三湘衰鬢逢秋色，万里归心对月明。","旧業已隨征戰尽，更堪江上鼓鼙声。"]', '诗', 'shi', '', NULL, '晚次鄂州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a854ae25-d815-46d8-b949-5b76c5eb4594', '夜投豐德寺謁海上人', '夜投豐德寺謁海上人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["半夜中峰有磬聲，偶逢樵者問山名。","上方月曉聞僧語，下路林疎見客行。","野鶴巢邊松最老，毒龍潛處水偏清。","願得遠公知姓字，焚香洗鉢過浮生。"]', '["半夜中峰有磬声，偶逢樵者问山名。","上方月晓闻僧語，下路林疎见客行。","野鹤巢邊松最老，毒龙潛处水偏清。","願得远公知姓字，焚香洗鉢過浮生。"]', '诗', 'shi', '', NULL, '夜投豐德寺謁海上人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6482fd9-283a-4d2c-a384-c56a0c5c5046', '江行次武昌縣', '江行次武昌縣', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["家寄五湖間，扁舟往復還。","年年生白髮，處處上青山。","去國空知遠，安身竟不閑。","更悲江畔柳，長是北人攀。"]', '["家寄五湖间，扁舟往复還。","年年生白髮，处处上青山。","去国空知远，安身竟不闲。","更悲江畔柳，长是北人攀。"]', '诗', 'shi', '', NULL, '江行次武昌縣 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79046181-9ccc-498e-a1e0-555113a039f4', '夜泊金陵', '夜泊金陵', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["圓月出高城，蒼蒼照水營。","江中正吹笛，樓上又無更。","洛下仍傳箭，關西欲進兵。","誰知五湖外，諸將但爭名。"]', '["圓月出高城，蒼蒼照水營。","江中正吹笛，楼上又無更。","洛下仍傳箭，关西欲進兵。","誰知五湖外，諸將但爭名。"]', '诗', 'shi', '', NULL, '夜泊金陵 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e556ef-941e-4f51-be7d-7c635b0cd372', '渡浙江', '渡浙江', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["前船後船未相及，五兩頭平北風急。","飛沙卷地日色昏，一半征帆浪花濕。"]', '["前船後船未相及，五兩头平北风急。","飞沙卷地日色昏，一半征帆浪花濕。"]', '诗', 'shi', '', NULL, '渡浙江 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4301f96-e872-4eae-aa51-0d12328059d1', '李端公', '李端公', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["故關衰草遍，離別自堪悲。","路出寒雲外，人歸暮雪時。","少孤爲客早，多難識君遲。","掩淚空相向，風塵何處期。"]', '["故关衰草遍，離別自堪悲。","路出寒云外，人归暮雪时。","少孤爲客早，多难識君遲。","掩泪空相向，风塵何处期。"]', '诗', 'shi', '', NULL, '李端公 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('574ee2e4-2ebf-4d3a-9ee0-336beac25b92', '秋晚山中別業', '秋晚山中別業', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["樹老野泉清，幽人好獨行。","去閑知路靜，歸晚喜山明。","蘭芰通荒井，牛羊出古城。","茂陵秋最冷，誰念一書生。"]', '["樹老野泉清，幽人好独行。","去闲知路静，归晚喜山明。","蘭芰通荒井，牛羊出古城。","茂陵秋最冷，誰念一书生。"]', '诗', 'shi', '', NULL, '秋晚山中別業 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc62ad3d-4687-456b-beda-287839883f6a', '關口逢徐邁', '关口逢徐邁', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["廢寺連荒壘，那知見子真。","關城夜有雪，冰渡曉無人。","酒裏唯多病，山中願作鄰。","常聞兄弟樂，誰肯信家貧。"]', '["廢寺連荒壘，那知见子真。","关城夜有雪，冰渡晓無人。","酒裏唯多病，山中願作鄰。","常闻兄弟乐，誰肯信家貧。"]', '诗', 'shi', '', NULL, '關口逢徐邁 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57cf8e6-e45e-4d01-a101-87fbeef75b15', '山中詠古木', '山中詠古木', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["高木已蕭索，夜雨復秋風。","墜葉鳴藂竹，斜根擁斷蓬。","半侵山色裏，長在水聲中。","此地何人到，雲門去亦通。"]', '["高木已蕭索，夜雨复秋风。","墜葉鳴藂竹，斜根擁斷蓬。","半侵山色裏，长在水声中。","此地何人到，云门去亦通。"]', '诗', 'shi', '', NULL, '山中詠古木 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e2cc19c-6e43-47ad-834b-44694dc75180', '詶李端公野寺病居見寄', '詶李端公野寺病居见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["野寺鐘昏山正陰，亂藤高竹水聲深。","田夫就餉還依草，野雉驚飛不過林。","齋沫暫思同靜室，清羸已覺助禪心。","寂寞日長誰問疾，料君惟取古方尋。"]', '["野寺鐘昏山正陰，亂藤高竹水声深。","田夫就餉還依草，野雉驚飞不過林。","斋沫暫思同静室，清羸已覺助禪心。","寂寞日长誰问疾，料君惟取古方尋。"]', '诗', 'shi', '', NULL, '詶李端公野寺病居見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d3e1549-4887-4b3b-b8d3-4725128a32f0', '送少微上人遊蜀', '送少微上人游蜀', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["瓶鉢繞禪衣，連宵宿翠微。","樹開巴水遠，山曉蜀星稀。","識遍中朝貴，多諳外學非。","何當一傳付，道侶願知歸。"]', '["瓶鉢繞禪衣，連宵宿翠微。","樹开巴水远，山晓蜀星稀。","識遍中朝貴，多諳外学非。","何當一傳付，道侶願知归。"]', '诗', 'shi', '', NULL, '送少微上人遊蜀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7717b2-cc2b-46c0-a6b6-fbeaee2d9e7d', '送寧國夏侯丞', '送寧国夏侯丞', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["楚國青蕪上，秋雲似白波。","五湖長路少，九派亂山多。","謝守通詩宴，陶公許醉過。","憮然餞離阻，年鬢兩蹉跎。"]', '["楚国青蕪上，秋云似白波。","五湖长路少，九派亂山多。","謝守通诗宴，陶公許醉過。","憮然餞離阻，年鬢兩蹉跎。"]', '诗', 'shi', '', NULL, '送寧國夏侯丞 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be3da1b-06f3-4630-83a5-9bdd9940630b', '送袁偁', '送袁偁', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["諫獵名空久，多因病與貧。","買書行幾市，帶雨別何人。","客路山連水，軍州日映塵。","淒涼一分手，俱恨老相親。"]', '["諫獵名空久，多因病與貧。","買书行幾市，带雨別何人。","客路山連水，軍州日映塵。","淒涼一分手，俱恨老相親。"]', '诗', 'shi', '', NULL, '送袁偁 盧綸 shi');
